-- The Constitution of Nepal (second amendment, 2020), using the shared PostgreSQL JSONB schema.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODEx023def4c7e89$doc_const_2072_2nd_amendment_2020$CODEx023def4c7e89$,$CODEx396a63c738e4$The Constitution of Nepal$CODEx396a63c738e4$,$CODEx7757d743f8b6$नेपालको संविधान$CODEx7757d743f8b6$,$CODExef7573952f0b$constitution$CODExef7573952f0b$,2072,2015,202,$CODEx5eadb276c96f$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Preamble", "content": "The Constitution of Nepal\nDate of Publication in Nepal Gazette\nSeptember 20, 2015\nAmendments:", "children": []}, {"tier": 1, "nodeType": "part", "identifier": "Part-1", "title": "Preliminary", "content": "1. Constitution as Fundamental Law: (1) This Constitution is the fundamental law of\nNepal. Any law inconsistent with this  Constitution shall, to the extent of such\ninconsistency, be void.\n(2) It shall be the duty of every person to uphold this Constitution.\n2. Sovereignty and State Power: The sovereignty and State power of Nepal shall be\nvested in the Nepali people. It shall be exercised in accordance with the provisions set\nforth in this Constitution.", "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 1", "title": "The Constitution of Nepal (First Amendment), 2016", "content": null, "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 2", "title": "The Constitution of Nepal (Second Amendment), 2020", "content": "February 28, 2016\nJune 18, 2020\nPreamble:\nWE, THE SOVEREIGN PEOPLE OF NEPAL;\nINTERNALIZING the people's sovereign right and right to autonomy and self -rule, while\nmaintaining freedom, sovereignty, territorial integrity, national unity, independence and\ndignity of Nepal;\nRECALLING the glorious history of historic people's movements, armed struggle, dedication\nand sacrifice of Nepali people carried out , from time to time, for the s ake of interests of the\nnation, democracy and progressive changes, and respecting for the martyrs, disappeared\npersons and victimized citizens;\nELIMINA TING all forms of discrimination and oppression resulted from the feudalistic,\nautocratic, centralized, unitary system of governance of the State;\nPROTECTING and promoting unity in diversity, social and cultural solidarity, tolerance and\nharmony, by recognizing the multi -ethnic, multi -lingual, multi-religious, multi -cultural and\ngeographically diverse characteristics; and resolving to build an egalitarian society based on\nthe proportional inclusive and participatory principles in order to ensure econo mic equality,\nprosperity and social justice by eliminating discrimination based on class, caste, region,\nlanguage, religion and gender and all forms of caste-based untouchability;\nBEING COMMITTED  to socialism based on democratic norms and values including the\npeople's competitive multiparty democratic system of governance, civil liberties, fundamental\nrights, human rights, adult franchise, periodic elections, full  freedom of the press, and\nindependent, impartial and competent judiciary and concept of the ru le of law in order to\nbuild a prosperous nation;\nDESIRING to fulfil aspirations for sustainable peace, good governance, development and\nprosperity through the federal democratic republican system of governance;\nDO HEREBY ADOPT AND PROMULGA TE THIS CONSTI TUTION THROUGH THE\nCONSTITUENT ASSEMBLY .", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 3", "title": "Nation", "content": "All the Nepali people, with multi-ethnic, multi-lingual, multi-religious, multi-\ncultural characteristics and in geographical diversities, and having common aspirations\nand being united by a bond of allegiance to national independence, territorial integrity,\nnational interest and prosperity of Nepal, collectively constitute the nation.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 4", "title": "State of Nepal", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Nepal is an independent, indivisible, sovereign, secular, inclusive,\ndemocratic, socialism-oriented, federal democratic republican State.\nExplanation: For the purposes of this Article, \"secular\" means religious,\ncultural freedoms, including protection of religion and culture handed down from time\nimmemorial.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The territory of Nepal shall comprise the following:-\n(a) The territory existing at the time of commencement of this\nConstitution, and\n(b) Such other territory as may be acquired after the commencement of\nthis Constitution.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 5", "title": "National Interest", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Safeguarding of the  freedom, sovereignty, territorial integrity,\nnationality, independence and dignity of Nepal, the rights of the Nepali people, border\nsecurity, economic wellbeing and prosperity shall be the basic elements of the n ational\ninterest of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Any conduct and act contrary to the national interest shall be punishable in\naccordance with the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 6", "title": "Languages of Nation", "content": "All languages spoken as the mother tongues in Nepal are the\nlanguages of the nation.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 7", "title": "Official Language", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Nepali language in the Devnagari script shall be the\nofficial language of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Province may, by a provincial law, determine one or more than one\nlanguages of the nation spoken by a majority of people within the Province as its\nofficial language or languages, in addition to the Nepali language.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Other matters relating to language shall be as decided by the Government\nof Nepal on recommendation of the Language Commission.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 8", "title": "National Flag", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The national flag of Nepal consists of two juxtaposed triangular\nfigures with a crimson -coloured base and deep blue borders, there being a white\nemblem of the crescent moon with eight rays visible out of sixteen in the upper part\nand a white emblem of a twelve rayed sun in the lower part.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The method of drawing out the flag and other particulars relating thereto\nshall be as provided for in Schedule-1.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 9", "title": "National Anthem and so on", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The national anthem of Nepal shall be as set forth in\nSchedule-2.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The coat-of-arms of Nepal shall be as set forth in Schedule-3.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Rhododendron Arboreum shall be the national flower, Crimson Colour\nshall be the national colo ur, Cow shall be the national animal and Lophophor us shall\nbe the national bird of Nepal.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-2", "title": "Citizenship", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 10", "title": "Not to Deprive of Citizenship", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No citizen of Nepal shall be deprived of the right to\nobtain citizenship.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Provision of single federal citizenship with provincial identity has been\nmade in Nepal.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 11", "title": "To be Citizens of Nepal", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The persons who have obtained the citizenship of Nepal\nat the time of commencement of this Constitution and who are qualified to obtain\ncitizenship in accordance with this Part shall be the citizens of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The following person who has his or her permanent domicile in Nepal at\nthe time of commencement of this Constitution shall be the citizen of Nepal by\ndescent:-\n(a) A person who has obtained the citizenship of Nepal by descent prior\nto the commencement of this Constitution;\n(b) A person whose father or mother was a citizen of Nepal at  the time of\nhis or her birth.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A child of a citizen having obtained the citizenship of Nepal by virtue of\nbirth prior to the commencement of this Constitution shall, upon attaining the age of\nmajority, acquire the citizenship of Nepal by descent in case  the child's  father and\nmother both are citizens of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Every minor who is found within Nepal and the whereabouts of whose\nfather and mother are not known shall, until the father or the m other of the child is\ntraced, be a citizen of Nepal by descent.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "A person who is born in Nepal to a woman who is a citizen of Nepal  and\nhas resided in Nepal and whose father is not traced shall be provided with the\ncitizenship of Nepal by descent.\nProvided that in case his or her father is held to be a foreign citizen, the\ncitizenship of such person shall be converted into naturalized citizenship as provided\nfor in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "A foreign woman who has a matrimonial relationship with a citi zen of\nNepal may, in case  she so desires, acquire the naturalized citizenship of Nepal as\nprovided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "Notwithstanding anything contained elsewhere in this Article, in the case\nof a person  born to a woman who is a citizen of Nepal  and married to a foreign\ncitizen, the person may acquire the naturalized citizenship of Nepal in accordance\nwith the federal law in case he or she has permanently resided in Nepal and has not\nacquired the citizenship of a foreign country.\nProvided that  in case  such person's mother and father both are citizens of\nNepal at the time of acquisition of citizenship, such person born in Nepal may acquire\nthe citizenship of Nepal by descent.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "In the cases other than those referred to in this Article, the Government of\nNepal may, in accordance with  the federal law, grant the naturalized citizenship of\nNepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "The Government of Nepal may, in accordance with  the federal law, grant\nthe honorary citizenship of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": "Whenever any territory is acquir ed by way of incorporation into Nepal, a\nperson having his or her domicile within such territory shall , subject to the federal\nlaw, become a citizen of Nepal.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 12", "title": "Citizenship based on Descent along with Gender Identity", "content": "A person who is entitled to\nobtain the citizenship of Nepal by descent in  accordance with this Constitution may\nobtain a certificate of citizenship of Nepal with gender identity by the name of his or\nher mother or father.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 13", "title": "Acquisition, Reacquisition and Termination of Citizenship", "content": "Other matters relating to\nthe acquisition, reacquisition and termination of citizenship shall be as provided  for in\nthe federal law.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 14", "title": "Power to Grant non-resident Nepali Citizenship", "content": "The non-residential citizenship of\nNepal may be so granted to a  person who has acquired the citizenship of a foreign\ncountry, has resided in a country other than a Member State of the South Asian\nAssociation for Regional Coope ration, and who or whose father or mother ,\ngrandfather or grandmother was prev iously a citizen of Nep al by decent or birth but\nsubsequently acquired the citizenship of the foreign country that such person may\nenjoy economic, social and cultural rights in accordance with the federal law.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 15", "title": "Other Provisions relating to Citizenship of Nepal", "content": "Other matters relating to the\nmaintenance of records setting out the identity of every citizen of Nepal and the\ncitizenship of Nepal shall be as provided for in the federal law.", "children": []}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-3", "title": "Fundamental Rights and Duties", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 16", "title": "Right to Live with Dignity", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every person shall have the right to live with dignity.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No law shall be made providing for the death penalty to anyone.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 17", "title": "Right to Freedom", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No person shall be deprived of his or her personal liberty except\nin accordance with law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Every citizen shall have the following freedoms: -\n(a) Freedom of opinion and expression;\n(b) Freedom to assemble peaceably and without arms;\n(c) Freedom to form political parties;\n(d) Freedom to form unions and associations;\n(e) Freedom to move and reside in any part of Nepal;\n(f) Freedom to practise any profession, carry on any occupation  and establish\nand operate any industry, trade and business in any part of Nepal.\nProvided that:", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Nothing in sub-clause (a) shall be deemed to prevent the making of an Act\nto impose reasonab le restrictions on any act which may undermine the\nsovereignty, territorial integrity, nationality and independence of Nepal or\nthe harmonious relations between the Federal Units or the people  of\nvarious castes, tribes, religions  or communities or  incite caste-based\ndiscrimination or untouchability or on  any act of disrespect of labour,\ndefamation, contempt of court , incitement to an offence  or on any act\nwhich may be contrary to public decency or morality.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Nothing in sub-clause (b) shall be deemed to  prevent the making of an Act\nto impose reasonable restrictions on any act which may undermine the\nsovereignty, territorial integrity, nationality and inde pendence of Nepal o r\nthe harmonious relations between the Federal Units or public  law and\norder.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Nothing in sub-clause (c) shall be deemed to prevent the making of an Act\nto impose reasonable restrictions on any act  which may  undermine the\nsovereignty, territorial integrity, nationality and independence of Nepal,\nconstitute an espionage against the nation or divulge national secrecy or on\nany act of rendering assistance to  any foreign State, organization or\nrepresentative in a manner to undermine the security of Nepal or on an act\nof sedition or on any act which may  undermine the harmonious relations\nbetween the Federal Units  or on any act of incitement to caste -based or\ncommunal hatred or on any act  which may undermine the harmonious\nrelations between various castes, tribes, religions and communities, or on\nany act of acquisition of , or restriction on, membership of any political\nparty on the basis solely of  tribe, language, religion, community or sex   or\non any act of formation of a political party with discrimination between\ncitizens or on incitement to violent acts or on any act whi ch may be\ncontrary to public morality.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Nothing in sub-clause (d) shall be deemed to prevent the making of an Act\nto impose reasonable restrictions on any act which may undermine the\nsovereignty, territorial integrity, nationality and independence of Ne pal, or\non any act which may constitute espionage against the nation or on any act\nof divulgence of national secrecy or on any act assisting any foreign State,\norganization or representative in a manner to undermine the security of\nNepal or on an act of sedition or on any act which may undermine the\nharmonious relations between the Federal Units or on any act of\nincitement to caste -based or communal hatred or on any act which may\nundermine the harmonious relations between various castes, tribes,\nreligions and communities or on incitement to violent acts or on any act\nwhich may be contrary to public morality.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Nothing in sub-clause (e) shall be deemed to prevent the making of an Act\nto impose reasonable restrictions on any act which may undermine  the\ninterest of the pubic-in-general or which may undermine the harmonious\nrelations between the Federal Units or the harmonious relations between\nthe peoples of various castes, tribes, religions or communities or which\nmay constitute or incite violent acts.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "Nothing in sub-clause (f) shall be deemed to prevent the making of an Act\nto prevent any act which may undermine the harmonious relations between\nthe Federal Units or any act which may be contrary to public health,\ndecency or morality of  pubic-in-general or to confer on the State the\nexclusive right to undertak e any specific industry, trade or service, or to\nprescribe any condition or qualification for carrying on any industry, trade,\noccupation, employment or business.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 18", "title": "Right to Equality", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "All cit izens shall be equal before  law. No one shall be denied\nthe equal protection of law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No discrimination shall be made in the application of general laws on\ngrounds of origin, religion, race , caste, tribe, sex , physical condition,  disability,\ncondition o f health,  marital status, pregnancy, economic condition, language or\nregion, ideological conviction or on similar other grounds.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Sta te shall not discriminate among citizens on grounds of origin,\nreligion, race , caste, tribe, sex, economic condition, langu age, region, ideolog ical\nconviction or on similar other grounds.\nProvided that nothing shall be deemed to prevent the making of spe cial\nprovisions by law  for the protection, empowerment or  development of the citizens\nincluding the socially or culturally backward women, Dalit, indigenous  people,\nindigenous nationalities  (Aadibasi Janajati ), Madhesi, Tharu, Muslim, oppressed\nclass, Pichhada class, minorities, the marginalized, farmers, labours, youths, children,\nsenior citizens, gender and sex ual minorities, persons with disabilities,  pregnant\npersons, incapacitated or helpless, backward region and indigent Khas Arya.\nExplanation: For the purposes of thi s Part and Part 4, \" indigent\" means a person who\nearns income less than that specified by the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "No discrimination shall be made on the ground of gender with regard to\nremuneration and social security for the same work.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "All offspring shall have the equal  right to the ancestral property without\ndiscrimination on the ground of gender.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 19", "title": "Right to Communication", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No publication and broadcasting or dissemination or\nprinting of any news item, editorial, feature article or other reading, audio and audio -\nvisual material through any means whatsoever including electronic publication,\nbroadcasting and printing shall be censored.\nProvided that nothing shall be deemed to prevent the making of Acts to impose\nreasonable restrictions on any act which may undermine the sovereignty, territorial\nintegrity, nationality of Nepal or the harmonious relations between  the Federal Units\nor the harmonious relations between various castes, tribes, religions or communities,\nor on any act of sedition, defamation or contempt of court or incitement to an offence,\nor on any act which may be contr ary t o public decency or  morality, on any act of\nhatred to labour and on any act of incitement to caste-based untouchability as well as\ngender discrimination.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No radio, television, online or other form of digital or electronic equipment,\npress or other means of communication publishing, broadcasting or printing any news\nitem, feature, editorial, article, information or other material shall be closed or seized\nnor shall registration thereof be cancelled nor shall such material be seized by the\nreason of publication, broadcasting or printing of such material through any audio,\naudio-visual or electronic equipment or press.\nProvided that nothing contained in this clause shall be deemed to prevent the\nmaking of an Act to regulate radio, television, online or  any other form of digital or\nelectronic equipment, press or other means of communication.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "No means of communication including the press, electronic broadcasting and\ntelephone shall be interrupted except in accordance with law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 20", "title": "Rights r elating to  Justice", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No person  shall be detained in custody without\ninforming him or her of the ground for his or her arrest.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Any person who is arrested shall have the right to consult a legal\npractitioner of his or her choice from the time of such arrest  and to be defended by\nsuch legal practitioner. Any consultation made by such person with, and advice given\nby, his or her legal practitioner shall be confidential.\nProvided this clause shall not apply to a citizen of an enemy State.\nExplanation: For the purpose of this clause, \"legal practitioner\"  means any\nperson who is authorized by law to represent any person in any court.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Any person who is arrested shall be produced before the adjudicating\nauthority within a period of twenty -four hours of such arr est, excluding the time\nnecessary for the journey from the place of arrest to such authority; and  no such\nperson shall be detained in custody except on the order of such authority.\nProvided that this clause shall not apply to a person held in preventive de tention\nand to a citizen of an enemy State.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "No person shall be liable for punishment  for an act  which was not\npunishable by the law in force when the act was committed nor shall any person be\nsubjected to a punishment greater than that prescribed by t he law in force at the time\nof the commission of the offence.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Every person accused of an offence shall be presumed innocent until proved\nguilty of the offence.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "No person shall be tried and punished for the same offence in a court of law\nmore than once.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "No person accused of an offence shall be compelled to testify against himself\nor herself.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "Every person shall have the right to be informed of any proceedings taken\nagainst him or her.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "Every person shall have the right to a fair trial by a n independent, impartial\nand competent court or judicial body.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": "Any indigent party shall have the right to free legal aid in accordance with\nlaw.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 21", "title": "Right of Victim of Crime", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A victim of crime shall have the right to get information\nabout the investigation and proceedings of a case in which he or she is the victim.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A victim of crime  shall have the right to justice along with social\nrehabilitation and compensation in accordance with law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 22", "title": "Right against Torture", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No person who is arrested or detained shall be subjected to\nphysical or mental torture or to cruel, inhuman or degrading treatment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Any act referred to in clause (1) shall be punishable by law, and any person\nwho is a victim of such treatment shall have the right to obtain com pensation in\naccordance with law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 23", "title": "Right against Preventive Detention", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No person shall be held under preventive\ndetention unless there is a sufficient ground of the existence of an immediate threat to\nthe sovereignty, territorial integrity or public law and order of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Information about the situation of a person who is held under preventive\ndetention pursuant to clause (1) shall be given  immediately to his or her family\nmembers or relatives.\nProvided that this clause shall not apply to a citizen of an enemy State.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case  the authority having power to hold a person under  preventive\ndetention holds any person under preventi ve detention contrary to law or in bad faith,\nsuch person shall have the right to obtain compensation in accordance with law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 24", "title": "Right against Untouchability and Discrimination", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No person shall be subjected to\nany form of untouchability or discrimination in any private and public places  on\ngrounds of his or her origin, caste,  tribe, community , profession , occupation or\nphysical condition.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In producing or distributing any goods, services or facilities, no person\nbelonging to any particular caste or tribe shall be prevented from purchasing or\nacquiring such goods, services or facilities nor shall such goods, services or facilities\nbe sold, distributed or provided only to the persons belonging to any particular caste\nor tribe.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "No act purporting to demon strate any person or community as superior or\ninferior on grounds of origin, caste, tribe or physical condition or justifying social\ndiscrimination on grounds of caste , tribe or untouchability or propagating ideology\nbased on untouchability and caste based superiority or hatred or encouraging caste -\nbased discrimination in any manner whatsoever shall be allowed.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "No discrimination in any form shall be allowed at a workplace  with or\nwithout making untouchability on the ground of caste.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "All types of acts of untouchability and discrimination committed in\ncontravention of this Article shall be punishable by law as a severe social offence, and\nthe victim of such  act shall have the right to obtain compensation in accordance  with\nlaw.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 25", "title": "Right relating to Property", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every citizen shall, subject to law, have the right to\nacquire, own, sell, dispose of, acquire business profits from, and otherwise deal with,\nproperty.\nProvided that the State may levy tax on property of a person, and tax on income\nof a person in accordance with the concept of progressive taxation.\nExplanation: For the purposes of this Article, \"property\" means any form  of\nproperty including movable and immovable property and the word includes\nintellectual property right as well.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The State shall not, except  for public interest, requisition,  acquire, or\notherwise create any encumbrance on, property of a person.\nProvided that this clause shall not apply to any property acquired by any  person\nillicitly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The basis of compensation  to be provided and procedures to be followed in\nthe requisition by the State of property of any person for public interest pursuant to\nclause (2) shall be as provided for in the Act.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The provisions of clauses (2) and (3) shall not prevent the State from making\nland reforms, management and regulation in accordance with law  for the purposes of\nenhancement of product and productivity of land, modernization and\ncommercialization of agriculture, environment protection and planned housing and\nurban development.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In case the State has requisitioned property of any person for public interest\npursuant to clause (3), nothing shall prevent the  State from using such property for\nany other public interest instead of such public interest.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 26", "title": "Right to Freedom of Religion", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every person  who has faith in religion  shall have\nthe freedom to profess, practice and protect his or her religion in accordance with his\nor her conviction.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Every religious denomination shall have the right to operate and protect its\nreligious sites and religious Guthi (trusts).\nProvided that nothing shall be deemed to prevent the regulation, by making law,\nof the operation and protection of religious sites an d religious trusts and management\nof trust properties and land.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "No person shall, in the exercise of the right conferred by this Article, do, or\ncause to be done, any act which may be contrary to public health, de cency and\nmorality or breach of public peace, or convert another person from one religion to\nanother or any act or conduct that may jeopardize other's religion and such act shall be\npunishable by law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 27", "title": "Right to Information", "content": "Every citizen shall have the right to demand and receive\ninformation on any matter of his or her interest or of public interest.\nProvided that no one shall be compelled to provide information on any matter\nwhich must be maintained confidential in accordance with law.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 28", "title": "Right to Privacy", "content": "The privacy of any person, his or her residence, property, document,\ndata, correspondence and matters relating to his or her character shall , except in\naccordance with law, be inviolable.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 29", "title": "Right against Exploitation", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every person shall have the right against exploitation.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No person shall be exploited in any manner on the ground s of religion,\ncustom, tradition, usage, practice or on any other grounds.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "No one shall be subjected to trafficking nor shall one be held in slavery or\nservitude.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "No one shall be forced to work against his or her will.\nProvided that nothing shall be deemed to prevent the making of law by the State\nrequiring citizens to perform compulsory service for public purposes.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "An act contrary to clauses (3) and (4) shall be punishable by law and the\nvictim shall have the right to obtain compensation from the perpetrator in accordance\nwith law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 30", "title": "Right to Clean Environment", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every citizen shall have the right to live in a clean\nand healthy environment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The victim shall have the right to obtain  compensation, in accordance with\nlaw, for any damage caused by environmental pollution or degradation.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "This Article shall not be deemed to prevent the making of necessary legal\nprovisions for a proper balance between  environment and development in\ndevelopment works of the nation.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 31", "title": "Right relating to Education", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every citizen shall have the right of access to basic\neducation.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Every citizen shall have the right to get compulsory and free education up\nto the basic level and free education up to the secondary level from the State.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The citizens with disabilities and the indigent citizens shall have the right\nto get free higher education in accordance with law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The visually impaired citizens shall have the righ t to get free education\nthrough brail script and the citizens with hearing or speaking impairment, to get free\neducation through sign language, in accordance with law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Every Nepali community residing in Nepal shall have the right to get\neducation in its own mother tongue and, for that purpose, to open and operate schools\nand educational institutes, in accordance with law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 32", "title": "Right to Language and Culture", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every person and community shall have the right\nto use their own languages.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Every person and community shall have the right to participate  in the\ncultural life of his/her/its community.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Every Nepali community residing in Nepal shall have the right to preserve\nand promote its language, script, culture, cultural civilization and heritage.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 33", "title": "Right to Employment", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every citizen shall have the right to employment. The terms\nand conditions of employment , and unemployment benefit shall be as provided for in\nthe federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Every citizen shall have the right to choose employment.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 34", "title": "Right to Labour", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every labourer shall have the right to fair labour practice.\nExplanation: For the purposes of this Article, \"labourer\" means a labourer or\nworker who does physical or intellectual work for an employer in consideration for\nremuneration.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Every labourer shall have the right to appropriate remuneration, facilities and\ncontributory social security.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Every labourer  shall have the right to form and join trade unions and to\nengage in collective bargaining, in accordance with law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 35", "title": "Right relating to Health", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every citizen shall have the right to free basic health\nservices from the State, and no one shall be deprived of emergency health services.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Every person shall have the right to  get information about his or her medical\ntreatment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Every citizen shall have equal access to health services.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Every citi zen shall have the right of  access to clean drinking water and\nsanitation.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 36", "title": "Right relating to Food", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every citizen shall have the right relating to food.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Every citizen shall have the right to be safe from the state of being in\ndanger of life from the scarcity of food.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Every citizen shall have the right to food sovereignty i n accordance with\nlaw.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 37", "title": "Right to Housing", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every citizen shall have the right to an appropriate housing.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No citizen shall be evicted from the residence owned by him or her  nor\nshall his or her residence be infringed except in accordance with law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 38", "title": "Rights of Women", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every woman shall have equal lineage right without  gender-\nbased discrimination.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Every woman shall have the right to safe motherhood and reproductive\nhealth.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "No woman shall be subjected to physical, mental, sexual, psychological or\nother form of violence or exploitation on grounds of religion, social, cultural tradition,\npractice or on any other grounds. Such  act shall be punishable by law, and the victim\nshall have the right to obtain compensation in accordance with law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Women shall have the right to participate in all bodies of the State on the\nbasis of the principle of proportional inclusion.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Women shall have the right to obtain special opportunity in education,\nhealth, employment and social security, on the basis of positive discrimination.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The husband and wife  shall have the equal right to property  and family\naffairs.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 39", "title": "Rights of Child", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every child shall have the right to name and birth registration\nalong with his or her identity.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Every child shall have the right to education, health, maintenance, proper\ncare, sports, entertainment and overall personality development from the families and\nthe State.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Every child shall have the right to elementary child development  and child\nparticipation.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "No child shall be engaged in any factory, mine or similar other hazardous\nwork.\n5) No child shall be subjected to child marriage, transported illegally and\nkidnapped or taken hostage.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "No child shall be recruited or used in army, police or any armed group, or be\nsubjected, in the name of cultural or religious traditions, to abuse, exclusion or physical,\nmental, sexual or other form of exploitation or improper use by any means or in any\nmanner.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "No child shall be subjected to physical, mental or any other form of torture\nin home, school or other place and condition whatsoever.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "Every child shall have the right to child-friendly justice.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "The child who is helpless, orphan, with disabilities, conflict victim, displaced\nor vulnerable shall have the right to special protection and facilities from the State.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": "Any act contrary to in clauses (4), (5), (6) and (7 ) shall be punishable by\nlaw, and a child who is the victim of such act  shall have th e right to obtain\ncompensation from the perpetrator, in accordance with law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 40", "title": "Rights of Dalit", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Dalit shall have the right to participate in all bodies of the\nState on the basis of the principle of proportional in clusion. Special provision shall be\nmade by law for  empowerment, representation and participation of the Dalit\ncommunity in public services as well as other sectors of employment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Provision of free education with scholarship, from primary to higher\neducation, shall be made by law for the Dalit students. Special provision shall be\nmade by law for the Dalit in technical and vocational education.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Special provision shall be made by law in order to provide health and\nsocial security to the Dalit community.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The Dalit community shall have the right to use, protect and develop their\ntraditional occupation, knowledge, skill  and technology. The State shall accord\npriority to the Dalit community in modern business related with their traditional\noccupation and provide skills and resources required therefor.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The State shall provide land  to the landless Dalit for one time in\naccordance with law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The State shall, in accordance with law,  make provision of settlement for\nthe Dalit who do not have housing.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The facilities conferred by this Article to the Dalit community shall be\ndistributed in a just manner  so that the Dalit women, men and Dalit in all\ncommunities may obtain such facilities proportionately.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 41", "title": "Rights of Senior Citizens", "content": "The senior citizens shall have the right to special protection\nand social security from the State.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 42", "title": "Right to Social Justice", "content": "(1) The economically, socially or educationally backward\nwomen, Dalit, indigenous nationalities  (Aadibasi Janajati ), Madhesi , Tharu,\nMuslims, backward classes, minorities, marginalized communities, persons with\ndisabilities, gender and sexual minorities, farmers, labourers, oppressed or\ncitizens of backward regions and indigent  Khas Arya  shall have the right to\nparticipate in the bodi es of the State on the basis of principle of proportional\ninclusion.", "children": [{"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The indigent citizens and citizens of the communities on the verge of\nextinction shall have the right to get special opportunities and benefits in education,\n Amended by the First Amendment.\nhealth, housing, employment, food and social security for their protection, upliftment,\nempowerment and development.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The citizens with disabilities shall have the right to live with dignity and\nhonour, with the identity of their diversity , and have equal access to p ublic services\nand facilities.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Every farmer shall, in accordance with law, have the right to have access to\nland for agro activities, select and protect local seeds and agro species which have\nbeen used and pursued traditionally.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The families  of the martyrs who have sacrificed their life , and of the\ndisappeared persons and those who became disabled and injured in all people's\nmovements, armed conflicts and revolutions that have been carried out for progressive\ndemocratic changes in Nepal, democracy fighters, conflict victims and displaced ones,\npersons with disabilities, the injured and victims shall have the right to get a\nprioritized opportunity, with justice and due respect, in education, health,\nemployment, housing and social security, in accordance with law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 43", "title": "Right to Social Security", "content": "The indigent citizens, incapacitated and helpless citizens,\nhelpless single women, citizens with disabilities, children, citizens who cannot take care\nthemselves and citizens belonging to the tribes on the verge of extinction shall have\nthe right to social security, in accordance with law.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 44", "title": "Rights of Consumer", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every consumer shall have the right to obtain quality goods\nand services.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A person who has suffered damage from any substandard goods or services\nshall have the right to obtain compensation in accordance with law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 45", "title": "Right against Exile", "content": "No citizen shall be exiled.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 46", "title": "Right to Constitutional Remedies", "content": "There shall be a right to obtain constitutional\nremedies in the manner set forth in Article 133 or 144 for the enforcement of the\nrights conferred by this Part.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 47", "title": "Implementation of Fundamental Rights", "content": "The State shall, as required, make legal\nprovisions for the implementation of th e rights conferred by this Part, within three\nyears of the commencement of this Constitution.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 48", "title": "Duties of Citizens", "content": "Every citizen shall have the following duties:-\n(a) To safeguard the nationality, sovereignty and integrity of Nepal, while\nbeing loyal to the nation;\n(b) To abide by the Constitution and law;\n(c) To render compulsory service as and when the State so requires;\n(d) To protect and preserve public property.", "children": []}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-4", "title": "Directive Principles, Policies and Obligations of the State", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 49", "title": "To be as Guidelines", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The directive principles , policies and obligations set forth in\nthis Part shall be guidelines for governance of the State.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The State shall mobilize, or cause to be mobilized, means and resources, as\nrequired, to implement the principles, policies and obligations set forth in this Part.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 50", "title": "Directive Principles", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The political objective of the State shall be to establish a\npublic welfare system of governance, by establishing a j ust system in all aspects of\nnational life through the rule of law, values and norms of fundamental rights and\nhuman rights, gender equality, proportional inclusion, participation and social justice,\nwhile at the same time protecting the life, property , equality and liberties  of the\npeople, in keeping with the vitality of freedom, sovereignty, territorial integrity and\nindependence of Nepal; and to consolidate the federal democratic republic an system\nof governance in order t o ensure an atmosphere conducive to the enjoyment of fruits\nof democracy, while at the same time maintaining the relations between the Federal\nUnits on the basis of cooperative federalism  and incorporating the principle of\nproportional participation in the system of governance on the basis of local autonomy\nand decentralization.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The social and cultural objective of the State shall be to build a civilized\nand egalitarian society by eliminating all forms of discrimination, exploitation and\ninjustice based on the grounds of religion, culture, tradition, usage, custom, practice or\non any other similar grounds ; to develop social, cultural values founded on national\npride, democracy, pro-people, respect  of labour, entrepreneurship, discipline, dignity\nand harmony; and to consolidate the national unity by maintaining social cohesion,\nsolidarity and harmony, while recognizing cultural diversity.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The economic objective of the State shall be to attain a sustainable\neconomic development, while achieving rapid economic growth, by way of maximum\nmobilization of the available means and resources  through participation and\ndevelopment of public, private and cooperatives ; and to develop a socialism -oriented\nindependent and prosperous economy while making the national economy\nindependent, self-reliant and progressive in order to build an exploitation -free society\nby abolishing economic inequality through equitable distribution of the achievements\nmade.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The State shall direct its internatio nal relations towards enhancing the\ndignity of the nation in the world community by maintaining international relations on\nthe basis of sovereign equality, while safeguarding the freedom, sovereignty, territorial\nintegrity and independence and national interest of Nepal.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 51", "title": "Policies of the State", "content": "The State shall pursue the following policies:-\n(a) Policies relating to National Unity and National Security:", "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "To maintain national unity intact, while p rotecting the freedom,\nsovereignty, territorial integrity and independence of Nepal;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "To promote national unity while developing mutual cooperative\nrelations among the Federal U nits by maintaining mutual cohesion,\nharmony and solidarity among various castes, tribes, relig ions,\nlanguages, cultures and communities;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "To maintain law and order by developing national security system;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "To guarantee overall human security system;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "To make all security organs , including the Nepal Army, Nepal Police\nand Armed Police Force  Nepal, com petent, strong,  professional,\ninclusive and accountable to people, on the basis of national security\npolicies;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "To make and keep citizens ready and competent to serve the n ation as\nand when the nation requires;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "To make proper use, in nations' interest, of knowled ge, skills and\nexperiences of former public employees including former employees,\nmilitary and police.\n(b) Policies relating to Political and Governance System of State:", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "To guarantee the best interests and prosperity of people through\neconomic, social and cultural transformations, while safeguarding,\nconsolidating and developing political achievements;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "To maintain rule of law by protecting and promoting human rights;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "To implement international treaties, agreements to which Nepal is a\nparty;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "To guarantee good governance by ensuring equal and easy access of\npeople to services and facilities delivered by the State, while making\npublic administration fair, competent, impartial, transparent, free from\ncorruption, accountable and participatory;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "To make necessary provisions to make mass media fair, healthy,\nimpartial, decent, responsible and professional;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "To develop and expand harmonious and cooperative relations between\nthe Federal Units by way of sharing of responsibilities, resources and\nadministration between them.\n(c) Policies relating to Social and Cultural Transformation:", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "To build a society founded on cordial social relations by developing  a\nhealthy and civilized culture;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "To carry out studies, research works, excavation and dissemination for\nthe protection, promotion and development of historical,\narchaeological and cultural heritages;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "To make community development through enhancement of local public\nparticipation, by promoting and mobilizing the creativity of local\ncommunities in social, cultural and service-oriented works;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "To focus on development of arts, literature and music which form  part\nof national heritages;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "To eliminate all forms of discrimination, inequality, exploitation and\ninjustice in the name of religion, custom, usage, practice and tradition\nexisting in society;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "To protect and develop languages, scripts, culture , literature,  arts,\nmotion pictures and heritages of various  castes, tribes,  and\ncommunities on the basis of equality and co -existence, while\nmaintaining the cultural diversity of the country;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "To pursue a multi-lingual policy.\n(d) Policies relating to Economy, Industry and Commerce:", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "To strengthen national economy through participation and independent\ndevelopment of the public, private and cooperative sectors;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "To achieve economic prosperity by way of optimum mobilization of\nthe available means and resources , while focusing on the role of\nprivate sector in economy;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "To promote the cooperative sector and mobilize  it in national\ndevelopment to the maximum extent;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "To encourage and mobilize the economic sector in the overall national\ndevelopment, while providing for regulation to maintain fairness,\naccountability and competition in all of its activities;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "To make equitable distribution of the available means and resources\nand benefits of economic development;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "To diversify and expand markets for goods and services, while\npromoting expo rts through development and expansion of industries\nupon identifying areas of comparative advantage;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "To protect interests of consumers by maintaining trade fairness and\ndiscipline by making national economy competitive, while eliminating\nactivities such as black marketing, monopoly, creating artificial\nscarcity and restricting competition;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "To protect and promote national industries and resources and accord\npriority to domestic investment based on Nepali labour, skills and raw\nmaterials for development of national economy;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "To accord priority to domestic investment for development of national\neconomy;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": "To encourage foreign capital and technological investment in areas of\nimport substitution and export promotion, in consonance wit h national\ninterest, and encourage and mobilize such investment in  development\nof infrastructure;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(11)", "title": null, "content": "To make the receiving of foreign assistance transparent, while making\nthe national needs and priorities as the bas es for obtaining foreign\nassistance, and incorporating amounts received in form of foreign\nassistance in the national budget,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(12)", "title": null, "content": "To utilize knowledge, skill, technology and capital of the non-resident\nNepali in the national development;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(13)", "title": null, "content": "To make economic development dynamic by establishing coordination\namong Provinces and Provinces and the Federation in relation to\nindustrial corridors, special economic zones, national projects and\nprojects involving foreign investment.\n(e) Policies relating to Agriculture and Land Reforms:", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "To introduce scientific land reforms  having regard to the interests of\nthe farmers, while ending the dual ownership existing in the land;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "To enhance product and productivity by carrying out land pooling,\nwhile discouraging absentee land ownership;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "To carry out land management and commercialization,\nindustrialization, diversification and modernizatio n of agriculture by\npursuing land -use policies to  enhance agriculture product and\nproductivity, while protecting and promoting the rights and interests of\nthe farmers;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "To make proper use of  land, while regulating and managing it on the\nbasis of, inter alia, productivity, nature of land and ecological balance;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "To make provisions for appropriate prices of agricultural inputs and\nagricultural products and for market access.\n(f) Policies relating to Development:", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "To formulate sustainable socio -economic development strategies and\nprograms under the regional development plan for inclusive economic\ndevelopment with regional balance, and implement them in a\ncoordinative manner;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "To d evelop balanced, environment friendly , quality  standard and\nsustainable physical infrastructure s, wh ile according priority to the\nregions lagging behind from development perspective;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "To enhance local public participation in the process of development\nworks;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "To enhance investment in scientific study, re search works and in\ninvention, progress and d evelopment of science and technology, and\nprotect scientists, technologists, intellectual and eminent talents;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "To ensure easy and simple access of public-in-general to information\ntechnology by developing and expanding information technology in\ntune with national needs, and make optimum utilization of information\ntechnology in the national development;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "To make provisions enabling public-in-public-in-general to enjoy fruits\nof development in just manner, while according priority to the indigent\ncitizens in the distribution of such fruits;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "To develop an integrated national identity management information\nsystem and manage all types of information and data of the citizens in\nan integrated manner, and link such system with the services and\nfacilities provided by the State and with national development plans;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "To update demographic statistics and link it with national development\nplans.\n(g) Policies relating to Protection, Promotion and Use of Natural Resources:", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "To protect, promote, and make environmental friendly and sustainable\nuse of, natural resources available in the country, in consonance with\nnational interest and by adopting the concept of inter -generational\nequity, and make equitable distribution of  benefits, according priority\nand preferential right to the local communities;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "To achieve multi-purpose development of water resources  having\naccorded priority to national investment based on public participation;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "To ensure reliable supply of energy in an affordable , and easy manner,\nand make proper use of energy, for the fulfilment of the basic needs of\ncitizens, by generating and developing renewable energy;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "To develop sustainable and reliable irrigation by making control of\nwater-induced disasters, and river management;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "To conserve, promote, and make sustainable use of, forests, wildlife,\nbirds, vegetation and bio -diversity, by mitigating possible risks t o\nenvironment from industrial and physical development, while raising\nawareness of public-in-general about environment cleanliness;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "To maintain forest area in territory required for ecological balance;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "To adopt appropriate measures to abolish or mi tigate existing or\npossible adverse environmental impacts on the nature, environment or\nbiological diversity;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "To pursue principles of environmental ly sustainable development such\nas the principles of polluter pay , of precaution in environmental\nprotection and of prior informed consent;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "To make provisions of advance warning, preparedness, rescue, relief\nand rehabilitation in order to mitigate risks from natural disasters.\n(h) Policies relating to Basic Needs of Citizens:", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "To prepare human resources that  are competent, competitive, ethical,\nand devoted to national interests, while making education scientific,\ntechnical, vocational, skill-oriented, employment and people-oriented;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "To promote investment of the State in education sector and to make\nprivate sector investment in education service -oriented by regulation\nand management;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "To make higher education easy, qualitative and accessible, and free\ngradually;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "To establish and promote community information ce ntres and libraries\nfor personality development of citizens;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "To keep on increasing investment necessary in public health sector by\nthe State in order to make the citizens healthy;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "To ensure easy, convenient and equal access of all to quality health\nservices;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "To protect and promote health systems including Ayurveda, as a\ntraditional medical system of Nepal, natural therapy and homeopathy\nsystem;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "To make private sector investment in the health sector service-oriented\nby regulating and managing such investment, while enhanci ng the\nState's investment in this sector;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "To focus on health research and keep on increasing the number of\nhealth institutions and health workers in order to make health services\nwidely available and qualitative;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": "To increase average life expectancy by reducing maternal and infant\nmortality rate s, while encouraging family planning for population\nmanagement on the basis of Nepal's capacity and need;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(11)", "title": null, "content": "To manage unplanned set tlement and develop planned and systematic\nsettlement;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(12)", "title": null, "content": "To provide for sustainable production, supplies, storage, security, and\neasy and effective distribution of foods by encouraging food\nproduction in tune with climate and soil, in consonance with th e\nconcept of food sovereignty , while  enhancing investment in the\nagriculture sector;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(13)", "title": null, "content": "To ensure planned supply system by according special priority to the\nremote and backward regions, while ensuring equal access of all\ncitizens to basic goods and services;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(14)", "title": null, "content": "To enhance investment in the transportation sector, while ensuring\nsimple, easy and equal access of the citizens to transportation facilities,\nand to  make the transportation sector safe, systematic and friendly to\npersons with disabilities by encouraging public transportation and\nregulating private transportation, while according priority to the\nenvironment friendly technologies;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(15)", "title": null, "content": "To arrange for access to medical treatment while ensuring citizen's\nhealth insurance.\n(i) Policies relating to Labour and Employment:", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "To make competent and professional the labour force that has remained\nas the main socio-economic strength of the country  and enhance\nemployment within the country, while ensuring a condition enabling all\nto work;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "To guarantee social security, while ensuring the basic rights of all\nlabours, in consonance with the concept of decent labour;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "To abolish all forms of labour exploitation including child labour;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "To encourage participation of labour er in management, while\nmaintaining cordial relations between the labourer and entrepreneurs;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "To regulate and manage the foreign employment sector in order to\nmake it free from exploitation, safe and systematic and to guarantee\nemployment and rights of the labourer;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "To encourage mobilizing the capital, skills, technology and experience\ngained from foreign employment in productive sectors in the country.\n(j) Policies relating to Social Justice and Inclusion:", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "To keep on making  appropriate arrangements for the livelihoods of\nhelpless single women , while  according priority to them in\nemployment on the basis of skills, competency and qualification;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "To make self-reliant women who are at risks, subjected to social and\nfamily exc lusion and victims of violence by their rehabilitation,\nprotection and empowerment;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "To ensure enjoyment of requisite services and facilities  at the\nreproductive stage;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "To evaluate economically the work and contribution  such as\nmaintenance of children and care of families;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "To take into consideration primarily of the best interests of the child;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "To identify the freed bonded labours, Kamlari, Harawa, Charawa,\ntillers, landless, squatters and rehabilitate them by providing housing,\nhousing plot for residence and cultivable land or employment for their\nlivelihoods;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "To create an atmosphere conducive to the full enjoyment of the\npolitical, economic, social and cultural rights, while enhancing the\nparticipation of youths in national development, to make their\npersonality development, while providing special opportunity in areas\nincluding education, health and employment for the empowerment and\ndevelopment of the youths and provide them with appropriate\nopportunities for the overall development of the State;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "To make the indigenous nationalities  (Aadibasi Janajati) participate in\ndecisions concerning that community by making special provisions for\nopportunities and benefits in order to ensure the right of these\nnationalities to liv e with dignity, along with their identity, and protect\nand promote traditional knowledge, skill , culture,  social tradition and\nexperience of the indigenous nationalities and local communities;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "To make special provisions for opportunities and benefits to minority\ncommunities to enjoy social and cultural rights, having maintained\ntheir identity;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": "To make special provisions for equal distribution of economic, social\nand cultura l opportunities and benefits to the Madhesi community,\nMuslims and backward class, and for  opportunities and benefits to the\nindigent citizens within such communities for their protection,\nupliftment, empowerment and development;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(11)", "title": null, "content": "To make special provisions for opportunities and benefits for the\nprotection, upliftment, empowerment and development of the citizens\nof the oppressed and backward regions and for the fulfilment of their\nbasic needs;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(12)", "title": null, "content": "To accord priority to the indigent persons within all sexes, regions and\ncommunities while providing social security and social justice;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(13)", "title": null, "content": "To make planned investment in sports and sport -persons in order to\nprepare healthy, competent and disciplined citizens, and to develop\nsports as a mea ns of consolidating national unity and enhancing\nnational prestige at the international level;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(14)", "title": null, "content": "To adopt a single door system for the establishment, approval, operation,\nregulation and management of community -based and national or\ninternational non -governmental organizations and to involve such\norganizations only in the sectors of national need and priority, while\nmaking investment and role of such organizations transparent and\naccountable.\n(k) Policies relating to Justice and Penal System:", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "To make administration of justice speedy, efficient, widely available,\ncost-effective, impartial, effective, and accountable to people;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "To pursue alternative means such as mediation and arbitration for the\nsettlement of disputes of ordinary nature;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "To adopt effective measures for control of corruption and irregularities\nin all sectors including political, ad ministrative, judicial  and social\nsectors.\n(l) Policies relating to Tourism: To develop eco-friendly tourism industries as an\nimportant base of national economy by way of identification, protection,\npromotion and publicity of the   historical, cultural, religious, archaeological\nand natural heritages of Nepal, to make environment and policy required for\nthe development of tourism culture, and to accord priority to local people in\nthe distribution of benefits of tourism industries.\n(m) Policies relating to International Relations:", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "To conduct independent  foreign po licy based on the Charter of the\nUnited Nations, non-alignment, principles of Panchsheel, international\nlaw and the norms of world peace,  taking into consideration of the\noverall interest of  the nation, while remaining active in safeguarding\nthe sovereignty, territorial integrity, independence and national interest\nof Nepal;", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "To review  treaties concluded in the past , and conclude treaties,\nagreements based on equality and mutual interest.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 52", "title": "Obligations of the State", "content": "It shall be the obligation of the State to  make Nepal a\nprosperous and affluent country  by protecting and promoting  fundamental rights and\nhuman rights, pursuing  directive principles of the State and gradually implementing\npolicies of the State, while keeping intact the freedom, sovereignty, territorial integrity\nand independence of Nepal.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 53", "title": "To Submit Report", "content": "The Government of Nepal shall submit to the President an annual\nreport containing the steps taken and achievements made in the implementation of the\ndirective principles, policies and obligations of the State  set forth in this Part, and the\nPresident shall cause such  report to be laid through the Prime Minister before the\nFederal Parliament.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 54", "title": "Provisions relating to Monitoring", "content": "There shall be a committee, in accordance with\nlaw, in the Federal Parliament in order to monitor and evaluate whether  or not the\ndirective principles, policies and obligations of the State set forth in this Part have\nbeen implemented progressively.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 55", "title": "Questions not to be raised in Court", "content": "No question shall be raised in  any court as to\nwhether or not any matter contained in this Part has been implemented.", "children": []}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-5", "title": "Structure of State and Distribution of State Power", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 56", "title": "Structure of State", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The main structure of the Federal Democratic Republic of\nNepal shall be of three levels, namely the Federation, the Province and the Local\nLevel.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Federation, Provinces and Local Levels shall exercise the State power\nof Nepal in accordance with this Constitution and law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "There shall be Provinces consisting of the Districts referred to in Schedule-\n4 existing in Nepal at the time of commencement of this Constitution.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "There shall be Rural Municipalit y, Municipalit y and District Assembl y\nunder the Local Level. The number of Wards in a Rural Municipality  and\nMunicipality shall be as provided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Any Special,  Protected or Autonomous Region  may be set up by the\nfederal law for social, cultural protection or economic development.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The Federation, Provinces and Local Levels shall protect Nepal's freedom,\nsovereignty, territorial integrity, independence, national interest, overall development,\nmulti-party, competitive, democratic, republican, federal system of  governance,\nhuman rights and fundamental rights, rule of law, sepa ration of powers and check and\nbalance, egalitarian society b ased on pluralism and equality, inclusive  representation\nand identity.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 57", "title": "Distribution of State Power", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The powers of the Federation shall be vested o n the\nmatters enumerated in Schedule -5 and such powers shall be exercised  in accordance\nwith this Constitution and the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The powers of a Province shall be vested o n the m atters enumerated in\nSchedule-6 and such powers shall be exercised in accordance with  this Constitution\nand the provincial law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The concurrent powers of the Federation and a Province shall be vested on\nthe matters enumerated in  Schedule-7 and such powers shall be exercised in\naccordance with this Constitution, federal law and provincial law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The powers of the Local Level shall be vested o n the matters enumerated\nin Schedule-8 and such powers shall be exercised in accordance with this Constitution\nand law made by the Rural Municipal Assembly or Municipal Assembly, as the case\nmay be.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The concurrent powers of the Federation, Provinces and Local Levels shall\nbe vested o n the matters enumerated in Schedule -9 and such powers shall be\nexercised in accordance with  this Constitution , federal law, provincial law  and law\nmade by the Rural Municipal Assembly or Municipal Assembly, as the case may be.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "Any law to be made by a Provincial Assembly, Rural Municipal Assembly\nor Municipal Assembly pursuant to clause (3) or (5) shall be so made as not to be\ninconsistent with  the federal law ; and any law made by the Provincial Assembly,\nRural Municipal Assembly  or Municipal Asse mbly which is inconsistent with the\nfederal law shall be invalid to the extent of such inconsistency.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "Any law to be made by a Rural Municipal Assembly  or Municipal\nAssembly, as the case may be,  pursuant to clause (5) shall be so made as not to be\ninconsistent with a provincial law ; and any law made by the Rural Municipal\nAssembly or Municipal Assembly which is inconsistent with  a provincial law shall be\ninvalid to the extent of such inconsistency.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 58", "title": "Residuary Powers", "content": "The Federation shall have power on any matter not enumerated in\nthe list of powers of the Federation, Province and Local Level or Concurrent Lists or\non any matter which is not so specified in this Constitution as to be exercised by any\nlevel.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 59", "title": "Exercise of Financial Powers", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Federation, Province and Local Level  shall\nmake laws, make annual budget, decisions, formulate and implement policie s and\nplans on any matters related to financial powers within their respective competence.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Federation may so make necessary policies, standards and laws on any\nof the matters enumerated in the Concurrent List and other areas of financial powers\nas to be applicable also to the Provinces.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Federation, Province and Local Level  shall make budget of the ir\nrespective levels, and the time for submission of  budget by Province and Local Level\nshall be as provided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The Federation, Province and Local Level  shall provide for equitable\ndistribution of benefits  derived from the use of natural resources or development.\nCertain portions of such benefits shall be distributed, in accordance with  law, in the\nform of royalty, services or goods to the project affected regions and local\ncommunities.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In case, in utilising natural reso urces, the local community desires to make\ninvestment therein, the Federation, Province and Local Level shall accord priority to\nsuch investment in such portion as provided by law on the basis of the nature and size\nof such investment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The Government of Nepal shall have power to obtain foreign assistance\nand borrow loan s. Such assistance or loan s shall be so obtained or borrowed as to\nhave macro-economic stability of the country.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "Provisions relating to the management of budget deficits and other fiscal\ndiscipline of the Federation, Province and Local Level shall be as provided for in  the\nfederal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 60", "title": "Distribution of Sources of Revenue", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Federation, Province and Local Lev el\nmay impose taxes on matters falling within their respective  competence and collect\nrevenue from these sources.\nProvided that provisions relating to the imposition of taxes and collection of\nrevenue on matters enumerated in  the Concurrent List and on matters that are not\ncontained in the List of any level shall be as determined by the Government of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Government of Nepal shall make provisions for the equitable\ndistribution of the collected revenue to the Federation, Province and Local Level.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The amount of fiscal transfer receivable by Province and Local Level shall\nbe as recommended by the National Natural Resources and Fiscal Commission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The Government of Nepal shall, on the basis of the need of expenditu re\nand revenue capacity, distribute fiscal equalization grants to Province and Local\nLevel.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Each Province shall, in accordance with the provincial law, distribute fiscal\nequalization grants out of the grants received from the Government of Nepal and\nrevenues collected from its own sources, on the b asis of the need of expenditure  and\nrevenue capacity of its subordinate Local Level.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "Provisions relating to distribution of conditional grants, complementary\ngrants or special grants for other purposes to be provided by the Government of Nepal\nfrom the Federal Consolidated Fund shall be as provided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "While distributing revenues between the Federal, Provincial and Local\nLevels, it shall be made in a balanced and transparent manner.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "In making a federal Act on the distribution of revenues, regard shall be had\nto the matters of  national policies; national requirements; autonomy of the Province\nand Local Levels ; services to be r endered by the Province and Local Level  to the\npeople and financial powers granted to them; capacity to collect revenues; potentiality\nand use of revenues ; assistance to be made in development and construction ;\nreduction of regional imbalances ; poverty and inequality ; end of deprivation ; and\nassistance to be made in the performance of contingent works and fulfilment of\ntemporary needs.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-6", "title": "President and Vice-President", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 61", "title": "President", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a President of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall be the Head of State of Nepal. He or she shall perform\nhis or her functions in accordance with this Constitution and federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The President shall promote national unity of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The main duty of the President shall be to abide by and protect the\nConstitution.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 62", "title": "Election of President", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The President shal l be elected by an electoral college\nconsisting of the members of the Federal Parliament and members of the Provincial\nAssemblies. The voting weightage of the members of the Federal Parliament and of\nthe Provincial Assemblies shall vary as provided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Notwithstanding anything contained in clause (1), nothing shall be deemed\nto bar the formation of an electoral college for the purpose of election to the President\nby the sole reason that election to Provincial Assembly has not been held in any\nProvince.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A person who secures a majority of the then existing total votes of the\nElectoral College referred to in clause (1) shall be elected as the President.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "In case none of the candidates secures a majority pursuant to  clause (3),\nthere shall be the voting between the two candidates who have secured the highest\nnumber of votes, and a candidate who secures more than fifty percent of the total\nvotes in such voting shall be elected as the President.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In case none of the candidates secures more than fifty percent of the total\nvotes even in the voting under clause (4), re -voting shall be held. A candidate who\nsecures a majority of the t otal valid votes cast in such voting shall be elected as the\nPresident.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "In case  a person who holds a political office to be fulfilled by way of\nelection, nomination or appointment is elected as the President under this Article, such\noffice shall, ipso facto, fall vacant.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "Election to the President and other m atters related thereto shall be as\nprovided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 63", "title": "Term of Office of President", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The term of office of the President shall be  five years\nfrom the date on which he or she is elected.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President whose term of office under clause (1) has expired shall\ncontinue to discharge the functions under this Constitution until another elected\nPresident assumes his or her office.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 64", "title": "Qualification for President", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A person who has the following qualifications shall be\neligible to become the President:-\n(a)   One who is eligible to become a member of the Federal Parliament;\n(b)   On who has completed the age of at least forty-five years; and\n(c)  One who is not disqualified by any law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Notwithstanding anything contained in clause (1), a person who has\nalready been elected twice as the President shall not be eligible to be a candidate in\nthe election to the President.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 65", "title": "V acation of Office of President", "content": "The office of the President shall fall vacant in any of the\nfollowing circumstances:\n(a) In case he or she tenders resignation in writing to the Vice-President;\n(b) In case the motion of impeachment against him or her is adopted under\nArticle 101;\n(c) In case his or her term of the office expires;\n(d) In case he or she dies.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 66", "title": "Functions, Duties and Powers of President", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The President shall exercise such\npowers and perform such duties as conferred on him or her in accordance with  this\nConstitution or the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In exercising the powers or duties under clause (1), the President shall\nperform all other functions to be performed by him or her on recommendation and\nwith the consent of the Council of Ministers than those functions specifically provided\nto be performed  on recommendation of any institution or official under this\nConstitution or federal law. Such recommendation and consent shall be submitted\nthrough the Prime Minister.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Any decision or order to be issued in the name of the President under\nclause (2) an d other instrument of authorization pertaining thereto shall be\nauthenticated as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 67", "title": "Vice-President", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a Vice-president of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The functions to be performed by the President shall be performed by the\nVice-president during the absence of the President.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case  a person who holds a political office to be fulfilled by way of\nelection, nomination or appointment is elected as the Vice-president, such office shall,\nipso facto, fall vacant.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 68", "title": "V acation of Office of Vice-President", "content": "The office of the Vice-president shall fall vacant\nin any of the following circumstances:-\n(a) In case he or she tenders resignation in writing to the President,\n(b) In case a motion of impeachment against him or her is adopted under\nArticle 101,\n(c) In case his or her term of office expires,\n(d) In case he or she dies.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 69", "title": "Other provisions relating to Vice -President", "content": "Provisions relatin g to the qualification,\nprocedures of election and   term of office of the Vic e-President shall be the same as\nthat of the President.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 70", "title": "President and Vice-President to Belong to Different Sex or Community", "content": "Election to\nthe President and the Vice -president under this Constitution shall be so made as to\nhave representation of different sex or community.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 71", "title": "Oath by President and Vice -President", "content": "Prior to assuming their respective office s, the\nPresident shall take an oath of office and secrecy before the Chief Justi ce, and the\nVice-President, before the President, as provided for in the federal law.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 72", "title": "Remuneration and Facilities of President and Vice -President", "content": "The remuneration and\nother facilities of the President and the Vice -president shall be as provided  for in a\nFederal Act, and until such Act is enacted as specified by the Government of Nepal.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 73", "title": "Office of President and Vice -President", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be separate offices for the\nperformance of the functions of the President and the Vice-President.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Government of Nepal shall make arrangements for employees and\nother provisions as required to perform the functions of the offices referred to in\nclause (1).", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-7", "title": "Federal Executive", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 74", "title": "Form of Governance", "content": "The form of governance of Nepal shall be multi -party\ncompetitive federal democratic republican parliamentary form of governance based\non pluralism.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 75", "title": "Executive Power", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The executive power of Nepal shall, in accordance with  this\nConstitution and law, be vested in the Council of Ministers.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The responsibility for issuing general directives, controlling and regulatin g\nthe governance of Nepal shall, subje ct to this Constitution and law , lie in the Council\nof Ministers.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "All federal executive functions of Nepal shall be perf ormed in the name of\nthe Government of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Any decision or order to be issued in the name of the Government of Nepal\npursuant to clause (3) and other instruments of authorization pertaining thereto shall\nbe authenticated as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 76", "title": "Constitution of Council of Ministers", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The President shall appoint the leader of the\nparliamentary party that commands a majority in the House of Representatives as the\nPrime Minister, and the Council of Ministers shall be constituted under his or her\nchairpersonship.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In cases where no party has a clear majority in the House of\nRepresentatives pursuant to  clause (1), the President shall appoint as the Prime\nMinister a member of the House of Representatives who is able to command a\nmajority with the support of two or more parties representing to the House of\nRepresentatives.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In cases where the Prime Minister cannot be appointed pursuant to clause", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "within thirty days after the date of declaration of the final results of election to th e\nHouse of Representatives or where the Prime Minister so appointed fails to secure a\nvote of confidence pursuant to  clause (4), the President shall appoint as the Prime\nMinister the  leader of the parliamentary  party which has the highest number of\nmembers in the House of Representatives.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The Prime Minister appointed pursuant to  clause (2) or (3) shall  be\nrequired to secure the vote of confidence from the House of Representatives within\nthirty days after the date of such appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In cases where the Prime Minister appointed pursuant to clause (3) fails to\nsecure the vote of confidence pursuant to  clause (4) and any member referred to in\nclause (2) presents a ground on which he or she is able to secure the vote of\nconfidence in the H ouse of Representatives, the  President shall appoint such  member\nas the Prime Minister.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The Prime Minister appointed pursuant to clause (5) shall be required to\nsecure the vote of confidence pursuant to clause (4).", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "In cases where the Prime Minister appointed pursuant to clause (5) fails to\nsecure a vote of confidence or the Prime Minister cannot be appointed, the President\nshall, on the recommendation of the Prime Minister, dissolve the House of\nRepresentatives and appoint a date of election so that the election to another House of\nRepresentatives is completed within six months.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "Procedures as to the appointment of the Prime Minister under this Article\nshall be required to be completed within thirty-five days after the date of declaration\nof the final results of election to the House of Representatives held under this\nConstitution or the date on which the office of the Prime Minister has fallen vacant.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "The President shall, on recommendation of the Prime Minister , constitute\nthe Council of Ministers comprising a maximum of twenty -five Ministers including\nthe Prime Minister, in accordan ce with the inclusive principle , from amongst the\nmembers of the Federal Parliament.\nExplanation: For the purposes of this Article,  \"Minister\" means a Deputy Prime\nMinister, Minister, Minister of State and Assistant Minister.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": "The Prime Minister and Ministers shall be collectively responsible to the\nFederal Parliament, and the Ministers shall be individually responsible for the\nbusiness of their respective Ministries to the Prime Minister and the Federal\nParliament.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 77", "title": "Vacation of O ffice of Prime Minister and Minister", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The office of the Prime\nMinister shall fall vacant in any of the following circumstances: -\n(a) In case he or she tenders resignation in writing to the President;\n(b) In case a resolution of confidence is not adopted or a resolution of no\nconfidence is adopted against him or her pursuant to Article 100;\n(c) In case he or she ceases to be a member of the House of\nRepresentatives;\n(d) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The office of a Minister shall fall vacant in any of the following\ncircumstances: -\n(a) In case he or she tenders resignation in writing to the Prime Minister;\n(b) In case the Prime Minister removes him or her from the office;\n(c) In case the office of Prime Ministe r falls vacant pursuant to  sub-\nclause (a), (b) or (c) of clause (1);\n(d) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case the office of Prime Minister falls vacant pursuant to clause (1), the\nsame Council of Ministers shall continue to act until another Council of Ministers is\nconstituted.\nProvided that in case the Prime Minister dies, the senior -most Minister shall\nact as the Prime Minister until a new Prime Minister is appointed.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 78", "title": "Non-Member of Federal Parliament to be come Minister", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Notwithstanding\nanything contained in clause (9) of Article 76, the President may, on  the\nrecommendation of the Prime Minister, appoint a  person who is not a member of the\nFederal Parliament as a Minister", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Minister appointed pursuant to clause (1) shall be required to become a\nmember of the Federal Parliament  within six months from the date of taking oath by\nhim or her.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In the event of failure to obtain membership of the Federal Parliament\nwithin the period referred to in clause (2), he or she shall not be qualified to be\nreappointed to the office of Minister during the term of the then House of\nRepresentatives.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Notwithstanding anything contained in clause (1), a person who has  lost\nthe election to the then House of Representatives shall not be eligible to be appointed\nto the office of Minister  as referred to  in clause (1) during the term of such House of\nRepresentatives.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 79", "title": "Remuneration and other Facilities of Prime Minister and Ministers", "content": "The remuneration\nand other facilities of the Prime Minister and Ministers shall be as provided for in a\nFederal Act. It shall be as sp ecified by the Government of Nepal  until such Act is\nmade.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 80", "title": "Oath", "content": "The Prime Minister, Deputy Prime Minister and Ministers shall , prior to\nassuming their respective offices,  take an oath of office and secrecy before the\nPresident, and Ministers of State and Assistant Ministers, before the Prime Minister,\nas provided for in the federal law.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 81", "title": "To inform President", "content": "The Prime Minister shall inform the President on the following\nmatters:-\n(a) Resolutions of the Council of Ministers;\n(b) Bills to be introduced in the Federal Parliament;\n(c) Such other necessary information as commanded by the President on\nmatters set forth in clauses (a) and (b); and\n(d) Current general state of affairs of Nepal and matters concerning foreign\nrelations.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 82", "title": "Transaction of Business of Government of Nepal", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The business of the Government\nof Nepal shall be allocated and transacted in accordance with the rules approved by\nthe Government of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No question may be raised in any court as to whether or not the rules\nreferred to in clause (1) have been observed.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-8", "title": "Federal Legislature", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 83", "title": "Federal Legislature", "content": "There shall be a Federal Legislature consisting of two Houses to\nbe known as the House of Representatives and the National Assembly , which shall be\ncalled as the Federal Parliament.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 84", "title": "Composition of House of Representatives", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The House of Representatives shall\nconsist of a total of two hundred and seventy five members, as follows :-\n(a) One hundred and sixty-five members to be elected through the first\npast the post electoral system, with one being elected from each of\none hundred and sixty-five election constituencies delimited in\nNepal on the basis  of population and geographical convenience\nand specificity ;\n(b) One hundred and ten members to be elected through the proportional\nelectoral system where voters vote for political parties , with the whole\ncountry being considered as a single election constituency.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The federal law shall provide that  in filing candidacy by political parties\nfor the election to the House of Representatives under the proportional electoral\nsystem, representation shall be ensured on the basis of a closed list also from women ,\nDalit, indigenous nationalities ( Aadibasi Janajati) Khas Arya , Madhesi, Tharu,\nMuslims and backward regions, on the basis of popul ation. In so filing candidacy,\nregard shall also be had to geography and regional balance.\nExplanation: For the purpose s of this clause, \"Khas Arya \" means Kshetri, Brahmin,\nThakuri, Sanyasi (Dashnami) communities.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In filing candidacy pursuant to clause (2), political parties shall provide for\nrepresentation of the persons with disabilities as well.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Election to the House of Representatives referred to in clause (1) shall be\nheld through secret ballots in accordance with law.\n Amended by the First Amendment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Each citizen of Nepal who has completed the age of eighteen years shall\nhave the right to vote in any one election constitue ncy as provided for in the federal\nlaw.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "A person who is qualified pursuant to Article 87 and entitled to vote in an\nelection to the members of the House of Representatives may, subject to  the federal\nlaw, be a candidate in any election constituency.\nProvided that a person shall not be a candidate in more than one election\nconstituencies at the same time.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "In case  the seat of a ny member of the House of Representatives falls\nvacant while its term still remains for more than six months, the vacancy sh all be\nfulfilled in the same manner of electoral system as in which such seat was fulfilled.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "Notwithstanding anything contained elsewhere in this Part, at least one\nthird of the total number of members elected from each political party representing in\nthe Federal Parliament shall be women. In case  women are not so elected as to\nconstitute one third of the elected members of any political party pursuant to  sub-\nclause (a) of clause (1) and sub -clause (a) of c lause (2) of Article 86, such political\nparty m ust, in electing members under sub -clause (b) of clause (1), so elect that\nwomen members constitute at least one third of the total number of members elected\nto the Federal Parliament from that party.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "Election to the House of Representatives and othe r matters pertaining\nthereto shall be as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 85", "title": "Term of House of Representatives", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Unless dissolved earlier in accordance with\nthis Constitution, the term of the House of Representatives shall be five years.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Notwithstanding anything contained in clause (1), the term of the House of\nRepresentatives may be extended by a Federal Act for a period not exceeding one\nyear in cases where a proclamation or order of a state of emergency is in effect.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of the  House of Representatives extended pursuant to clause (2)\nshall ipso facto expire upon the expiry of six months from the date of revocation of\nthe proclamation or order of the state of emergency.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 86", "title": "Composition of National Assembly and Term of Office of its Members", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The\nNational Assembly shall be a permanent House.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The National Assembly shall consist of fifty-nine members as follows: -\n(a) Fifty six elected members consisting of at least three women, one\nDalit and one from persons with disabilities or minorities, from each\nProvince by an electoral college  consisting of members of the\nProvincial Assembly, chairpersons and vice-chairpersons of the Rural\nMunicipalities, and Mayors and Deputy-Mayors of the Municipalities,\nwith different weightage  of vote  by members of the Provincial\nAssembly, chairpersons and vice -chairpersons of the Rural\nMunicipalities, and Mayors and Deputy-Mayors of the Municipalities,\nas provided for in the federal law,\n(b) Three members consisting of at least one woman nomin ated by the\nPresident on the recommendation of the Government of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of office of the members of the National Assembly shall be  six\nyears. The term of office of one third of the members of the National Assembly shall\nexpire in every two years.\nProvided that, for the first time after the commencement of this Constitution,\narrangements shall be made by drawing lots to retire one -third of the members on the\nexpiry of two years, another one -third on the expiry of four years, and the final one -\nthird on the expiry of six years.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "In computing the term of office of the members of the National Assembly\nfor the first time after the commencement of this Constitution, the term of office of all\nmembers shall be deemed to have commenced on the day on which the first session of\nthe National Assembly is held.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Any vacancy of seat in the National Assembly shall be fulfilled for the\nremainder of the term of office in the same manner of election or nomination as in\nwhich the seat of the vacating member was fulfilled.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "Other matters relating to election to the members of the National Assembly\nshall be as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 87", "title": "Qualifications for Member", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A person who has the following qualifications shall be\neligible to become a member of the Federal Parliament:-\n(a) One who is a citizen of Nepal;\n(b) One who has completed the age of twenty -five years, for the House of\nRepresentatives, and of thirty-five years for the National Assembly;\n(c) One who has not been convicted of a criminal offense involving moral\nturpitude;\n(d) One who is not disqualified under any federal law; and\n(e) One who is not holding any office of profit.\nExplanation: For the purposes o f this clause, \"office of profit\" means any position,\nother than a political position which is to be fulfilled by election or nomination, for\nwhich a remuneration or financial benefit is paid out of a government fund.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No person may be a member of both Houses at the same time.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case  a person who holds a political office to be fulfilled by way of\nelection, nomination or appointment is elected or nominated as a member of the\nFederal Parliament under this Part, his or her office shall ipso facto fall vacant from\nthe day on which he or s he takes an oath of office of member of the Federal\nParliament.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 88", "title": "Oath", "content": "Every me mber of each House of the Federal Parliament shall be required ,\nbefore taking part for the first time in the  meeting of the House or any of its\ncommittees, to take an oath as provided for in the federal law.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 89", "title": "V acation of Seat", "content": "The seat of a member of the Federal  Parliament shall fall vacant in\nany of the following circumstances:-\n(a) In case he or she tenders resignation in writing to the Speaker or\nChairperson;\n(b) In case he or she is no longer qualified or ceases to possess the\nqualification pursuant to Article 87;\n(c) In case the term of the House of Representatives or the term of office of\nthe member of the National Assembly expires;\n(d) In case he or she is absent   in ten consecutive meetings without\nproviding information to the concerned House;\n(e) In case the political party of which he or she was a member when elected\nprovides a notification in accordance with the federal law that he or she\nhas defected from the party,\n(f) In case he or she dies.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 90", "title": "Decision as to Disqualification of Member", "content": "In case question arises as to whether any\nmember of the Federal Parliament is disqualified or has become disqualified pursuant\nto Article 87, the Constitutional Bench of the Supreme Court shall finally decide that\nquestion.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 91", "title": "Speaker and Deputy Speaker of House of Representatives", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The members of the\nHouse of Representatives shall, within fifteen days of the date of holding of the first\nmeeting of the House of Representatives , elect a Speaker and a Deputy Speaker from\namongst themselves.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Election pursuant to clause (1) shall be so held that there is one woman o ut\nof the Speaker and the  Deputy Speaker, and the Speaker and the Deputy Speaker of\nthe House of Representatives shall be representatives from different parties.\nProvided that in case there is no representation of more than one party in the\nHouse of Representatives or no candidacy is filed by more than one party in spite of\nrepresentation, nothing shall prevent the members of the same party from being the\nSpeaker and the Deputy Speaker of the House of Representatives.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case the office of the Speaker or the Deputy Speaker falls vacant,  the\nmembers of the House of Representatives  shall fulfil the vacancy by electing the\nSpeaker or Deputy Speaker from amongst themselves.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The Deputy Speaker shall, in the absence of the Speaker , preside over the\nHouse of Representatives.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In case election to the Speaker and the Deputy Speaker is not held or in\ncase both the positions  fall vacant, the attending member who is by age the senior -\nmost shall preside over the meeting of the House of Representatives.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The office of the Speaker o r Deputy Speaker of the House of\nRepresentatives shall fall vacant in any of the following circumstances:-\n(a) In case he or she  ceases to be a member of the House of\nRepresentatives;\nProvided that, in the event of dissolution of the House of\nRepresentatives, the Speaker and the Deputy Speaker of the House of\nRepresentatives holding their respective offices shall continue in\noffice until the previous day of the filing of nominations for another\nelection to the House of Representatives;\n(b) In case he or she tenders resignation in writing;\n(c) In case a resolution is adopted by a majority of two -thirds of the total\nnumber of the then members of the House of Representatives that his\nor her conduct is not compatible with his or her office.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The Deputy Speaker shall preside over  a meeting at which deliberations\nare to be held on a resolution that the conduct of the Speaker of the House of\nRepresentatives is not compatible with his or her office. The Speaker of the House of\nRepresentatives may take part and vote in the deliberations on such resolution.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 92", "title": "Chairperson and Vice-Chairperson of National Assembly", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The members of the\nNational Assembly shall, within fifteen days of the date of holding of its first meeting,\nelect the Chairperson and the Vice-Chairperson of the Nationa l Assembly from\namongst themselves.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Election pursuant to clause (1) shall be so held that there is one woman out\nof the Chairperson and the Vice-Chairperson of the National Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case the office of the Chairperson or Vice-Chairperson of the National\nAssembly falls vacant, the members of the National Assembly shall  fulfil the vacancy\nby electing its Chairperson or Vice-Chairperson from amongst themselves.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The Vice-Chairperson of the National Assembly shall, in the absence of its\nChairperson, preside over the National Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In case the election to the Chairperson and the Vice -Chairperson of the\nNational Assembly is not held or in case both the positions fall vacant, the member\nwho is by age the senior -most out of the attendin g members  shall preside over  the\nmeeting of the National Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The office of the Chairperson  or Vice-Chairperson of the National\nAssembly shall fall vacant in any of the following circumstances:-\n(a) In case he or she ceases to be a member of the National Assembly;\n(b) In case he or she tenders resignation in writing;\n(c) In case a resolution is adopted by a majority of two -thirds of the total\nnumber of the then members of the National Assembly that his or her\nconduct is not compatible with the office.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The Vice-Chairperson of the National Assembly shall preside over  a\nmeeting at which deliberations are to be held on a reso lution that the conduct of the\nChairperson of the National Assembly  is not compatible with his or her office. The\nChairperson of the National Assembly may take part and vot e in the deliberations on\nsuch resolution.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 93", "title": "Summoning and Prorogation of Session", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The President shall summon a session of\nthe Federal Parliament within thirty days of the declaration of final  results of  the\nelection to the House of Representatives. Thereafter, the President shall , from time to\ntime, summon sessions of both or either of the Houses in accordance with  this\nConstitution.\nProvided that the interval between the two consecutive sessions shall not\nexceed six months.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President may prorogue the sessions of both or either of the Houses of\nthe Federal Parliament.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case, during the prorogation or recess of the session of the House of\nRepresentatives, one-fourth of the total number of its members submit a requisition in\nwriting that it is  appropriate to convene a session or meeting, the President shall\nspecify the date and time for such session or meeting. The House of Representatives\nshall meet or commence its session at the date and time so specified.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 94", "title": "Quorum", "content": "Except as otherwise provided for in this Constitution, no question or motion\nshall be presented for a decision in a meeting of either House of the Federal\nParliament unless one-fourth of the total number of its members are present.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 95", "title": "Address by President", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The President may address either a meeting of any House or\na joint sitting of both Houses of the  Federal Parliament, and may summon the\nmembers for that purpose.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall ad dress the first s ession after election to the House  of\nRepresentatives and a joint sitting of both Houses of the Federal Parliament after the\ncommencement of the first session of each year.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 96", "title": "Deputy Prime Minister, Minister, Minister o f State and Assistant Minister e ntitled to take part in both Houses", "content": "The Deputy Prime Minister, Minister, Minister of State and\nAssistant Minister  shall be entitled to attend and take part in the proceedings and\ndeliberations of either House of the Federal Parliament or its committees.\nProvided that he or she shall not be entitled to vote in a House or its committee\nof which he or she is not a member.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 97", "title": "Constitution of Committees", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The House of Representatives and the National\nAssembly may constitute committees as provided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In case  a resolution is adopted by either House demanding that a joint\ncommittee of both the Houses be constituted for the purpose of managing the working\nprocedures between the two Houses of the Federal Parliament, resolving disagreement\non any Bill or for any other specified function,  a joint committee thereon shall be\nconstituted. The joint committee shall consist of a maximum of  twenty-five members\nin the ratio of five members from the House of Representatives to one member from\nthe National Assembly on the basis of inclusion.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 98", "title": "Transaction of Business In case of Vacancy of Seat of a Member", "content": "Either House of the\nFederal Parliament shall have the power to transact its business notwithstanding any\nvacancy in a seat of its member. No proceedings of either House of the Federal\nParliament shall become invalid even in case  it is subsequently discovered that a\nperson who was not so entitled took part in such proceedings.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 99", "title": "Voting", "content": "Except as otherwise provided  for in this Constitution, any motion submitted\nfor decision in either House of the Federal Parliament shall be decided by a majority\nvote of the members present and voting. The member presiding over the meeting shall\nnot have the right to vote.\nProvided that he or she may exercise the casting vote in case of a tie of votes.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 100", "title": "Provisions r elating to Vote of Confidence and  Motion of No C onfidence", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The\nPrime Minister may, whenever he or she considers necessary or appropriate to  show\nthat he or she has confidence from the House of Representatives, table a motion in the\nHouse of Representatives for the vote of confidence.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In case the political party, which the Prime Minister represents , is divided\nor a political party in coalition government withdraws its support, the Prime Minister\nshall table a motion in the House of Representatives for a vote of confidence within\nthirty days.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case a motion tabled pursuant to clauses (1) and (2) is not adopted by a\nmajority of the total number of the then members of the House of Representatives, the\nPrime Minister shall be relieved of his or her office.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "One-fourth of the total number of the then members of the House  of\nRepresentatives may table a motion of no confidence in writing that the House has no\nconfidence in the Prime Minister.\nProvided that a motion of no confidence shall  not be tabled until the first two\nyears after the appointment of the Prime Minister and until another one year after the\ndate of failure of the motion of no confidence once tabled.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "A motion of no confidence to be tabled pursuant to  clause (4) shall also\nmention the name of a member proposed for the Prime Minister.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "In case a motion of no confidence tabled pursuant to clause (4) is adopted\nby a majority of the total number of the then members of the House of\nRepresentatives, the Prime Minister shall be relieved of his or her office.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "In case the office of Prime Minister falls vacant because  of the adoption of\na motion of no confidence pursuant to  clause (6), the President shall , pursuant to\nArticle 76, appoint as the Prime Minister the member of the House of Representatives\nproposed pursuant to clause (5).", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 101", "title": "Impeachment", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "One fourth of the total number of the then members of the House of\nRepresentatives may move a motion of impeachment against the President or Vice -\nPresident on the ground of serious violation of this Constitution and law.  In case the\nmotion is adopted by at least two thirds majority of the total number of the then\nmembers of both Houses of the Federal Parliament, he or she shall  be relieved of his\nor her office.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "One fourth of the total number of the then members of the House of\nRepresentatives may move a motion of impeachment against the Chief Justice  of\nNepal or a Justice of Supreme Court, member of the Judicial Council, chief or official\nof a Constitutional Body on the ground of his or her failure to fulfil his or her duties\nof the office because of serious violation of this Constitution and law,  incompetence\nor misconduct or failure to discharge the duties of the office honestly or serious\nviolation of the code of conduct . In case the motion is adopted by at least two thirds\nmajority of the total number of the then members of the House of Representatives, the\nconcerned person shall be relieved of his or her office.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "There shall be an impeachment recommendation committee in the House\nof Representatives for the purpose of making recommendation after inquiring into\nwhether or not there exists ground and reason for moving a motion of impeachment\nagainst any person referred to in clause (2).", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The committee referred to in clause (3) shall consist of eleven members of\nthe House of Representatives.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In case at least three members of the House of Representatives certi fy and\nsubmit that the received information, notice or complaint is admissible on the ground\nof serious violation of the Constitution or incompetence or misconduct or failure to\ndischarge the dut ies of office honestly or serious violation of the code of conduct by\nthe person relieving of office on impeachment  pursuant to  clause (2) , and the\ncommittee referred to in clause (3) makes recommendation, upon inquiring into such\ncomplaint in accordance w ith federal law , to the House of Representatives for\nimpeachment proceedings , a motion of impeachment may be moved pursuant to\nclause (2).", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "After the commencement of impeachment proceedings pursuant to clause", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": ", the Chief Justice  of Nepal or the Justice of Supreme Court , the member of the\nJudicial Council, the chief or official of the Constitutional Body shall not be allowed\nto discharge the duties of his or her office pending the settlement of such proceedings.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "A person who is charged with im peachment pursuant to clause (1) or (2)\nshall be provided with a reasonable opportunity to defend himself or herself.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "Nothing shall bar the taking of action under the federal law  in relation to\nthe offence, if any, committed while in office by the President or Vice-President, the\nChief Justice of Nepal or a Justice of Supreme Court  of Nepal, the member of the\nJudicial Council, the chief or official of a Constitutional Body  who is relieved of\noffice upon the adoption of a motion of impeachment under this Article.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "A person who is relieved of the office on the adoption of a motion of\nimpeachment pursuant to clause (1) or (2) shall not be entitled  to obtain any facility\naccruing from such office and to be appointed or nominated to any public office in the\nfuture.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": "Other matters  relating to impeachment shall be as provided for in the\nfederal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 102", "title": "Penalty for Unauthorized Presence or Voting", "content": "In case a person who has not taken oath\npursuant to Article 88 or who is not a member of the Federal Parliament is present or\ncasts vote in the capacity of a member in a meeting of either House of the Federal\nParliament or of its committee, the person shall, by order of the person presiding over\nthe meeting, be fined with a sum of five thousand rupees fo r each instance of such\npresence or voting, and such fine shall be recovered as a government due.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 103", "title": "Privileges", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be full freedom of speech in both Houses of the Federal\nParliament; and no member shall be arrested, detained or prosecuted in any court for\nanything expressed or any vote cast by him or her in the House.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Each House of t he Federal Parliament shall, subject to this Constitution,\nhave full power to regulate and decide its internal business, and the concerned House\nshall have the exclusive right to decide whether or not any of its proceedings is\nregular or irregular. No question shall be raised in any court in this regard.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "No comment shall be made about good faith concerning any proceeding of\nany House of the Federal Parliament, and no publication and broadcasting of any type\nshall be made about anything said by any member, intentionally distorting or\nmisinterpreting the meaning of the speech.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The provisions of clauses (1) and (3) shall apply also to persons, other than\nthe members of the Federal Parliament, who are entitled to participate in the meetings\nof the House.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "No proceedings shall be initiated in any court against any person in respect\nof the publication , under the authority granted by any House of the Federal\nParliament, of any document, report, vote or proceeding.\nExplanation: For the purposes of  this clause and clauses (1), (2), (3) and (4), \" House\"\nmeans the House of Representatives or the National Assembly, and includes a joint\nsitting or committee or joint committee of the Federal Parliament.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "No member of the Federal Parliament shall be arrested during the period\nfrom the issuance of a notice summoning the session to its prorogation.\nProvided that nothing in this clause shall be deemed to prevent the arrest under\nthe federal law  of any member on a criminal charge. In case  any member is so\narrested, the authority ma king such arrest shall forthwith give information ther eof to\nthe person presiding over the concerned House.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "Any breach of the privileges shall be deemed to constitute the contempt of\nthe Federal Parliament, and  the concerned House  shall have the exclusive right to\ndecide whether or not any privilege has been breached.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "In case any person is in contempt of any House, the person presiding over\nthe concerned House may, after a decision by the House to that effect, admonish, warn\nor impose a sentence of imprisonment for a term not exceeding three months or of a\nfine not exceeding ten  thousand rupees on such  person, and  such fine  shall be\nrecovered as a government due.\nProvided that in case  such person apologies  to the satisfaction of the\nconcerned House, the House may pardon, remit or commute the sentence imposed on\nhim or her.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "Other matters relating to the privileges of the Federal Parliament shall be\nas provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 104", "title": "Procedures relating to Conduct of Business", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Each House of the Federal Parliament\nshall frame rules to conduct its business, maintain order du ring its meetings and\nregulate the constitution, functions and procedures of the committees  and procedures\nof the  House or its committee.  Until such rules are framed, the Federal Parliament\nshall regulate its procedures on its own.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The conduct of business of the joint sitting of the Federal Parliament and\nconstitution and proceedings of the joint committee of the  Federal Parliament shall be\nregulated by the rules or procedures approved by the joint sitting of both Houses of\nthe Federal Parliament.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 105", "title": "Restriction on Discussion", "content": "No discussion shall be held in either House of the Federal\nParliament on any matters that may cause adverse effect on the dispensation of justice\nin cases which are sub judice in any court of Nepal and in any judicial act carried out\nby Judges in the course of performance of their duties.\nProvided that nothing in this Artic le shall be deemed to bar the expression of\nopinions about the conduct of a Judge during deliberations held on a motion of\nimpeachment.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 106", "title": "Secretary General and Secretary of Federal Parliament", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The President shall\nappoint the Secretary General of the House of Representatives on recommendation of\nboth the Speaker of the House of Representatives and the Chairperson of the National\nAssembly, the Secretary of the House of Representatives on recommend ation of the\nSpeaker, and the Secretary of the National Assembly on recommendation of the\nChairperson.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The qualification, functions, duties, powers and other conditions of service\nof the Secretary General of the Federal Parliament, Secretary of the Hou se of\nRepresentatives and Secretary of the National Assembly shall be as provided  for in\nthe federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 107", "title": "Secretariat of Federal Parliament", "content": "There shall be a Secretariat for conducting and\nmanaging the business of the Federal Parliament. The establish ment of such\nSecretariat and other matters related thereto shall be as provided for in the federal law.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 108", "title": "Remuneration", "content": "The remuneration and facilities of the Speaker and the Deputy Speaker\nof the House of Representatives, the Chairperson and the Vice-Chairperson of the\nNational Assembly , chairpersons of the committees and members of the Federal\nParliament shall be as provided for in the federal law, and shall be as specified by the\nGovernment of Nepal until such law is made.", "children": []}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-9", "title": "Federal Legislative Procedures", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 109", "title": "Legislative Powers of Federal Parliament", "content": "The legislative powers of the Federal\nParliament shall be as enumerated  in the lists of Schedule -5, Schedule -7 and\nSchedule-9.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 110", "title": "Procedures for Introduction of Bills", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A Bill may, subject to this Constitution, be\nintroduced in any House of the Federal Parliament.\nProvided that a Money Bill shall be introduced only in t he House of\nRepresentatives.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Money Bill and a Bill concerning a security institution including the\nNepal Army, Nepal Police and Armed Police Force, Nepal shall be introduced only as\na Government Bill.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "\"Money Bill\" means a Bill concerning any or all of the following matters: -\n(a) Matters concerning Imposition, collection, abolition, re mission,\nalteration or regulation of taxes;\n(b) Matters concerning preservation of the Federal Consolidated Fund or\nany other Federal Government Fund, the deposit of moneys into or\nthe appropriation or the withdrawal of moneys from such Funds, or\nthe reduction, increment or cancellation of appropriations of propos ed\nexpenditures from such Funds;\n(c)  Regulation of matters relating to the borrowing of money or the\nguarantee to be given  by the Government of Nepal, or any matter\npertaining to the amendmen t of the law with respect to any financial\nobligations undertaken or to be undert aken by the Government of\nNepal,\n(d) Matters concerning custody of all revenues received by  the Federal\nGovernment Fund, moneys acquired through the repayment of loans,\nand grant moneys, investments to be made or accounts or audits of the\naccounts of the Government of Nepal; and\n(e) Other incidental matters  directly related to any of the matters\nspecified in clause (a), (b), (c) or (d).\nProvided that any Bill shall not be deemed to be a Money Bill only by\nthe reason that it provides for the levying of any charges , fees or tariff such as\nlicense fee, application fee, renewal fee or for the imposition of fines or\npenalty of imprisonment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "In case any question arises as to whether or not a Bill is a Money Bill, the\ndecision of the Speaker shall be final.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 111", "title": "Procedures for Adoption of Bills", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A Bill adopted by one House of the Federal\nParliament shall be transmitted to the other Hous e as soon as possible and such  Bill\nshall, if adopted by the receiving House, be submitted to the President for\nauthentication.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Money Bill adopted by the House of Representatives shall be\ntransmitted to the National Assembly.  The National Assembly  shall, after\ndeliberations on such  Bill, send the Bill back to the House  of Representatives within\nfifteen days from the date of receipt of the Bill, with suggestions, if any.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The House of Representatives shall, upon deliberations on a Bill returned\nwith suggestion s pursuant to clause (2), present the Bill  incorporating such\nsuggestions as it may deem appropriate to the President for authentication.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "In case  the National Assembly  does not return a Money Bill received\npursuant to clause (2) for more  than fifteen days, the House of Representatives may\npresent the Bill to the President for authentication.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Any Bill, except for a Money Bill, adopted by the House  of\nRepresentatives and transmitted to the National Assembly shall be returned with\napproval or suggestions within two months from the date of receipt. In case  the\nNational Assembly  does not return the Bill within that period, the House  of\nRepresentatives may, by a resolution adopted by a majority of the total number of its\nthe then existing members, present the Bill to the President for authentication.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "In case any Bill, other than a Money Bill, adopted by one House is rejected\nor is accepted with amendments by the other House, the  Bill shall be returned to the\nHouse where it was originated.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "In case the House of Representatives, in considering a Bill which has been\nrejected or amended and returned by the National Assembly pursuant to  clause (6),\nadopts it again as it was or with amendments, by a majority of the total number of the\nthen existing members, the Bill shall be submitted to the President for authentication.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "In case a Bill which has been returned with amendments by the House of\nRepresentatives to the National Assembly pursuant to clause (6) is also again adopted,\nwith such amendments, by a majority of the number of the then existing members of\nthe National Assembly, the Bill shall be submitted to the President for authentication.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "The following Bills shall be referred to a joint sitting of the both Houses,\nand in case the joint sitting adopts the Bill as it was or with amendments, the House in\nwhich the Bill originated shall present it to the President for authentication:-\n(a) A Bill which, though adopted by the National Assembly, ha s been\nrejected by the House of Representatives; or\n(b) A Bill which has  been sent back  to the National Assembly  with\namendments by the House  of Representatives , but the National\nAssembly has not agreed on such amendments.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": "Even though a session of a House is prorogued  while a Bill is under its\nconsideration, deliberations on the Bill may continue at the succeeding session.\nProvided that in case the House of Representatives  is dissolved or its term\nexpires when any Bill introduced in the  House of Representatives  is under its\nconsideration or when any Bill adopted by the  House of Representatives is under\nconsideration in the National Assembly, such Bill shall lapse.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 112", "title": "Withdrawal of Bills", "content": "A Bill may be withdrawn by the member introducing it with the\napproval of the House.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 113", "title": "Authentication on Bills", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Bill to be presented to the President for\nauthentication pursuant to Article 111  shall be certified by the Speaker or the\nChairperson of the House in which the Bill originated and so presented.\nProvided that in case of a Money Bill, the Speaker shall so certify.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Bill presented to the President for his or her authentication in accordance\nwith this Article shall be authenticated within fifteen days, and both Houses shall be\ninformed thereof as soon as possible.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case the President is of the opinion that any Bill , except a Money Bill,\npresented for authentication needs reconsideration, he or she may, within fifteen days\nfrom the date of submission of such Bill,  send back  the Bill along with his or her\nmessage to the House in which the Bill originated.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "In case any Bill is sent back along with a message by the President , and\nboth Houses reconsider and adopt such Bill as it was or with amendments and present\nit again, the President shall authenticate that Bill within fifteen days of such\npresentation.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "A Bill shall become an Act after the President authenticates it.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 114", "title": "Provisions relating to Ordinance", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "In case, at any time, except when both Houses of\nthe Federal Parliament are in session, circumstances exist which render it necessary to\ntake immediate action, the President may, on recommendation of the Council of\nMinisters, promulgate an Ordinance.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Ordinance promulgated pursuant to  clause (1) shall have the same\nforce and effect as an Act.\nProvided that every such Ordinance,-\n(a) Shall be tabled at the session of both Houses of the Federal\nParliament held after the promulgation, and in case not adopted by\nboth Houses, it shall, ipso facto, cease to be effective;\n(b) May be repealed at any time by the President; and\n(c) Shall, unless rendered ineffective or repealed pursuant to sub-clause\n(a) or (b), ipso facto cease to be effective at the expiration of sixty\ndays after the day on which a meeting of both Houses is held.\nExplanation: For the purposes of this clause, \"day on which a meeting of both\nHouses is held\" means the day on which a session or meeting of both Houses\nof the Federal Parliament commences or is held , and this term means  the later\nday on which a meeting of the House is held in case the Houses of the Federal\nParliament meet on different dates.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-10", "title": "Federal Financial Procedures", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 115", "title": "No tax to be levied or Loan to be raised", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No tax shall be levied and collected\nexcept in accordance with law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No loan shall be raised and guarantee be given by the Government of\nNepal except as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 116", "title": "Federal Consolidated Fund", "content": "Except for the revenues of trusts ( Guthi), all revenues\nreceived by the Government of Nepal, all loans raised on the security of reven ues, all\namounts received in repayment of any loan made under the authority of any Act and\nany other mo neys received by the Government of Nepal shall , except as otherwise\nprovided by a Federal Act, be credited to a Government Fund to be known as the\nFederal Consolidated Fund.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 117", "title": "Expenditures from  Federal Consolidated Fund or Federal Government Fund", "content": "No\nexpenditure shall be incurred out of the Federal Consolidated Fund or any other\nFederal Government Fund except the following:-\n(a) Moneys charged on the Federal Consolidated Fund;\n(b) Moneys required to  meet the expenditure under a Federal\nAppropriation Act;\n(c) Advance moneys authorized by a Federal Act required to meet\nexpenditures, when an Appropriation Bill is under consideration; or\n(d) Expenditures to be incurred in extraordinary circumstances under a\nFederal V ote of Credit Act, which  contains only a description of\nexpenditures.\nProvided that matters relating to the Federal Contingency Fund\nshall be governed by Article 124.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 118", "title": "Expenditures Chargeable on Federal Consolidated Fund", "content": "The expenditures relating to\nthe following matters shall be charged on the Federal Consolidated Fund, and\napproval of the Federal Parliament shall not be required for such expenditures:-\n(a) The amount required as remuneration and facilities of the P resident and\nthe Vice-president;\n(b) The amount required as remuneration and  facilities payable to the Chief\nJustice of Nepal, Justices of the Su preme Court, and  members of the\nJudicial Council;\n(c) The amount required as remuneratio n and facilities payable to the\nSpeaker and the Deputy Speaker of the House of Representatives, and\nthe Chairperson and the Vice Chairperson of the National Assembly;\n(d) The amount required as remuneration and facilities payable to the chiefs\nand officials of the Constitutional Bodies,\n(e) The amount required as remuneration and facilities of the Chiefs of\nProvinces,\n(f) The administrative expenses of the Office of the President or the Vice\nPresident, the Supreme Court, the Judicial Counci l, the Constitutional\nBodies, and the offices of Chiefs of Provinces;\n(g) All charges relating to debts for which th e Government of Nepal is\nliable;\n(h) Any sum required to satisfy any judgment or decree made by a court\nagainst the Government of Nepal; and\n(i) Any other sum to be chargeable  by the federal law  on the Federal\nConsolidated Fund.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 119", "title": "Estimates of Revenues and Expenditures", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Minister for Finance of the\nGovernment of Nepal shall, in respect of every fiscal year, lay before the joint sitting\nof both Houses of the Federal Parliament an annual estimate setting out, inter alia, the\nfollowing matters:-\n(a) Estimate of revenues;\n(b) Moneys required to meet the charges on the Federal Consolidated\nFund; and\n(c) Moneys required to meet the expe nditure to be provided for  in the\nFederal Appropriation Act.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The annual estimate to be laid pursuant to clause (1) shall also be\naccompanied by a statement of the expenses allocated to every Ministry in the\nprevious fiscal year and particulars of whether or not the objectives of the expenses\nhave been achieved.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Minister for Finance of the Government of Nepal shall lay before the\nFederal Parliament an estimate of revenues and expenditures referred to in clause (1)\non the 15th of Jeshta (mid May) each year.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 120", "title": "Appropriation Act", "content": "The moneys to b e spent under an  Appropriation Act shall be\nspecified under concerned heads in the Appropriation Bill.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 121", "title": "Supplementary Estimate", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Minister for Finance of the Government of Nepal\nmay lay before the House of Representatives  a supplementary estimate in case it is\nfound in any fiscal year:-\n(a) That the sum authorized to be spent for a particular service by the\nAppropriation Act for the current fiscal year is insufficient, or that a\nneed has arisen for expenditures on some new  service not provided\nfor in the Appropriation Act for that year; or\n(b) That the expenditures made during that fiscal year are in excess of the\namount authorized by the Appropriation Act.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The sums included in the supplementary estimate  shall be specified under\nthe related heads in a Supplementary Appropriation Bill.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 122", "title": "V otes on Account", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Notwithstanding anything contained elsewhere in this Part, a\nportion of the expenditure estimated for the fiscal year may, when an Appropriation\nBill is under consideration, be incurred in advance, as provided for in Federal Act.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No V ote on Account Bill shall be introduced until the estimates of revenues\nand expenditures have been laid pursuant to Article 119, and the sums involved in the\nV ote on Account shall not exceed one -third of the estimate of expenditures for the\nfiscal year.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The expenditures incurred in accordance with the Federal V ote on Account\nAct shall be included in the Appropriation Bill.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 123", "title": "V otes of Credit", "content": "Notwithstanding anything contained elsew here in this Part, in case\nowing to an emergency due to either natural causes or a threat of external aggression\nor internal disturbances or other reasons, it appears to be impractical or inexpedient in\nview of the security or inter est of the State to specify the d etails required pursuant to\nclause (1) of Article 119, the Minister for Finance of the Government of Nepal may\nlay before the House of Representatives a V ote of Credit Bill giving only a statement\nof expenditures.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 124", "title": "Federal Contingency Fund", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A Federal Act may create a fund to be known as the\ncontingency fund into which such moneys as may be determined by  the Federal Act\nshall be deposited from time to time.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The fund referred to in the clause (1) shall be under the control of the\nGovernment of Nepal and may meet any unforeseen expenditure out of such fund.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The amount of the expenditure referred to in  clause (2) shall be\nreimbursed as soon as possible as provided for in the Federal Act.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 125", "title": "Act relating to Financial Procedures", "content": "Matters relating to the transfer of moneys\nappropriated by a Federal Act from one head to another and other financial procedures\nshall be as provided for in the Federal Act.", "children": []}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-11", "title": "Judiciary", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 126", "title": "Courts to Exercise Powers relating to Justice", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Powers relating to justice in Nepal\nshall be exercised by courts and other judicial  institutions in ac cordance with this\nConstitution, other laws and recognized principles of justice.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "All shall abide by the orders or deci sions made by courts in the course of\nhearing of lawsuit.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 127", "title": "Courts", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be the following courts in Nepal:-\n(a) Supreme Court;\n(b) High Court; and\n(c) District Court.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In addition to the c ourts referred to in clause (1), judicial institutions may\nbe constituted at the local level to tr y cases under law or other institutions as required\nmay be formed to pursue alternative dispute resolution methods.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 128", "title": "Supreme Court", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a Supreme Court of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Supreme Co urt shall be a court of record. All courts and judicial\ninstitutions shall, except as otherwise provided in this Constitution, be under the\nSupreme Court.  The Supreme Court shall have the final authority to interpret this\nConstitution and laws.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Supreme Court may inspect, supervise an d give necessary directives\nto, itself and courts, specialized courts or other judicial institutions under its\njurisdiction, on matters relating to administration of justice or management.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "All shall abide by any interpretation of the Constitution or a law made by\nor any legal principle laid down by the Supreme Court in the course of hearing a\nlawsuit. In case anyone makes obstruction in the dispensation of justice or disregard\nany order or judgment handed down  by it or any of its subordinate courts, the\nSupreme Court may , in accordance with law,  initiate proceedings of contempt and\nimpose punishment therefor.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 129", "title": "Appointment and Qualification of Chief Justice of Nepal and Justices of Supreme Court", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Supreme Court shall consist of a maximum of twenty Justices, in\naddition to the Chief Justice of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall appoint the Chief Justice  on recommendation of the\nConstitutional Council and other Justices of the Supreme Court  on recommendation\nof the Judicial Council.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Any person who has served as a Justice of the Supreme Court for at least\nthree years shall be eligible for appointment as the Chief Justice.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The term of office of the Chief Justice shall be six years.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Any citizen of Nepal  who has  obtained a bachelor 's degree in law and\nserved as the Chief Judge or a Judge of a High Court for at least five years or who has\nobtained a bachelor's degree in law and constantly practised law as a senior  advocate\nor advocate for at least fifteen years or who is a distinguished jurist having constantly\nworked for at least fifteen years in the judicial or legal field or who has served in the\npost of Gazetted first class or a higher post of the Judicial Service  for at least twelv e\nyears shall be deemed  to be eligible for appointment as a Justice of the Supreme\nCourt.\nExplanation: The period during which one has served as the Chief Judge or Judge of\nan Appellate Court prior to the commencement of this Constitution shall, for the\npurposes of this clause, be deemed to be the period of service in the capacity of the\nChief Judge or Judge of the High Court.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "In case the office of the Chief Justice f alls vacant or the Chief Justice is\nunable to carry out the duties of his or her office by reason of illness or otherwise or\nhe or she cannot be present in the Supreme Court by reason of a leave of absence or\nhis or her being outside of Nepal, the senior -most Justice of Supreme Court  shall act\nas the Acting Chief Justice.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 130", "title": "Conditions of Service and Facilities of Chief Justice and Justices", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "In case the Chief\nJustice or a Justice of the Supreme Court who has served for at least five years resigns\nor undergoes compulsory retirement or dies, he or she shall be entitled to such pension\nas may be provided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Except otherwise provided for in this Constitution, the remuneration and\nother conditions of service of the Chief Justice an d Justices of the Sup reme Court\nshall be as provided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Notwithstanding anything contained in clauses (1) a nd (2), the Chief\nJustice or a  Justice of the Supreme Court who has been removed from the office by\nway of impeachment or who has been punished by a court for a criminal offence\ninvolving moral turpitude shall not be entitled to gratuity or pension.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The remuneration and other conditions of service of the Chief Justice or a\nJustice of the Supreme Court shall not be altered to his or her disadvantage.\nProvided that this provision shall not apply in case s where a state of\nemergency is declared because of extreme economic disarrays.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 131", "title": "V acation of office of Chief Justice or Justice of Supreme Court", "content": "The office of t he\nChief Justice or a Justice of the Supreme Court shall fall vacant  in any of the\nfollowing circumstances:-\n(a) In case he or she tenders resignation in writing to the President;\n(b) In case he or she attains the age of sixty-five years;\n(c) In case a motion of impeachment is adopted against him or her pursuant\nto Article 101;\n(d)  In case the Chief Justice or a Justice of Supreme Court is relieved of his\nor her office by the President, in the case of Chief Justice on\nrecommendation of the Constitutional Council, and in the case of Justice\nof Supreme Court, on  recommendation of the Judicial Council, on the\nground that he or she is unable to discharge hi s or her duties because of\nphysical or mental illness;\n(e) In case he or she is punished by a court for a criminal offence involving\nmoral turpitude;\n(f) In case he or she dies.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 132", "title": "Chief Justice and Justice of Supreme Court not to be engaged in Any Other Office", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No Chief Justice or Justice of the Supreme Court shall be engaged in or deputed to\nany office other than that of a Judge.\nProvided that the Government of Nepal may, in consultation with the Judicial\nCouncil, depute a Justice of the Supreme Court to work concerning judicial inquiry, or\nto legal or judicial investigation or research for a specified period.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No person who has once held the office of Chief Justice or a Justice of the\nSupreme Court shall be eligible for appoi ntment to any government office, except as\notherwise provided for in this Constitution.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 133", "title": "Jurisdiction of Supreme Court", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Any citizen of Nepal may file a petition in the\nSupreme Court to have any law or any part thereof declared void on the ground of\ninconsistency with this Con stitution because it imposes unreasonable rest riction on\nthe enjoyment of any fundamental right conferred by this Constitution or on any other\nground; or to have  any law or any part thereof made by a Provincial Assembly\ndeclared void because it is inconsistent with any law made by the Federal Parliament ;\nor to have any law or any part thereof made by a Municipal Assembly or Rural\nMunicipal Assembly declared void because it is inconsistent with a law made by the\nFederal Parliament or the Provincial Assembly; the Supreme Court shall have  an\nextra-ordinary power to declare such law to be void either ab initio or from the date of\nits decision in case the law in question  appears to be so inconsistent.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Supreme Court shall, for the enforcement of the fundamental rights\nconferred by this Cons titution or of any other legal right for which no other remedy\nhas been provided for or for which the remedy even though provided appears to be\ninadequate or ineffective or for the settlement of a ny constitutional or legal question\ninvolved in any dispute of public interest or concern ; have the extraordinary power to\nissue necessary and appropriate orders , provide appropriate remedies, enforce such\nright or settle such dispute.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Under the extra-ordinary jurisdiction referred to in clause (2), the Supreme\nCourt may issue appropriate orders and writs including the writs of habeas corpus,\nmandamus, certiorari, prohibition and quo warranto.\nProvided that  except on the ground of absence of juris diction, the Supreme\nCourt shall not under this clause interfere with any internal proceedings of the Federal\nParliament or Provincial Assembly, and with any proceedings instituted by the Federal\nParliament or Provincial Assembly concerning violation of its privileges and penalties\nimposed therefor.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Subject to this Constitution, the Supreme Court shall, as provided for in the\nfederal law , have the power to originally try and settle cases, hear appeals, test\njudgments referred for confirmation, revise cases, hear petitions or review its\njudgments or final orders.  While so reviewing the judgements,  Justices other than\nthose having handed down the previous judgment shall make such review.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The Supreme Court shall  have the power to settle  appeals from cases\noriginally heard and settled by a High Court and matters of public importance\ninvolving questions of interpretation of the Constitution and law or cases\nrecommended by a High Cou rt, accompanied by its opinion that it is reasonable that\ndecision be made by the Supreme Court.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "Other powers and procedures of the Supreme Court shall be as provided\nfor in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 134", "title": "Power to Transfer Cases", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "In case the cases which involve substantially the same\nquestions are sub judice before the Supreme Court and a High Court, and the Supreme\nCourt is satisfied on  its own or on application by the Attorney General or parties to\nsuch cases that such questions are of public importance, the Supreme Court shall have\nthe power to procure and adjudge the cases together.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In case there exists a special circumstance where judicial impartiality may\nbe questioned if a case filed in a High Court is heard by that Court, the Supreme Court\nmay, stating the reasons and grounds thereof, order such case to be transferred from\nsuch High Court to another High Court and be heard by the latter High Court , in\naccordance with law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 135", "title": "Not to be engaged in Practice of Law", "content": "No Chief Justice or Justice of the Supreme\nCourt shall, after retirement from office , be engaged in the practice of law, mediation\nor arbitration proceedings before any office or court.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 136", "title": "Responsibility of Chief Justice", "content": "The Chief Justice shall have the ultimate\nresponsibility to make effective the administration of justice by the Supr eme Court,\nsubordinate courts, specialized courts or other judicial institution.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 137", "title": "Constitution of Constitutional Bench", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a Constitutional Bench in the\nSupreme Court. The Constitutional Bench shall consist of the Chief Justice and other\nfour Justices designated by the Chief Justice on recommendation of the Judicial\nCouncil.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Bench referred to in clause (1) shall originally hear and settle the\nfollowing cases, in addition to the petitions filed pursuant to clause (1) of Article\n133:-\n(a) Disputes relating to jurisdiction between the Federation and a\nProvince, between Provinces, between a Province and a Local Level\nand between Local Levels;\n(b) Disputes relating to election to members of the Federal Parliament or\nProvincial Assembly and matters  relating to disqualification of a\nmember of the Federal Parliament or of the Provincial Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Notwithstanding anything contained in Article 133, in case it appears that\nany case sub judice in the Supreme Court involves a question of serious constitutional\ninterpretation, the Chief Justice may appoint such case to be heard by the Bench\nreferred to in clause (1).", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Other provisions relating to the functioning of the Constitutional Bench\nshall be as determined by the Supreme Court.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 138", "title": "Annual Report", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Supreme Court,  Judicial Council and Judicial Service\nCommission shall submit every year annual reports to the President, and the President\nshall submit such reports to the Federal Parliament through the Prime Minister.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In case  the Federal Parliament, upon deliberating on the annual reports\nsubmitted pursuant to clause (1), deems it necessary to give any suggestion, it may\ngive such suggestion to the concerned institution through the Government of Nepal,\nMinistry of Law and Justice.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Other provisions relating to annual reports referred to in clause (1) shall be\nas provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 139", "title": "High Courts", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a High Court in each Province.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In case  anyone makes obstruction in the dispensation of justice by, or\ndisregard any order or judgment handed down by, it or any of its subordinate courts or\njudicial institutions, the High Court may initiate proceedings on and impose\npunishment for contempt, as provided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Each High Court shall consist of such number of Judges, in addition to t he\nChief Judge, as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 140", "title": "Appointment and Qualification of Chief Judge and J udges of High Court", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The\nChief Justice shall, on recommendation of the Judicial Council, appoint the Chief\nJudge and Judges of the High Court.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Any citizen of Nepal who has obtained a bachelor 's degree in law and\nserved as a Judge of a District Court for at least five years or w ho has obtained a\nbachelor's degree in law and constantly practised law as a senior advocate or advocate\nfor at least ten years or who has constantly been engaged in the teaching or research\nof law or in any other field relation to law or justice for at le ast ten years or who has\nserved in the post of at least Gazetted first class of the Judicial Service for at least five\nyears shall be deemed to be eligible for appointment as the Chief Judge or a Judge of\nthe High Court.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Appointments to the Chief Judge and Judges of a High Court shall be made\nfrom amongst the persons who have possessed the qualification s referred to in clause", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "on the basis of the proportion of cases settled by him or her annually and of\nevaluation of cases upheld, quashed or reversed  by superior court s in the course of\nfinal decision thereof, in the case of a District Judge, and of his or her seniority,\nqualification and evaluation of standard of performance of business , in the case of a\nperson who has served in the post of at least G azetted first class of the Judicial\nService, and of evaluation of seniority, professional continu ity, honesty, professional\nconduct and contribution made to the field of law and justice, in the case of others.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "In case  the office of the Chief Judge falls vacant or the Chief Judge is\notherwise unable to carry out the duties of his or her office or cannot be present in the\nHigh Court by reason of a leave of absence or his or her being outside of the Province,\nthe senior-most Judge of the High Court shall act as the Acting Chief Judge.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 141", "title": "Conditions of Service and Facilities o f C hief Judge and Judges", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Except  as\notherwise provided for in this Constitution, the remuneration and other conditions of\nservice of the Chief Judge and Judges of the High Court shall be as provided for in the\nfederal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Notwithstanding anything contained in clause (1), the Chief Judge or a\nJudge of a High Court who has been removed from office  upon action taken by the\nJudicial Council or upon punishment by a court for a criminal offence involving moral\nturpitude shall not be entitled to gratuity or pension.\nProvided that this provision shall not apply in cases where the Judicial Council\nhas removed him or her from office on the ground of inability to perform the duties of\nhis or her office because of physical or mental illness.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The remuneration and other conditions of service of the Chief Judge or a\nJudge of the High Court shall not be altered to his or her disadvantage.\nProvided that this p rovision shall not apply in case s where a state of\nemergency is declared because of extreme economic disarrays.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 142", "title": "V acation of office of Chief Judge or Judge", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The office of Chief Judge or Judge of a\nHigh Court shall fall vacant in any of the following circumstances: -\n(a) In case he or she tenders resignation in writing to the Chief Justice;\n(b) In case he or she attains the age of sixty-three years;\n(c) In case he or she is relieved of  office by the Chief Justice on\nrecommendation of the Judicial Council, on the ground of his or her\nincompetence, misconduct, failure to perform his or her duties\nhonestly, performance of business with mala fide intention or serious\nviolation by him or her of the code of conduct required to be observed\nby him or her;\n(d) In case he or she is removed from office by the Chief Justice on\nrecommendation of the Judicial Council on the ground that he or she\nis unable to discharge his or her duties becaus e of physical or mental\nillness;\n(e) In case he or she is convicted and punished by a court for a criminal\noffence involving moral turpitude;\n(f) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Judge who is facing a charge shall be provided with a reasonable\nopportunity to defend himself or herself prior to removing him or her from the office\npursuant to  sub-clause ( c) of clause (1). The Judge against whom the proceedings\nhave been so instituted shall not be allowed to perform the duties of his or her office\nuntil the proceedings are completed.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Nothing shall bar the institution of action in accordance with the federal\nlaw against the Chief Judge or Judge who has been removed from office for an\noffence which he or she has committed while in office.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 143", "title": "Chief Judge and Judges not to be engaged in any Other Office and Provisions relating to Transfer", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No Chief Judge or Judge of a High  Court shall be engaged in or\ndeputed to any office other than that of Judge.\nProvided that the Government of Nepal may, in consultation with the Judicial\nCouncil, depute a Judge of the High Court to work concerning judicial inquiry, or to\nlegal or judicia l investigation or research or to any work of national interest for any\nspecific period.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Chief Justice may, on recommendation of the Judicial Council,\ntransfer a Judge of a High Court to another High Court.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 144", "title": "Jurisdiction of High Court", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The High Court shall  have the power to issue\nnecessary and appropriate orders , for the enforcement of the fundamental rights\nconferred by this Constitution or for the enforcement of any other legal right for\nwhich no other remedy has been provided or for whic h the remedy even though\nprovided appears to be inadequate or ineffective or for the settlement of any legal\nquestion involved in any dispute of public interest or concern.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "For the purposes of clause (1), the High Court may issue appropriate orders\nand writs including the writs of habeas corpus, mandamus, certiorari, prohibition and\nquo warranto.\nProvided that except on the ground of absence of jurisdiction, the High Court\nshall not under this clause interfere with  any internal proceedings of the Federal\nParliament or Provincial Assembly, and with any proceedings instituted by the Federal\nParliament or Provincial Assembly concerning violation of its privileges and penalties\nimposed therefor.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The High Court shall, in accordance with the federal law, have the power\nto originally hear and settle cases, hear appeals and  test judgments referred fo r\nconfirmation.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Other powers and procedures of the High Court shall be as provided for in\nthe federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 145", "title": "Power to Transfer Cases", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "In case a High Court is of the opinion that a case which\nis sub judice in a subordinate court within its jurisdiction involves a question relating\nto a provincial law and it is essential to settle that question in order to decide the case,\nthe High Court may procure the case and dispose the case wholly or decide only such\nquestion and remand the case to the court of first instance.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In case it is satisfied with the reason that there exists a situatio n where\njudicial impartiality may be questioned if a case filed in a District Court is heard by\nthat Court, the High Court may, stating the reasons and grounds thereof, order such\ncase to be transferred from such  District Court to another District Court under its\njurisdiction and heard by the latter District Court, as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 146", "title": "Allowed to be engaged in Practice of Law", "content": "A person who has retired from the office\nof a Judge of a High Court may be engaged in the practice of law before the Supreme\nCourt and a High Court, other than the High Court and subordinate courts where he or\nshe has served as a Judge.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 147", "title": "Responsibility of Chief Judge", "content": "The Chief Judge shall have the ultimate  responsibility\nto make effective the administration of justice by the High Court and the Courts or\nother judicial institutions which are subordinate to it . For that purpose, the Chief\nJudge may, subject to this Constitution and the federal law, give necessary direction to\nthe subordinate Courts and judicial institutions", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 148", "title": "District Court", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a District Court in each District.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Local Level  judicial institutions established in accordance with the\nprovincial law  shall be subordinate to the District Court. The District Court may\ninspect as well as supervise and give necessary direction to its subordinate judicial\ninstitutions.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 149", "title": "Appointment, Qualification, Remuneration and Other Conditions of Service of Judges of District Courts", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Chief Justice shall, on recommendation of the Judicial\nCouncil, appoint Judges of the District Courts.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The vacant posts of Judges of the  District Court shall be fulfilled as\nfollows:-\n(a) Twenty percent of the total vacant posts, on the basis of evaluation of\nseniority, qualification and competency, from amongst the officers\nwho have obtained bachelor's degree in law and served for at least\nthree years in the post of Gazetted Second Class of the Judicial\nService;\n(b) Forty percent of the total vacant posts , on the basis of open\ncompetitive examination, from amongst the officers who have\nobtained bachelor's degree in law and served for at least three years in\nthe post of Gazetted Second Class of the Judicial Service;\n(c) The remaining forty percent of the total vacant posts, on the basis of\nopen competitive examination, from amongst the citizens of Nepal\nwho, having obtained bachelor's degree in law, have constantly\npractised law for at least eight years as an advocate or who,  having\nobtained bachelor's degree in law, have served  in a Gazetted post of\nthe Judicial Service for at least eight years or have constantly been\nengaged in the teaching or research of law or served in any other field\nof law or justice for at least eight years.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Judicial Service Commission shall, in accordance with the federal law,\nhold written and oral competitive examinations for the persons who have possessed\nthe qualification s referred to in  sub-clauses (b) and (c) of clause (2), and make\nrecommendation, in order of merit, to  the Judicial Council for appointment as District\nJudges.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The remuneration and other conditions of service of the Judges of the\nDistrict Court shall be as provided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The remuneration and other conditions of service of a Judge of the District\nCourt shall not be altered to his or her disadvantage.\nProvided that this provision shall not apply in case s where a state of\nemergency is declared because of extreme economic disarrays.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The office of a Judge of the District Court shall fall vacant in any of the\nfollowing circumstances:-\n(a) In case he or she tenders resignation in writing to the Chief Justice;\n(b) In case he or she attains the age of sixty-three years;\n(c) In case he or she is removed from office by the Chief Justice on\nrecommendation of the Judicial Council, on the ground of his or her\nincompetence, misconduct, failure to perform his or her duties\nhonestly, performance of business with malafide intention or se rious\nviolation by him or her of the code of conduct required to be observed\nby him or her;\n(d) In case  he or she is removed from  office by the Chief Justice on\nrecommendation of the Judicial Council on the ground that he or she\nis unable to continue service and discharge his or her duties becaus e\nof physical or mental illness;\n(e) In case he or she is convicted and punished by a court for a criminal\noffence involving moral turpitude;\n(f) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "A District Judge who is accused shall be given a reasonable opportunity to\ndefend himself or herself  before removing him or her from office pursuant to  sub-\nclause (c) of clause (6).  The District Judge against whom the proceedings are so\ninitiated shall not perform the dut ies of his or her office until the proceedings are\ncompleted.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "Nothing shall prevent the instituting of an action, in accordance with the\nfederal law, against a District Judge who is removed from office for the offence which\nhe or she has committed while in office.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 150", "title": "District Judges not to be engaged in any Other Office and Provisions r elating to Transfer", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No District Judge shall be engaged in or deputed to any office other than\nthat of Judge.\nProvided that the Government of Nepal may, in consultation with the Judicial\nCouncil, depute a District Judge to work concerning judicial inquiry, or to legal or\njudicial investigation or research and to any election related work  for a specified\nperiod.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Chief Justice may, on recommendation of the Judicial Council,\ntransfer a District Judge from one District Court to another District Court.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 151", "title": "Jurisdiction of District Court", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Except as otherwise provided for in the federal law,\na District Court shall have the power to initially hear and settle all cases under its\njurisdiction, to hear petitions under law, including petitions of habeas corpus  and\ninjunction, hear appeals under law from decisions made by quasi -judicial institutions,\nhear appeals from decisions made by Local Level judicial institutions formed under\nthe provincial law, institute contempt proceedings  and punish for contempt under the\nfederal law  in case  anyone makes obstruction in the dispensation of justice by , or\ndisregards any order or judgment by, it or any of its subordinate courts.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Other provisions relating to the jurisdiction and procedures of the District\nCourts shall be as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 152", "title": "Specialized Courts", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Other specialized courts, judicial institutions or tribunals may\nbe constituted to initiate and settle specific types and nature of cases other than those\nreferred to in Article 127, as provided for in the federal law.\nProvided that no specialized court, judicial institutions or tribunal  shall be\nconstituted for any specific case.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No criminal offence involving imprisonment for a term of more than one\nyear shall fall under the jurisdiction of a n institution other than a court, specialized\ncourt, military court or judicial institution.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 153", "title": "Judicial Council", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a Judicial Council to make recommendation or\ngive advice, in accordance with this Constitution, on the appointment of, transfer of,\ndisciplinary action against, and dismissal of, Judges, and other matters relating to the\nadministration of justice, which shall consist of the following as its chairperson and\nmembers:\n(a) The Chief Justice - Chairperson\n(b) The Federal Minister for Law and Justice - Member\n(c) The senior-most Justice of Supreme Court  - Member\n(d) One jurist appointed by the President on\nrecommendation of the Prime Minister\n- Member\n(e) A senior advocate or advocate who has gained at least\ntwenty years of experience, appointed by the President\non recommendation of the Nepal Bar Association\n- Member", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The term of office of the members referred to in sub-clauses (d) and (e) of\nclause (1) shall be four years, and their remuneration and facilities shall be equivalent\nto those of a Justice of the Supreme Court.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The members referred to in  sub-clauses (d) and (e) of clause (1) shall be\nremoved from office in the same manner and on the same grounds as a Justice of the\nSupreme Court.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The chairperson and a member of the Judicial Council may study the case\nassociated with a complaint filed in respect of any Judge, and make a report thereof to\nthe Judicial Council.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In case a preliminary inquiry of a complaint filed in respect of any Judge\nreveals a need to have a detailed inquiry by an expert, the Judicial Council may form\nan inquiry committee.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "In case a Judge, other than a  Judge who may be removed from the office\nby way of impeachment in accordance with this Constitution, commits an abuse of\nauthority by way of corruption, the Judicial Council may investigate into the matter\nand institute a case in accordance with law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The Judicial Council shall be required to prepare updated records of the\npersons who are qualified for appointment to offices of the Chief Justice , Justices of\nthe Supreme Court, Chief Judges and Judges of the High Courts.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "Other functions, duties and p owers of the Judicial Council shall  be as\nprovided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 154", "title": "Judicial Service Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Government of Nepal shall , in appointing,\ntransferring or promoting gazetted officers of the Federal Judicial Service or taking\ndepartmental action concerning such officers in accordance with law, act on\nrecommendation of the Judicial Service Commission.\nProvided that the Government of Nepal shall consult the  Public Service\nCommission for new permanent appointments to gazetted posts of the Federal Judicial\nService from persons who are not already in the Federal Government Service or  for\npromotions from non -gazetted posts of the Federal Judicial Service to gazetted ones\nof that Service.\nExplanation: For the purposes of this Article, the Public Service Commission\nshall hold open and internal competitive examinations to be held for appointment s to\nGazetted posts of the Federal Judicial Service.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Judicial Service Commission shall consist of the following as its\nchairperson and members:-\n(a) The Chief Justice - Chairperson\n(b) The Federal Minister for Law and Justice - Member\n(c) The senior most Justice of Supreme Court - Member\n(d) The Chairperson of the Public Service\nCommission\n- Member\n(e) The Attorney General - Member", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Other functions, duties, powers and procedures of the Judicial Service\nCommission shall be as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 155", "title": "Provisions relating to Conditions of Service and Facilities", "content": "Provisions relating to the\nremuneration, facilities and conditi ons of s ervice of the employees of the Federal\nJudicial Service shall be as provided for in a Federal Act.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 156", "title": "Provisions relating to Provincial Judicial Service Commission", "content": "Provisions relating to\nthe formation of a Provincial Judicial Service Commission and the remuneration,\nfacilities and conditions of service of the employees of a Provincial Judicial Service\nshall be as provided for in the federal law.", "children": []}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-12", "title": "Attorney General", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 157", "title": "Attorney General", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be an Attorney General of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall, on recommendation of the Prime Minister, appoint the\nAttorney General.  The Attorney General shall hold his or her office during the\npleasure of the Prime Minister.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A person who i s eligible   to be ap pointed as a Justice of the Supreme\nCourt shall be eligible to be appointed as the Attorney General.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The office of the Attorney General shall fall vacant in any of the following\ncircumstances:\n(a) In case he or she tenders resignation in writing to the President\nthrough the Prime Minister;\n(b) In case he or she is relieved of the office by the President on\nrecommendation of the Prime Minister;\n(c) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The remuneration and other facilities of the Attorney General shall be\nsimilar to those of a Justice of Supreme Court . Other conditions of service of the\nAttorney General shall be in accordance with law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 158", "title": "Functions, Duties and Powers of Attorney General", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Attorney General shall be\nthe chief legal advisor to the Government of Nepal. It shall be the duty of the\nAttorney General to give opinions and advices on constitutional and legal matters to\nthe Government of Nepal and such other authorities as  the Government of Nepal may\nspecify.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Attorney General or government attorneys subordinate to him or her\nshall represent the Government of Nepal in lawsuits wherein the rights, interests or\nconcerns of the Government of Nepal are involved. Except as provided otherwise in\nthis Constitution, the Attorney General shall have the right to make a final decision as\nto whether or not to institute any case on behalf of the Government of Nepal in any\ncourt, judicial institution or authority.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Opinion of the Attorney General shall be required for withdrawing a case\nfiled on behalf of the Government of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The Attorney General may, upon in vitation by the Federal  Parliament or\nany of its committees, appear and express his or her opinion on any legal question in\nsuch meeting.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In the course of discharging the duties of his or her office, the Attorney\nGeneral shall have the right to appear in any Court, office and authority of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The Attorney General shall, in the course of performi ng his or her duties,\nin addition to that set forth in clause (2)  have the power to carry out the following\nacts:-\n(a) To defend, on behalf of the Government of Nepal, any lawsuit in\nwhich the Government of Nepal is a plaintiff or a defendant;\n(b) To monitor, or cause to be monitored, whether any interpretation\ngiven to a law or any legal principle laid down by the Supreme Court\nin the course of hearing of lawsuits has been implemented;\n(c) In case a complaint is made alleging that any person held in c ustody\nhas not been treated humanely subject to this Constitution or such\nperson has not been allowed to meet his or her relative or through his\nor her legal practitioner or in case  information of such  matter is\nreceived, to inquire there  into and give nec essary directive to the\nconcerned authority to prevent such act.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The Attorney General may so delegate his or her functions, duties and\npowers referred to in this Article to his or her subordinate government attorneys as to\nbe exercised and complied with subject to the specified conditions.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "In addition to the functions, duties and powers referred to in this Article,\nother functions, duties and powers of th e Attorney General shall be in accordance\nwith this Constitution and the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 159", "title": "Annual Report", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Attorney General shall, every year, submit to the President an\nannual report on the works which he or she has performed in accordance with thi s\nConstitution and the federal law , and the President shall cause such report to be laid\nbefore the Federal Parliament through the Prime Minister.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The annual report to be submitted pursuant to clause (1) shall set out, inter\nalia, the number of advices and opinions on constitutional and legal matters rendered\nby him or her throughout the year, along with short description of such advices and\nopinions, details of cases instituted as State cases, details of defence made in lawsuits\nin which the Government of Nepal is a plaintiff or defendant, details of reforms to be\nmade in the future in relation to cases to be instituted as State cases and information\nrelating to crime trends.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 160", "title": "Chief Attorney", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a Chief Attorne y in every Province, who shall be\nsubordinate to the Attorney General.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Chief of Province  shall, on recommendation of the concerned Chief\nMinister, appoint the Chief Attorney . The Chief Attorney shall hold office during the\npleasure of the Chief Minister.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A person who is qualified to be appointed as a Judge of High Court shall\nbe eligible to be appointed as the Chief Attorney.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The office of the Chief Attorney shall fall vacant in any of the following\ncircumstances: -\n(a) In case he or she tenders resignation in writing to the Chief of\nProvince through the Chief Minister;\n(b) In case he or she is removed from office by the Chief of Province on\nrecommendation of the Chief Minister;\n(c) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The Chief Attorney shall be the chief legal advisor to the Provincial\nGovernment. It shall be the duty of the Chief Attorney to give opinions and advices\non constitutional and legal matters to the Provincial Government and such other\nauthorities as the Provincial Government may specify.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The Office of Attorney General shall manage the employees under the\nOffice of Chief Attorney.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The remuneration and other facilities of the Chief Attorney shall be similar\nto those of a Judge of High Court. The fun ctions, duties and powers and o ther\nconditions of service of the Chief Attorney shall be as provided for in the provincial\nlaw.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 161", "title": "Provisions relating to Conditions of Service and Facilities", "content": "Provisions relating to the\nremuneration, facilities and conditions of service of the government attorneys and\nother employees under the Attorney General shall be as provided for in a Federal Act.", "children": []}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-13", "title": "Provincial Executive", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 162", "title": "Executive P ower of Province", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The executive power of a Province shall, in\naccordance with  this Constitution and provincial law , be vested in the Provincial\nCouncil of Ministers.\nProvided that in case  a Provincial Executive does not exist because of\nenforcement of Federal rule, the Chief of Province shall exercise the executive power\nof the Province as directed by the Government of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The responsibility for issuing general directives, controlling and regulating\nthe governance of the Province shall, subject to this Constitution and other laws, lie in\nthe Provincial Council of Ministers.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "All Provincial Executive functions shall be performed in the name of the\nProvincial Government.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The executive power of the Province shall be as referred to in Schedule-6,\nSchedule-7 and Schedule-9 subject to this Constitution.\nProvided that the Provincial Council of Ministers shall exercise the executive\npowers in coordination with the Government of Nepal, except as explicitly provided\nfor in this Constitution and in the federal law in relation to concurrent powers of the\nFederation and the Province.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Any decision or order to be issued in the name of the Provincial\nGovernment pursuant to clause (3) and other instruments of authorization pertaining\nthereto shall be authenticated as provided for in the provincial law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 163", "title": "Provisions r elating to Chief of Province", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a Chief of Province  in\neach Province as a representative of the Government of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall appoint one Chief of Province for each Province.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of office of a Chief of Province shall be five years except where\nthe President removes him or her from the office prior to the expiration of his or her\nterm of office.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The same person may not be the Chief of Province for more than once in\nthe same Province.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 164", "title": "Qualification for Chief of Province", "content": "A person who has the following qualification\nshall be eligible to become the Chief of Province:-\n(a) One who is eligible to become a member of the Federal Parliament;\n(b) One who has completed the age of thirty-five years; and\n(c) One who is not disqualified by any law.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 165", "title": "V acation of Office of Chief of Province", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The office of the Chief of Province shall\nfall vacant in any of the following circumstances:-\n(a) In case he or she tenders resignation in writing to the President;\n(b) In case his or her term of office expires or he or she is removed from\noffice by the President prior to expiration of the term;\n(c) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In case the office of the Chief of Province of any Province falls vacant, the\nPresident may so designate the Chief of Province  of another Province to act as such\nalso for such Province.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 166", "title": "Functions, Duties and Powers of Chief of Province", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Chief of Province  shall\nexercise such powers and perform such duties as conferred to him or her in\naccordance with this Constitution or law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In exercising the powers o r fulfilling the duties pursuant to clause (1), the\nChief of Province shall perform all other functions to be performed by him or her on\nrecommendation and with the consent of the Provincial Council of Ministers than\nthose functions specifically provided to be performed on recommendation  of any\ninstitution or official in accordance with  this Constitution or  law. Such\nrecommendation and consent shall be submitted through the Chief Minister.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Any decision or order to be issued in the name of the Chief of Province\npursuant to clause (2) and other instrument of authorization pertaining thereto shall be\nauthenticated as provided for in the provincial law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 167", "title": "Oath by Chief of Province", "content": "The Chief of Province shall, prior to assuming office, take\nan oath of office and secrecy before the President as provided for in the federal law.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 168", "title": "Constitution of Provincial Council of Ministers", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Chief of Province  shall\nappoint the leader of the parliamentary party commanding a majority in the Provincial\nAssembly as the Chief Minister and the Provincial   Council of Ministers shall be\nconstituted under his or her chairpersonship.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In cases where no party has a clear majority in the Provincial Assembly\npursuant to  clause (1), the Chief of Province  shall appoint as the Chief Minister a\nmember of the Provincial Assembly who is able to command majority with the\nsupport of two or more parties representing to the Provincial Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In cases where the Chief Minister cannot be appointed pursuant to clause", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "within thirty days after the date of declaration of the final results of election to the\nProvincial Assembly the Chief Minister so appointed fails to secure a vote of\nconfidence pursuant to clause (4), the Chief of Province  shall appoint as the Chief\nMinister the parliamentary party leader of the party which has the highest number of\nmembers in the Provincial Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The Chief Minister appointed pursuant to clause (2) or (3) shall secure a\nvote of confidence from the Provincial Assembly within thirty days after the date of\nsuch appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In cases where the Chief  Minister appointed pursuant to clause (3) fails to\nsecure a vote of confidence under clause (4) and any member referred to in clause (2)\npresents a ground on which he or she is able to secure a vote of confidence in the\nProvincial Assembly, the Chief of Province  shall appoint such member as the Chief\nMinister.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The Chief Minister appointed pursuant to clause (5) shall secure a vote of\nconfidence pursuant to clause (4).", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "In cases where the Chief Minister appointed pursuant to clause (5) fails to\nsecure a vote of confidence or the Chief Minister cannot be appointed, the Chief of\nProvince shall, on recommendation of the Chief Minister, dissolve the Provincial\nAssembly and appoint a date of election so that the election to another Provincial\nAssembly is completed within six months.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "Procedures on the appointment of the Chief Minister pursuant to  this\nArticle shall be required to be completed within thirty-five days after the date of\ndeclaration of the final results of election to the Provincial Assembly held in\naccordance with this Constitution or the date on which the office of the Chief Minister\nhas fallen vacant.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "The Chief of Province  shall, on recommend ation of the Chief Minister,\nconstitute the Provincial Council of Ministers consisting of a maximum of twenty\npercent of the total number of members of the Provincial Assembly, including the\nChief Minister, in accordance with the inclusive principle, from amongst the members\nof the Provincial Assembly.\nExplanation: For the purposes of this Article, \"Minister\" means a Minister,\nMinister of State and Assistant Minister.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": "The Chief Minister and Ministers shall be collectively responsible to\nProvincial Assembly, and the Ministers shall be individually responsible for the\nbusiness of their respective Ministries to the Chief Minister and the Provincial\nAssembly.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 169", "title": "Vacation of Office of Chief Minister and Minister", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The office of the Chief\nMinister shall fall vacant in any of the following circumstances: -\n(a) In case he or she tenders resignation in writing to the Chief of\nProvince;\n(b) In case a vote of no confidence is adopted against him or her or a vote\nof confidence is not adopted pursuant to Article 188;\n(c) In case he or she ceases to be a member of the Provincial Assembly;\n(d) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The office of a Minister shall fall vacant  in any of the following\ncircumstances: -\n(a) In case he or she tenders resignation in writing to the Chief Minister;\n(b) In case the Chief Minister removes him or her from the office;\n(c) In case the office of the Chief Minister falls vacant pursuant to sub-\nclause (a), (b) or (c) of clause (1);\n(d) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Even though the office of the Chief Minister falls vacant pursuant to clause", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": ", the same Council of Ministers shall continue to act until another Provincial\nCouncil of Ministers is constituted.\nProvided that in case the Chief Minister dies, the senior -most Minister shall\nact as the Chief Minister until a new Chief Minister is appointed.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 170", "title": "Non-Member of Provincial Assembly may B ecome Minister", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Notwithstanding\nanything contained in clause (9) of Article 168 , the Chief of Province may, on the\nrecommendation of the Chief Minister, appoint any person who is not a member of\nthe Provincial Assembly as a Minister.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Minister appointed pursuant to clause (1) shall be required to become a\nmember of the Provincial Assembly within six months from the date of taking an oath\nby him or her.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In the event of failure to become a member of the Provincial Assembly\nwithin the period referred to in clause (2), he or she shall not be eligible to be\nreappointed to the office of Minister during the term of the then Provincial Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Notwithstanding anything contained in clause (1), a person who has lost\nthe election to the then Provincial Assembly shall not be eligible to be appointed to\nthe office of Minister pursuant to clause (1) during the term of such Provincial\nAssembly.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 171", "title": "Remuneration and o ther Facilities of Chief Minister and Minister", "content": "The remuneration\nand other facilities of the Chief Minister and Ministers shall be as provided for in a\nprovincial Act , and until such Act is made, shall be as specified by the Provincial\nGovernment.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 172", "title": "Oath", "content": "The Chief Minister a nd Ministers shall , before assuming their respective\noffices, take an oath of office and secrecy before the Chief of Province, and Ministers\nof State and Assistant Ministers, before the Chief Minister, as provided for in the\nprovincial law.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 173", "title": "To Give Information to Chief of Province", "content": "The Chief Minister shall inform the Chief\nof Province about the following matters:-\n(a) Resolutions of the Provincial Council of Ministers;\n(b) Bills to be introduced in the Provincial Assembly;\n(c) Such other necessary information as commanded by the Chief of\nProvince on matters set forth in clauses (a) and (b); and\n(d) Current general state of affairs of the Province.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 174", "title": "Transaction of Business of Provincial Government", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The allocation and transaction\nof business of the Provincial Government shall be carried out in accordance with the\nrules approved by the Provincial Government.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No question shall be raised in any court as to whether or not the rules\nreferred to in clause (1) have been observed.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-14", "title": "Provincial Legislature", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 175", "title": "Provincial Legislature", "content": "The legislature of a Province shall be unicameral  which shall\nbe called as the Provincial Assembly.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 176", "title": "Composition of Provincial Assembly", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Each Provincial Assembly shall consist of a\nnumber of members as follows:-\n(a) Members in a number that is twice as many as the number of\nmembers elected to the House of Representatives from the concer ned\nProvince, through the first past the post electoral system;\n(b) The number of members to be set pursuant to  clause (a) shall be\nconsidered to be sixty percent, and the rest forty percent members to\nbe elected, through the proportional electoral system.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Election constituencies shall  be set on the ba sis of geography and\npopulation as provided for in  the federal law for the election to members pursuant to\nsub-clause (a) of clause (1).", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Sixty percent members of the Provincial Assembly shall be electe d in\naccordance with the first past the post electoral system and the forty percent members\nin accordance with the proportional electoral system.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Election to the members of the Provincial Assembly pursuant to clause (3)\nshall be held through adult suffrage by secret ballots in accordance with law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Each citizen of Nepal  who resides within the territory of the Province and\nwho has completed the age of eighteen years shall have a right to vote in any one\nelection constituency in accordance with law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "A federal law shall provide that in filing candidacy by political parties for\nthe election to the Provincial Assembly under the proportional electoral system,\nrepresentation shall be ensured on the basis of a c losed list also from women, Dalit,\nindigenous nationalities (Aadibasi Janajati ), Khas Arya , Madhesi, Tharu, Muslims\nand backward regions, minority communities, on the basis of popul ation. In so  filing\ncandidacy, regar d shall also be had to geographical  balance of the concerned\nProvince.\nExplanation: For the purposes of this clause, \" Khas Arya \" means Kshetri,\nBrahmin, Thakuri, Sanyasi (Dashnami) community.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "In filing candidacy pursuant to clause (6), political parties shall provide for\nrepresentation of the persons with disabilities as well.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "In case the seat of a member of the Provincial Assembly falls vacant while\nits term still remains for more than six months, the vacancy shall be fulfilled through\nthe same electoral system as through which such seat was fulfilled.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "Notwithstanding anything contained elsewhere in this Article, at least one\nthird of the total number of members elected from each political party representing in\nthe Provincial Assembly shall be women. In case  women are not so elected as to\nconstitute one third of the elected members of any political party pursuant to  sub-\nclause (a) of clause (1), such  political party shall, in electing members pursuant to\nsub-clause (b) of that clause , so elect  that women members constitute at least one\nthird of the total number of members electe d to the Provincial Assembly from that\nparty.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": "A person who is qualified pursuant to Article 178 and entitled to vote in\nan election to the members of the Provincial Assembly may, su bject to law, be a\ncandidate in any election constituency of the Province.\nProvided that a person shall not be a candidate in more than one election\nconstituencies at the same time.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(11)", "title": null, "content": "Other provisions relating to election to the Provincial Assembly shall be\nas provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 177", "title": "Term of Provincial Assembly", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Unless dissolved earlier in accordance with this\nConstitution, the term of the Provincial Assembly shall be five years.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Notwithstanding anything contained in clause (1), the term of the\nProvincial Assembly may be extended by a provincial Act for a period not exceeding\none year in cases where a proclamation or order of a state of emergency is in effect.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of the Provincial Assembly extended pursuant to clause (2) shall,\nipso facto, be terminated after the expiry of six months from the date of  revocation of\nthe proclamation or order of the state of emergency in the concerned Province.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 178", "title": "Qualification for a Member of Provincial Assembly", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A person who has the\nfollowing qualification s shall be eligible to become a member of the Provincial\nAssembly:-\n(a) One who is a citizen of Nepal;\n(b) One who is a voter of the concerned Province;\n(c) One who has completed the age of twenty-five years;\n(d) One who is not convicted of a cr iminal offense involving moral\nturpitude;\n(e) One who is not disqualified by any law; and\n(f) One who is not holding any office of profit.\nExplanation: For the purposes  of this clause, \"office of profit\" mean s any\nposition, other than a political position which is to be fulfilled by election or\nnomination, for which a remuneration or financial benefit is paid out of a government\nfund.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In case  a person who holds a political office to be fulfilled by way of\nelection, nomination or appointment is elected as a member of the Provincial\nAssembly under this Part, such office shall, ipso facto, fall vacant with effect from the\nday on which he or she takes an oath of such office.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 179", "title": "Oath of Member of Provincial Assembly", "content": "Every member of the Provincial Assembly\nshall be required, before taking part for the first time in the meeting of the Assembly\nor any of its committees, to take an oath as provided for in the provincial law.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 180", "title": "V acation of Seat of a Member of Provincial Assembly", "content": "The seat of a member of the\nProvincial Assembly shall fall vacant in any of the following circumstances:-\n(a) In case he or she tenders resignation in writing to the Speaker of\nProvince;\n(b) In case he or she is no longer qualified or ceases to possess th e\nqualifications referred to in Article 178;\n(c) In case the term of the Provincial Assembly expires or it is dissolved;\n(d) In case he or she is absent in ten consecutive meetings  without giving\ninformation to the Provincial Assembly;\n(e) In case the political party of which he or she was a member when elected\nprovides a notification as provided  for in the federal law that he or she\nhas defected from the party;\n(f) In case he or she dies.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 181", "title": "Decision as to Disqualification of Member", "content": "In case question arises as to whether any\nmember of the Provincial Assembly is disqualified or has ceased to possess any of the\nqualifications referred to in  Article 178 , the Constitutional Bench of the Supreme\nCourt shall make the final decision of such question.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 182", "title": "Speaker and Deputy Speaker of Provincial Assembly", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The members of the\nProvincial Assembly  shall, within fifteen days of the date of holding of the first\nmeeting of the Provincial Assembly, elect a Speaker of Province  and a Deputy\nSpeaker of Province from amongst themselves.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Election pursuant to clause (1) shall be so held that there is one woman out\nof the Speaker of Province  and the Deputy Speaker of Province , and the Speaker of\nProvince and the Deputy Speaker of Province  shall be representatives from different\nparties.\nProvided that in case there is no representation of more than one party in the\nProvincial Assembly or no candidacy is filed by more than one party despite\nrepresentation, nothing shall prevent the members of the same party from being the\nSpeaker of Province and the Deputy Speaker of Province.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case  the office of the Speaker of Province  or the Deputy Speaker of\nProvince falls vacant, the members of the Provincial Assembly shall fulfil the vacancy\nthrough election to the Speaker of Province or the Deputy Speaker of Province  from\namongst themselves.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The Deputy Speaker of Province  shall, in the absence of the Speaker of\nProvince, preside over the Provincial Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In case the election to the Speaker of Province and the Deputy Speaker of\nProvince has not taken place, or in case  both the positions have fallen vacant , the\nattending member who is by age the senior -most shall preside over the meeting of the\nProvincial Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The office of the Speaker of Province  or the Deputy Speaker of Province\nshall fall vacant in any of the following circumstances:-\n(a) In case he or she ceases to be a member of the Provincial Assembly;\nProvided that, in the event of the dissolution of the Provincial\nAssembly, the Speaker of Province  and the Deputy Speaker holding\ntheir respective offices shall continue in office until the previous day\nof the filing of nominations for another election to the Provincial\nAssembly;\n(b) In case he or she tenders resignation in writing;\n(c) In case a resolution is adopted by a majority of two -thirds of the total\nnumber of the then members of the Provincial Assembly to the effect\nthat his or her conduct is not compatible with his or her office.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The Deputy Speaker  of Province shall preside over a meeting at which\ndeliberations are to be held on a motion that the conduct of the Speaker of Province is\nnot compatible with his or her office. The Speaker of Province shall be entitled to take\npart and vote in the deliberations on such motion.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 183", "title": "Summoning and Prorogation of Session of Provincial Assembly", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Chief of\nProvince shall summon a session of the Provincial Assembly within twenty days of\nthe declaration of final results of the election to the Provincial Assembly. Thereafter,\nthe Chief of Province shall, from time to time, summon other sessions in accordance\nwith this Constitution.\nProvided that the interval between the two consecutive sessions shall not\nexceed six months.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Chief of Province  may prorogue the sessions of the Provincial\nAssembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case, during the prorogation or recess of the session of the Provincial\nAssembly, one-fourth of the total number of its members make a requisition in writing\nthat it is expedient  to convene a session or meeting, the Chief of Province  shall\nspecify the date and time for such  session or meeting. The Provincial Assembly shall\nmeet or commence its session at the date and time so specified.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 184", "title": "Address by Chief of Province", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Chief of Province may address a sitting of the\nProvincial Assembly and summon the members for that purpose.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Chief of Province shall address the first session after an election to the\nProvincial Assembly and a sitting of the Provincial Assembly after the\ncommencement of the first session of each year.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 185", "title": "Quorum of Provincial Assembly", "content": "Except as otherwise provided for in this\nConstitution, no question or motion shall be submitted for a decision in the Provincial\nAssembly unless one-fourth of the total number of its members are present.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 186", "title": "Voting in Provincial Assembly", "content": "All questions submitted for a decision in the\nProvincial Assembly shall be decided by a majority vote of the members present and\nparticipate in voting. T he member presiding over the meeting shall not have the right\nto vote.\nProvided that he or she may exercise his or her casting vote in the case of a tie.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 187", "title": "Privileges of Provincial Assembly", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Subject to this Constitution , there shall be full\nfreedom of speech in the Provincial Assembly and no member shall be arrested,\ndetained or prosecuted in any court for anything expressed or any vote cast by him or\nher in the Provincial Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Subject to this Constitution, the Provincial Assembly shall have full power\nto regulate and decide its internal business  and it shall be the exclusive right of the\nProvincial Assembly to decide whether or not any of its proceedings is regular or\nirregular. No question shall be raised in any court in this regard.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "No comment shall be made about the good faith concerning any\nproceeding of the Provincial Assembly, and no publication an d broadcasting of any\ntype shall be made about anything said by any member, intentionally distorting or\nmisinterpreting the meaning of the speech.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The provisions of clauses (1) and (3) shall also apply to other persons who\nare entitled to participate i n the meetings of the Provincial Assembly other than the\nmembers of the Provincial Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "No proceedings shall be initiated in any court against any person in respect\nof the publication, un der the authority granted by  the Provincial Assembly , of any\ndocument, report, vote or proceeding.\nExplanation: For the purposes of this clause and clauses (1), (2), (3) and (4),\n\"Provincial Assembly\" means and includes a meeting of a committee of the Provincial\nAssembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "No member of the Provincial Assembly may be arrested during the period\nfrom the issuance of a notice summoning the session to its prorogation.\nProvided that nothing in this clause shall be deemed to prevent the arrest under\nthe law of any member on a criminal charge. In case any member is so arrested, the\nauthority making such  arrest shall forthwith give information thereof to the person\npresiding over the Provincial Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "Any breach of the privileges shall be deemed to constitute  the contempt of\nthe Provincial Assembly, and the Provincial Assembly shall have the exclusive right\nto decide whether or not any breach of its privileges has taken place.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "In case any person is in contempt of the Provincial Assembly, the person\npresiding over the Provincial Assembly may, a fter a decision by the Provincial\nAssembly to that effect, admonish, warn or impose a sentence of imprisonment for a\nterm not exceeding three months or of a fine not exceeding ten thousand rupees on\nsuch person, and such fine shall be recovered as a government due.\nProvided that in case  such person apolog ies to the satisfaction of the\nProvincial Assembly, it may either pardon him or her or remit or commute the\nsentence imposed on him or her.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "Other matters relating to privileges of the Provincial Assembly shall be as\nprovided for in a provincial law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 188", "title": "Provisions relating to Vote of Confidence and Motion of No confidence", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The\nChief Minister may, whenever he or she considers necessary or appropriate to show\nthat he or she has confidence from the Provincial Assembly, table a resolution to that\neffect in the Provincial Assembly for the vote of confidence.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In case the political party which the Chief Minister represents is divided or\na political party  in coalition Provincial Government withdraws its support, the Chief\nMinister shall table a resolution in the Provincial Assembly for a vote of confidence\nwithin thirty days.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case a resolution tabled pursuant to clauses (1) and (2) is not adopted by\na majority of the total number of then members of the Provincial Assembly, the Chief\nMinister shall relieve of his or her office.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "One-fourth of the total number of then members of the Provincial\nAssembly may table in writing a motion of no confidence against the Chief Minister.\nProvided that a motion of no confidence may not be tabled until the first two\nyears after the appointment of the Chief Minister and until another one year after the\ndate of failure of the motion of no confidence once tabled.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "A motion of no confidence to be tabled pursuant to  clause (4) shall also\nmention the name of a member proposed for the Chief Minister.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "In case a motion of no confidence tabled pursuant to clause (4) is adopted\nby a majority of the total number of then members of the Provincial Assembly, the\nChief Minister shall be relieved of his or her office.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "In case the office of the Chief Minister falls vacant because of the adoption\nof a vote of no confidence pursuant to clause (6), the Chief of Province shall, pursuant\nto Article 168, appoint as the Chief Minister the member of the Provincial Assembly\nproposed pursuant to clause (5).", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 189", "title": "Minister, Minister of State and Assistant Minister entitled to Take part in Meetings of Provincial Assembly", "content": "The Minister, Minister of State and Assistant Minister shall be\nentitled to attend, and take part in the proceedings and deliberations of , the Provincial\nAssembly or its committees.\nProvided that a Minister, Minister of State or Assistant Minister  who is not a\nmember of the Provincial Assembly shall not be entitled to cast a vote in a meeting of\nthe Provincial Assembly or its committee, and a Minister, Minister of State or\nAssistant Minister shall not be entitled to vote in a meeting of a committee of which\nhe or she is not a member.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 190", "title": "Penalty for unauthorized Presence or Voting in Provincial Assembly", "content": "In case a person\nwho has not taken oath pursuant to  Article 179 or who is not a member of the\nProvincial Assembly is present or votes in a meeting of the Provincial Assembly or of\nits committee as a member, the person shall, by order of the person presiding over the\nmeeting, be fined with a sum of five thousand rupees for each instance of such\npresence or voting, and such fine shall be recovered as a government due.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 191", "title": "Restriction on Discussion", "content": "No discussion shall be held in the Provincial Assembly on\nany matters that may cause adverse effect on the dispensation of justice on any cases\nwhich are sub judice in any court of Nepal and on any judicial acts carried out by\nJudges in the course of performance of their duties.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 192", "title": "Transaction of Business i n Case of Vacancy in Seat of Member", "content": "The Provincial\nAssembly shall have the power to transact its business notwithstanding any va cancy\nin the seat of its member; and n o proceedings of the Provincial Assembly already\nconducted shall become invalid even in case it is subsequently discovered that a\nperson who was not so entitled took part in such proceedings.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 193", "title": "Power of Provincial Assembly to Constitute Committees", "content": "The Provincial Assembly\nmay, in accordance with its rules,  constitute committees or special committees, as\nrequired, in order to manage its working procedures.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 194", "title": "Procedures relating to Conduct of Business of Provincial Assembly", "content": "The Provincial\nAssembly shall frame rules to conduct its business, maintain order during its meetings\nand regulate the constitution, functions and procedures of , and other matters relating\nto, its committees. Until such rules are framed, the Provincial Assembly shall regulate\nits procedures on its own.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 195", "title": "Secretary and Secretariat of Provincial Assembly", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Chief of Province  shall\nappoint the Secretary of the Provincial Assembly on recommendation of the Speaker\nof Province.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "There shall be a Secretariat for conducting and managing the business of\nthe Provincial Assembly. The establishment of such Secretariat and other matters\nrelated thereto shall be as provided for in the provincial law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The qualification, functions, duties, powers and other conditions of service\nof the Secretary of the Provincial Assembly shall be as provided for in the   provincial\nlaw.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 196", "title": "Remuneration", "content": "The remuneration and facilities of the Speaker , Deputy Speaker and\nmembers of the Provincial Assembly shall be as provided  for in the provincial law,\nand until such law is made, as specified by the Provincial Government.", "children": []}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-15", "title": "Provincial Legislative Procedures", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 197", "title": "Legislative Powers of Provincial Assembly", "content": "The legislative powers of the Provincial\nAssembly shall be as enumerated in lists of Schedule-6, Schedule-7 and Schedule-9.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 198", "title": "Procedures for Introduction of Bills in Provincial Assembly", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A Bill may, subject\nto this Constitution, be introduced in the Provincial Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Money Bill and a Bill concerning law and order may be introduced only\nas a Government Bill.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "\"Money Bill\" means a Bill concerning any or all of the following subjects:-\n(a) Matters concerning imposition, collection, abolition, remission,\nalteration or regulation of taxes in the Province;\n(b) Matters concerning preservation of the Provincial Consolidated Fund\nor any other Provincial Government Fund, the deposit of moneys into\nand the appropriation or the withdrawal of moneys from such Funds,\nor the reduction, increment or cancellation of appropriations  of\nproposed expenditures from such Funds;\n(c) Regulation of matters relating to the borrowing of money or the\nguarantee to be given by the Provincial Government, or any matter\npertaining to the amendment of the law with respect to any financial\nobligations undertaken or to be undertaken by the Provincial\nGovernment,\n(d) Matters concerning custody of all revenues received by Provincial\nGovernment Fund, moneys acquired through the repayment of loans,\nand grant moneys, investments to be made or account or audits of the\naccounts of the Provincial Government, or\n(e) Other incidental matters directly related to any of the subjects\nspecified in clause (a), (b), (c) or (d).\nProvided that any Bill shall not be deemed to be a Money Bill only by the\nreason that it provides for the levying of any charges, fees or tariff such as license fee,\napplication fee, renewal fee or for the imposition of fines or penalty of imprisonment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "In case any question arises as to whether or not a Bill is a Money Bill, the\ndecision of the Speaker of Provincial Assembly shall be final.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 199", "title": "Procedures for Adoption of Bills", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A Bill adopted by the Provincial Assembly shall\nbe submitted to the Chief of Province for authentication.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In case a session of the Provincial Assembly is prorogued while a Bill is\nunder consideration, deliberations on the Bill may continue at the succeeding session.\nProvided that in case the Provincial Assembly is dissolved or its term expires\nwhen any Bill is under its consideration, such Bill shall lapse.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 200", "title": "Withdrawal of Bills", "content": "A Bill may be withdrawn by the member introducing it with the\napproval of the Provincial Assembly.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 201", "title": "Authentication on Bills", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Bill to be presented to the Chief of Province for\nauthentication pursuant to Article 199 shall be certified by the Speaker of Provincial\nAssembly and so presented.\nProvided that in the case of a Money Bill, the Speaker of Province  shall so\ncertify.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Bill presented to the Chief of Province  for the authentication shall be\nauthenticated within fifteen days, and the Provincial Assembly shall be informed\nthereof as soon as possible.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Except for a Money Bill, in case the Chief of Province  is of the opi nion\nthat any Bill needs further deliberations, he or she may send back the Bill along with\nhis or her message to the Provincial Assembly within fifteen  days from the date of\npresentation of the Bill to him or her.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "In case any Bill is sent back along with his or her message by the Chief of\nProvince pursuant to clause (3), it shall be reconsidered by the Provincial Assembly\nand in case the Bill so reconsidered is again adopted as it was or with amendments,\nand is again submitted to him or her, the Chief of Province shall authenticate that Bill\nwithin fifteen days of such submission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "A Bill shall become an Act after the Chief of Province authenticates it.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 202", "title": "Ordinance", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "In case , at any time, except when the Provincial Assembly is in\nsession, a circumstance exists which renders it necessary to take immediate action, the\nChief of Province  may, on the recommendation of the Provincial Council of\nMinisters, promulgate an Ordinance.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "An Ordinance promulgated pursuant to clause (1) shall have the same force\nand effect as an Act.\nProvided that every such Ordinance,-\n(a) Shall be tabled at the session of the Provincial Assembly held after\nthe promulgation, and in case  not adopted by the Provincial\nAssembly, it shall ipso facto cease to be effective;\n(b) May be repealed at any time by the Chief of Province; and\n(c) Shall, unless rendered ineffective or repealed pursuant to  sub-clause\n(a) or (b), ipso facto cease to be effective at the expiration of sixty\ndays after the day on which a meeting of the Provincial Assembly is\nheld.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-16", "title": "Province Financial Procedures", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 203", "title": "No Tax to be levied or Loan to be raised", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No tax shall be levied and collected in a\nProvince except in accordance with law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No loan shall be raised and guarantee be given by the Provincial\nGovernment except as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 204", "title": "Provincial Consolidated Fund", "content": "Except for the revenues of trusts ( Guthi), all revenues\nreceived by the Provincial Government, all loans raised on the security of revenues,\nall moneys received in repayment of any loans made under the authority of any\nprovincial Act and any amounts of grants or loans received from the Government of\nNepal shall, except as otherwise provided for in the provincial Act, be credited to a\nProvincial Government Fund to be known as the Provincial Consolidated Fund.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 205", "title": "Expenditures from Provincial Consolidated Fund or Provincial Government Fund", "content": "No\nexpenditure shall be incurred out of the Provincial Consolidated Fund or any other\nProvincial Government Fund except the following:-\n(a) Moneys charged on the Provincial Consolidated Fund;\n(b) Moneys required to meet the expenditure under an Appropriation Act;\n(c) Advance moneys authorized by a n Act required to meet expenditures,\nwhen an Appropriation Bill is under consideration; or\n(d) Expenditures to be incurred in extraordin ary circumstances under a\nV ote of Credit Act which contains only a description of expenditures.\nProvided that matters relating to the Provincial Contingency Fund shall\nbe pursuant to Article 212.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 206", "title": "Expenditures Chargeable on Province Consolidated Fund", "content": "The expenditures relating\nto the following matters shall be charged on the Provincial Consolidated Fund, and\napproval of the Provincial Assembly shall not be required for such expenditures:-\n(a) The amount required as remuneration and  facilities payable to the\nSpeaker of Province and the Deputy Speaker of Province;\n(b) The amount required as remuneration and  facilities payable to the\nChairperson and m embers of the Provincial Public Service\nCommission;\n(c) All charges relating to debts to  which the Provincial Government is\nliable;\n(d) Any sum required to satisfy any judgment or decree made by a court\nagainst the Provincial Government; and\n(e) Any other sum specified by the provincial law to be chargeable on the\nProvince Consolidated Fund.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 207", "title": "Estimates of Revenues and Expenditures", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Provincial Minister for Finance\nshall, in respect of every fiscal year, lay before the Provincial Assembly an annual\nestimate setting out, inter alia, the following matters:-\n(a) An estimate of revenues;\n(b) The moneys required to meet the charges on the Provincial\nConsolidated Fund; and\n(c) The moneys required to  meet the expenditure to be provided for by a\nProvincial Appropriation Act.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The annual estimate to be laid pursuant to clause (1) shall also be\naccompanied by a statement of the expenses allocated to every Ministry in the\nprevious fiscal year and particulars of whether or not the objectives of the expenses\nhave been achieved.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 208", "title": "Provincial Appropriation Act", "content": "The moneys required to meet the expenditure to be\nprovided for by the Provincial Appropriation Act shall be specified under appropriate\nheads in an Appropriation Bill.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 209", "title": "Supplementary Estimates", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Provincial Minister for Finance may lay before the\nProvincial Assembly a supplementary estimate in case it is found in any fiscal year,-\n(a) That the sum authorized to be spent for a particular service by the\nProvincial Appropriation Act for the current financial year is\ninsufficient, or that a need has arisen for expenditures upon some new\nservice not provided for in the Provincial Appropriation Act for that\nyear; or\n(b) That the expenditures made during that fiscal year are in excess of the\namount authorized by the Provincial Appropriation Act.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The sums included in the supplementary estimates shall be specified under\nthe heads in a Supplementary Appropriation Bill.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 210", "title": "V otes on Account", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Notwithstanding anything contained elsewhere in this Part, a\nportion of the expenditure estimated for the fiscal year may, w hen a  Provincial\nAppropriation Bill is under consideration, be incurred in advance in accordance with a\nProvince Act.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No V ote on Account Bill shall be introduced until the estimates of revenues\nand expenditures have been laid pursuant to Article 207, and the sums involved in the\nV ote on Account shall not exceed one -third of the estimate of expenditures for the\nfiscal year.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The expenditures incurred i n accordance with the Provincial V ote on\nAccount Act shall be included in the Provincial Appropriation Bill.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 211", "title": "V otes of Credit", "content": "Notwithstanding anything contained elsewhere in this Part, in case\nowing to an emergency due  to natural cause  or other reasons, it appears to be\nimpractical or inexpedient in view of the security or interest of the Province to specify\nthe details required pursuant to clause (1) of Article 207 , the Provincial Minister for\nFinance may lay before the Provincial Assembly a V ote of Credit Bill giving only a\nstatement of expenditures.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 212", "title": "Provincial Contingency Fund", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A provincial Act may create a Fund to be known as\nthe Provincial Contingency Fund into which shall be paid from time to time such\nmoneys as may be determined by a provincial Act.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Fund referred to in clause (1) shall be under the control of the\nProvincial Government. Any unforeseen expenditure may be met out of such Fund by\nthe Provincial Government.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The amount of the exp enditure referred to in  clause (2)  shall be\nreimbursed as soon as possible by a provincial Act.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 213", "title": "Act r elating to Financial Procedures", "content": "Matters relating to the transfer of moneys\nappropriated by a provincial Act  from one head to another and other financial\nprocedures shall be as provided for in the provincial Act.", "children": []}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-17", "title": "Local Executive", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 214", "title": "Executive Power of Local Level", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The executive power of the Local Level shall, in\naccordance with  this Constitution and the federal law , be vested in the Rural\nMunicipal Executive or the Municipal Executive.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The local executive power shall be as referred to  in Schedule -8 and\nSchedule-9.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The responsibility for issuing general directives, controlling an d regulating\nthe governance of the Rural Municipality and the Municipal ity shall, subject to this\nConstitution and other laws, lie in the Rural Municipal Executive and the Municipal\nExecutive.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The e xecutive functions of the Rural Municipality and the Municipality\nshall be performed in the name of the Rural Municipal Executive  and the Municipal\nExecutive.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Any decision or order to be issued in the n ame of the Rural Municipal\nExecutive and the Municipal Executive pursuant to clause (4 ) and other instruments\nof authorization pertaining thereto shall be authenticated as provided for in the  Local\nlaw.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 215", "title": "Provisions r elating to Chairperson and Vice -Chairperson of Rural Municipal Executive", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a Chairperson of Rural Municipal Executive  in each\nRural Municipality. The Rural Municipal Executive shall be formed under his or her\nchairpersonship.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Rural Municipal Executive referred to in clause (1) shall consist of one\nVice-Chairperson, Ward Chairperson elected from each Ward and members elected\npursuant to clause (4).", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Chairperson and the Vice -Chairperson shall be elected by the voters\nresiding within the concerned Rural Municipality area by secret ballots on the basis of\none person one vote, in accordance with the first past the post electoral system.\nExplanation: For the purp oses of this Article, \"Chairperson\" and \"Vice-Chairperson\"\nmean the Chairperson and the Vice-Chairperson of the Rural Municipal Executive.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The members of the Rural Municipal Executive  shall also include  four\nwomen members elected by the members of the Rural Municipal Assembly  from\namongst themselves and two members elected by the Rural Municipal Assembly from\nthe Dalit or minority communit ies, having possessed the qualifications referred to in\nclause (5), within fifteen days after receipt of the final results of the election to the\nRural Municipal Assembly referred to in Article 222.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "A person who has the following  qualifications shall be qualified to be\nelected to the office of the Chairperson, Vice -Chairperson, Ward Chairperson and\nmember: -\n(a) One who is a citizen of Nepal;\n(b) One who has completed the age of twenty-one years;\n(c) One whose name is included in the electo ral rolls of the Rural\nMunicipality;\n(d) One who is not disqualified by any law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The term of office of the Chairperson, Vice -Chairperson, Ward\nChairperson and member shall be five years after the date of being elected.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "A person who has been elected as the Chairperson for two terms shall not\nbe eligible to be a candidate in an election to the Rural Municipality.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "The office of the Chairperson, Vice -Chairperson, Ward Chairperson or\nmember shall fall vacant in any of the following circumstances: -\n(a) In case the Chairperson tenders resignation in writing to the Vice-\nChairperson, and in case the Vice-Chairperson tenders resignation to\nthe Chairperson;\n(b) In case his or her term of office expires;\n(c) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "In case the seat falls vacant pursuant to clause (7) while the term of office\nof the Chairperson or Vice -Chairperson still remains for more than one year , the\nvacancy shall be fulfilled through by-election for the remaining term.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 216", "title": "Provisions relating to Mayor and Deputy Mayor of Municipal Executive", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There\nshall be a Mayor in e ach Municipality  as Head of the Municipal Executive. The\nMunicipal Executive shall be formed under his or her chairpersonship.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Municipal Executive referred to in  clause (1) shall consist of one\nDeputy Mayor , Ward Chairper son elected from each Ward and m embers elected\npursuant to clause (4).", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Mayor and the Deputy Mayor shall be elected by the voters residing\nwithin the concerned Municipal area by secret ballots on the basis of one person one\nvote, in accordance with the first past the post electoral system.\nExplanation: For the purposes of this Article, \"Mayor\" and \"Deputy Mayor\" mean the\nMayor and the Deputy Mayor of the Municipal Executive.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The members of the Municipal Executive shall also include five women\nmembers elected by the members of the Municipal Assembly from amongst\nthemselves and t hree members elected b y the Municipal Assembly from the Dalit or\nminority communities, in possession of the qualification s referred to in  clause (5)\nwithin fifteen days after the final results of the election to the Municipal Assembly\npursuant to Article 223.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "A person who has the following qualification s shall be qualified to be\nelected to the office of the Mayor, Deputy Mayor, Ward Chairperson and member:-\n(a) One who is a citizen of Nepal;\n(b) One who has completed the age of twenty-one years;\n(c) One whose name is included in the electoral rolls of the Municipality;\n(d)  One who is not disqualified by any law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The term of office of the Mayor, Deputy Mayor, Ward Chairperson and\nmember shall be five years after the date of being elected.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "A person who has been elected as the Mayor for two terms shall not be\neligible to be a candidate in an election to the Municipality.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "The office of the Mayor, Deputy Mayor,  Ward Chairperson or Member\nshall fall vacant in any of the following circumstances:-\n(a) In case the Mayor tenders resignation in writing to the Deputy Mayor,\nand in case  the Deputy Mayor  tenders resignation  in writing to the\nMayor;\n(b) In case his or her term of office expires;\n(c) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "In case the seat falls vacant pursuant to clause (8) while the term of office\nof the Mayor or Deputy Mayor still remains for more than one year, the vacancy shall\nbe fulfilled through by-election for the remaining term of office.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 217", "title": "Judicial Committee", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Ther e shall be a three -member judicial committee to be\ncoordinated by its Vice-Chairperson in case of a Rural Municipality and by its Deputy\nMayor in  case of a Municipality , in order to settle disputes under their respective\njurisdictions in accordance with law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The judicial committee referred to in  clause (1) shall consist of two\nmembers elected by th e members of the Rural Municipal Assembly or the Municipal\nAssembly from amongst themselves.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 218", "title": "Conduct of Business of Rural Municipal Executive  and Municipal Executive", "content": "Allocation and conduct of business of the Rural Municipal Executive  and the\nMunicipal Executive shall be carried out in accordance with the rules approved by the\nRural Municipal Executive and the Municipal Executive, respectively.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 219", "title": "Other Provisions relating to Local Level Executive", "content": "Other provisions relating to the\nLocal Level Executive, except those contained in this Part, shall be as provided  for in\nthe federal law subject to this Constitution.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 220", "title": "District Assembly and District Coordination Committee", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a District\nAssembly to make coordinat ion between the Rural Municipalities and Municipalities\nwithin a district.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The District Assembly shall consist of Chairpersons and Vice-Chairpersons\nof Rural Mun icipal Executive s, and Mayors and Deputy Mayors of Municipal\nExecutives within the district. The first meeting of the District Assembly shall be held\nwithin thirty days of the date of final results of the election to the Village Assemblies\nand the Municipal Assemblies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The District Assembly shall elect the District Coordination Committee\nconsisting of a maximum of nine Members including one C hief, one Deputy Chief, at\nleast three women and at least one Dalit or minority.  The District  Coordination\nCommittee shall discharge all functions require d to be discharged by the District\nAssembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "A Member of a Rural Municipal Assembly or Municipal Assembly within the\nconcerned district shall be eligible to be a candidate for the office o f Chief, Deputy\nChief or Member of the District Coordination Committee. In case a member is elected\nto the office of Chief, Deputy Chief or Member of the District Coordination\nCommittee, his or her office of Member of Rural Municipal Assembly  or of\nMunicipal Assembly, as the case may be, shall ipso facto fall vacant.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The term of office of the Ch ief, Deputy Chief and m ember of the District\nCoordination Committee shall be five years after the date of being elected.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The office of the Chief,  Deputy Chief and m ember of the District\nCoordination Committee shall fall vacant in any of the following circumstances:-\n(a) In case the Chief tenders resignation in writing to the Deputy Chief,\nand in case  the Deputy Chief or m ember tenders resignation in\nwriting to the Chief;\n(b) In case his or her term of office expires;\n(c) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The functions, duties and powers of the District Assembly shall be as\nfollows: -\n(a) To make coordination between the Rural Municipalities and\nMunicipalities within the district;\n(b) To monitor development and construction works to make balance of\nsuch works;\n(c) To make coordination between the Federal  and the Provincial\nGovernment offices and Rural Municipalities  and Municipa lities in\nthe district;\n(d) To perform such other functions as provided for in the provincial law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "Provisions relating to the conduct of the District Assembly, facilities of\nMembers of the District Coordination Committee and other matters relating to the\nDistrict Assembly shall be as provided for in the provincial law.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-18", "title": "Local Legislature", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 221", "title": "Legislative Powers of Local Level", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Subject to this Constitution, t he legislative\npowers of the Local Level shall be vested in the Rural Municipal Assembly  and the\nMunicipal Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The legislative powers of the Rural Municipal Assembly  and the\nMunicipal Assembly shall be as enumerated in the lists contained in Sc hedule-8 and\nSchedule-9.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 222", "title": "Composition of Rural Municipal Assembly", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a Rural Municipal\nAssembly in each Rural Municipality.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Rural Municipal Assembly referred to in clause (1) shall consist of the\nChairperson and Vice -Chairperson of the Rural Municipal Executive , Ward\nChairpersons, and four m embers elected from each ward and Members of the Rural\nMunicipal Executive elected from Dalit and minority communities pursuant to clause", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "of Article 215.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A Rural Municipal Assembly  to be formed pursuant to clause (1)  shall\nhave representation of at least two women from each ward.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Each ward of a Rural Municipality  shall have a  Ward Committee\ncomposed of the Ward Chairperson and four m embers in accordance with the federal\nlaw. Such Ward Chairperson and Ward m embers shall be elected in accordance with\nthe first past the post electoral system.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Every person who has completed the age of eighteen years and whose\nname is included in the electo ral rolls of the Rural Municipality shall have a right to\nvote as provided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "A person who has the following qualifications shall be eligible to become a\ncandidate for the office of the Member of the Rural Municipal Assembly:-\n(a) One who is a citizen of Nepal;\n(b) One who has completed the age of twenty-one years;\n(c) One whose name is included as a voter in the electo ral rolls of the\nRural Municipality; and\n(d) One who is not disqualified by any law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "Matters relating to the election to the Rural Municipal Assembly and other\nmatters pertaining thereto shall be as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 223", "title": "Composition of Municipal Assembly", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Each Municipality shall have a Municipal\nAssembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Municipal Assembly referred to in clause (1) shall consist of the Mayor\nand the Deputy Mayor of the Municipal Executive, Ward Chairpersons, and four\nmembers elected from each Ward and m embers of the Municipal Executive elected\nfrom Dalit or minority communities pursuant to clause (4) of Article 216.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A Municipal Assembly to be formed pursuant to  (1) shall have\nrepresentation of at least two women from each Ward.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Each ward of a Municipality shall have a Ward Committee composed of\none Ward Chairperson and four m embers as provided for  in the federal law. Such\nWard Chairperson and Ward m embers shall be elected in accordance with the first\npast the post electoral system.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Every person who has completed the age of eighteen years and whose\nname is included in the electoral rolls of the Municipality shall have a right to vote as\nprovided for in federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "A person who has the following qualification s shall be qualified to be a\ncandidate for the office of member of the Municipal Assembly:-\n(a) One who is a citizen of Nepal;\n(b) One who has completed the age of twenty-one years;\n(c) One whose name included in the electoral rolls of the Municipality;\nand\n(d)  One who is not disqualified by any law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "Matters relating to the election to the Municipal Assembly and other\nmatters pertaining thereto shall be as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 224", "title": "Chairperson and Vice -Chairperson of Rural Municipal Assembly  and Municipal Assembly", "content": "The Chairperson and Vice -Chairperson of a Rural Municipal Executive\nand the Mayor and Deputy Mayor of a Municipal Executive shall ipso facto  be the\nChairperson and Vice -Chairperson of the Rural Municipal Assembly  and the\nMunicipal Assembly, respectively, and perform functions as such.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 225", "title": "Term of Rural Municipal Assembly  and Municipal Assembly", "content": "T he term of a Rural\nMunicipal Assembly and of a Municipal Assembly shall be five years from the date of\nelection. Election to a nother Rural Municipal Assembly  and Municipal Assembly\nshall be completed within six months of the expiration of such term.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 226", "title": "Powers to Make Law", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A Rural Municipal Assembly and Municipal Assembly may\nmake necessary laws on the matters enumerated in the l ists contained in Schedule -8\nand Schedule-9.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The process for making laws referred to in clause (1) shall be as provided\nfor in a provincial law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 227", "title": "Other Matters relating to Rural Municipal Assembly and Municipal Assembly", "content": "Other\nmatters relating to the conduct of business of a Rural Municipal Assembly  and\nMunicipal Assembly, rules of proce dures of meetings, formation of committees,\nconditions in which the office of m ember falls va cant, facilities to be entitled to\nmembers of the Rural Municipal Assembly  and Municipal Assembly and employees\nand offices of the Rural Municipality and Municipality, as the case may be, shall be as\nprovided for in a provincial law.", "children": []}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-19", "title": "Local Financial Procedures", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 228", "title": "No Tax to be levied or Loan to be r aised", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No tax shall be levied and collected and\nno loan raised in the Local Level except in accordance with law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Local Level may levy tax by making a law on matters falling within its\njurisdiction without prejudice to national economic policies,  carriage of goods and\nservices, capital and labour market, and the neighbouring Province or Local Level.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 229", "title": "Local Consolidated Fund", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a Local Consolidate Fund in e ach Rural\nMunicipality and Municipality under the Local Level. All revenues received by the Rural\nMunicipality or Municipality, any amounts of grants received from the Government of\nNepal and the Provincial Government, all loans raised by the Rural Municipality and\nMunicipality, and amounts received from other sources shall be credited to such Fund.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Matters relating to expenditures from the Local Consolidated Fund referred\nto in clause (1) shall be as provided for in a Local law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 230", "title": "Estimates of Revenues and Expenditures of Rural Municipality and Municipality", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Rural Municipal Executive  and the Municipal Executive sh all, subject to this\nConstitution, lay an estimate of revenues and expenditures of every fiscal year before, and\nhave the estimate adopted by, the Rural Municipal Assembly  and the  Municipal\nAssembly, respectively, as provided for in the Local law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In case , in laying an estimate of revenues and expenditures pursuant to\nclause (1), the Rural Municipal Executive or Municipal Executive is required to make\na deficit budget, it shall also propose the sources to meet the deficit as provided for in\nthe federal law and provincial law.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-20", "title": "Interrelations between Federation, Province and Local Level", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 231", "title": "Legislative Interrelations between Federation and Provinces", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A federal law may be\nmade to be applicable to the whole of, or, if required, to any part of, the territory of\nNepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A provincial law  may be made to be applicable to the whole of, or as\nrequired, to any part of the territory of the Province.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case two or more Provinces make a request to the Government of Nep al\nto make laws on any matter enumerated in Schedule -6, the Federal Parliament may\nmake necessary laws. Such laws shall be applicable to the concerned Provinces only.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 232", "title": "Relations between Federation, Province and Local Level", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Th e relations between\nthe Federation, Provinces and Local Levels  shall be based on the principles of\ncooperation, co-existence and coordination.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Government of Nepal may, in accordance with  this Constitution and\nfederal law, give necessary directions to any Provincial Council of Ministers on\nmatters of national importance and on matters to be coordinated among the Provinces,\nand it shall be the duty of the concerned Provincial Council of Ministers to abide by\nsuch directions.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case  any type of act that may seriously undermine the  sovereignty,\nterritorial integrity, nationality or independence  of Nepal  is carried out in any\nProvince, the President may, as required, warn such Provincial Council of Ministers ,\nsuspend the Provincial Council of Ministers and the Provincial Assembly for a period\nnot exceeding six months or dissolve them.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Any suspension or dissolution of any Provincial Council of Ministers and\nthe Provincial Assembly shall be approved by a majority of the total number of the\nthen members of the Federal Parliament within thirty-five days.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In case dissolution made pursuant to clause (3) is approved by the Federal\nParliament, election to the Provincial Assembly shall be held in such  Province within\nsix months.\nProvided that such suspension or dissolution  shall, ipso facto  be ceased to\noperate in case the Federal Parliament does not approve it.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The Federal Rule shall apply to such Province during the period of such\nsuspension in case the suspension made pursuant to clause (3) is approved pursuant to\nclause (4) and until the election to the Provincial Assembly is held pursuant to clause", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": ".", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "During the continuance of the Federal Rule, the Federal Parliament may\nmake laws with respect to any matter enumerated in the List contained in Schedule-6.\nSuch laws shall continue to apply until repealed by another laws made by the\nconcerned Provincial Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "The Government of Nepal may, directly or  through the Provincial\nGovernment, render necessary assistance and give necessary directives to any Rural\nMunicipal Executive or Municipal Executive in accordance with this Constitution and\nthe federal law . It shall be the duty of the Rural Municipal Executive  or Municipal\nExecutive to abide by such directives.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 233", "title": "Relations between Provinces", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "One Province shall render assistance in the\nexecution of legal provisions or judicial and administrative decisions or orders of\nanother Province.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Province may exchange information and consult with another Province\non matters of common concern and interest, coordinate each other on their activities\nand legislations and extend mutual assistance.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A Province shall, in accordance with its provincial law , provide equal\nsecurity, treatment and facility to residents of another Province.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 234", "title": "Inter-Province Council", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be an Inter -Province Council as follows to\nsettle political disputes arising out between the Federation and a Province and\nbetween Provinces:-\n(a) Prime Minister               - Chairperson\n(b) Minister for Home Affairs of the Government of Nepal     - Member\n(c) Minister for Finance of the Government of Nepal    - Member\n(d) Chief Ministers of the concerned Province               - Member", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Inter-Province Council may meet as required.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Inter -Province Council may invite to its meeting a  Minister of the\nGovernment of Nepal and a Minister of the concerned Province who is responsible for\nthe matter of dispute and a concerned expert.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The rules of procedures of the meeting of the Inter -Province Council shall\nbe as determined by the Council itself.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 235", "title": "Coordination between Federation, Province and Local  Level", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Federal\nParliament shall make necessary laws in order to maintain coordination between the\nFederation, Province and Local Level.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Provincial Assembly may maintain coordination between the Province\nand Rural Municipalities  or Municipalities and settle political disputes, if any, that\nhave arisen, in coordination with the conc erned Rural Municipality, Municipality and\nthe District Coordination Committee.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The processes and procedures for the settlement of disputes referred to in\nclause (2) shall be as provided for in the provincial law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 236", "title": "Inter-Province Commerce", "content": "Notwithstanding anything contained elsewhere in this\nConstitution, it is prohibited to make  any type of obstruction to the carriage of goods\nor extension of services by a Province or Local Level to another Province or Local\nLevel or to the carriage of goods or extension of services to any Province or Local\nLevel or to levy tax, fee or charge thereon or to make any type of discrimination on\nthe carriage or extension of such services or goods.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 237", "title": "Not to Affect Jurisdiction of Constitutional Bench of Supreme Court", "content": "Nothing\ncontained in this Part shall affect the jurisdiction of the Constitutional Bench of th e\nSupreme Court referred to in Article 137.", "children": []}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-21", "title": "Commission for the Investigation of Abuse of Authority", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 238", "title": "Commission for the Investigation of Abuse of Authority", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a\nCommission for the Investigation of Abuse of Authority  of Nepal consisting of the\nChief Commissioner and four other Commissioners. The Chief Commissioner shall\nact as the Chairperson of the Commission for the Investigation of Abuse of Authority.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall, on recommendation of the Constitutional Council,\nappoint the Chief Commissioner and Commissioners.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of office of the Chief Commissioner and Commissioners shall be\nsix years from the date of appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Notwithstanding anything contained in clause (3), the office of the Chief\nCommissioner or a Commissioner shall fall vacant  in any o f the following\ncircumstances: -\n(a) In case he or she tenders resignation in writing to the President;\n(b) In case he or she attains the age of sixty-five years,\n(c) In case  a motion of impeachment is adopted against him or her\npursuant to Article 101;\n(d) In case  he or she is removed from office by the President on\nrecommendation of the Constitutional Council on grounds of his or\nher inability to hold office and discharge  the functions due to\nphysical or mental illness;\n(e) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The Chief Commissioner and Commissioners appointed pursuant to clause", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "shall not be eligible for reappointment.\nProvided that a Commissioner may be appointed to the office of Chief\nCommissioner, and when a Commissioner is so appointed as the Chief Commissioner,\nhis or her term of office shall be so computed as to include his or her term as the\nCommissioner.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "A person shall be eligible to be appointed as the Chief Commissioner or a\nCommissioner of the Commission for the Investigation of Abuse of Author ity in case\nhe or she possesses the following qualifications:-\n(a) One who has acquired a bachelor's degree from a recognized\nuniversity;\n(b) One who is not a member of any political party at the time of\nappointment;\n(c) One who has gained at least twenty years of experiences in the field\nof either accounting, revenue, engineering, law, development or\nresearch and being a distinguished person;\n(d) One who has attained the age of forty-five years; and\n(e) One who bears high moral character.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The remuneration and other terms and conditions of service of the Chief\nCommissioner and the Commissioners shall be as provided for in the federal law. The\nremuneration and terms and conditions of service of the Chief Commissioner and the\nCommissioners shall not, so long as they hold office, be altered to their disadvantage.\nProvided that this provision shall not apply in case s where a state of\nemergency is declared because of extreme economic disarrays.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "A p erson once appointed as the Chief Commissioner or Commissioner\nshall not be eligible for appointment in other government service.\nProvided that nothing in this clause shall be deemed to be a bar to the\nappointment to any political position or to any position which has the responsibility of\nmaking investigations, inquiries or findings on any subject, or to any position which\nhas the responsibility of submitting advice, opinion or recommendation after carrying\nout a study or research on any subject.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 239", "title": "Functions, Duties and Powers of Commission for the Investigation of Abuse of Authority", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Commission for the Investigation of Abuse of Authority may, in\naccordance with law, conduct, or cause to be conducted investigations of any abuse of\nauthority committed through corruption by any person holding public office.\nProvided that this clause shall not apply to any official in relation to whom this\nConstitution itself separately provides for such action and to any official in relation to\nwhom other law provides for a separate special provision.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In the case of the persons who may be removed from the office by the\nvirtue of adoption of a motion of impeachment pursuant to  Article 101, the Judges\nwho may be removed by the Judicial Council and the persons who are liable to action\nin accordance with  the Army Act, it may conduct , or cause to be conducted,\ninvestigations in accordance with the federal law after they have been  removed from\noffice.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case the Commission for the Investigation of Abuse of Authority finds,\non investigation conducted pursuant to clause (1) or (2), that a person holding public\noffice has committed an act which is defined by law as corruption, it may file, or\ncause to be filed, a  case against that person and other person involved in that offense\nin the competent court in accordance with law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "In case, on investigation conducted pursuant to clause (1) or (2), any act or\naction done or taken by a person holding public office appe ars to be of such nature as\nto be falling under the jurisdiction of another official or institution, the Commission\nfor the Investigation of Abuse of Authority may write to the concerned official or\ninstitution for necessary action.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The Commission for the Investigation of Abuse of Authority may delegate\nany of its functions, duties and powers on the conducting of investigations or filing\ncases, to the Chief Commissioner, a Commissioner or an officer employee of the\nGovernment of Nepal to be exercised an d complied with subject to the specified\nconditions.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "Other functions, duties and powers and rules of procedure of the\nCommission for the Investigation of Abuse of Authority shall  be as provided for in\nthe federal law.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-22", "title": "Auditor General", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 240", "title": "Auditor General", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be an Auditor General of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall, on the recommendation of the Constitutional Council,\nappoint the Auditor General.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of office of the Auditor General shall be six years from the date\nof appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Notwithstanding anything contained in clause (3), the office of the Auditor\nGeneral shall fall vacant in any of the following circumstances: -\n(a) In case he or she tenders resignation in writing to the President;\n(b) In case he or she attains the age of sixty-five years;\n(c) In case a motion of impeachment is adopted against him or her\npursuant to Article 101;\n(d) In case he or she is removed from office by the President on\nrecommendation of the Constitutional Council on grou nds of his or\nher inability to hold office and discharge the functions due to physical\nor mental illness;\n(e) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The Auditor General appointed pursuant to clause (2) shall not be eligible\nfor reappointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "A person shall be eligible to be appointed as the Auditor General in case he\nor she possesses the following qualifications:-\n(a) One who has served in the Special Class of the Government of Nepal\nor having at least twenty years of experiences in audit related work ,\nafter having obtained a bachelor's degree in management, commerce\nor accounting from a recognized university or having passed a\nchartered accountancy examination;\n(b) One who is not  a member of any political party at the time of\nappointment;\n(c) One who has attained the age of forty-five years; and\n(d) One who bears high moral character.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The remuneration and terms and conditions of service of the Auditor\nGeneral shall be as provided for in the federal law . The remuneration and conditions\nof service of the Auditor General  shall not, so long as he or she  holds office, be\naltered to his or her disadvantage.\nProvided that this provision shall not apply in case s where a state of\nemergency is declared because of extreme economic disarrays.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "A person once appointed as the Auditor General shall not be eligible for\nappointment in another government service.\nProvided that nothing in this clause shall be deemed to be a bar to the\nappointment to any political position or to any position which has the responsibility of\nmaking investigations, inquiries or findings on any subject, or to any position which\nhas the responsibility of submitting advice, opinion or recommendation after carrying\nout a study or research on any subject.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 241", "title": "Functions, Duties and Powers of Auditor-General", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The accounts of all Federal and\nProvincial Government Offices including the Office of the President, Office of the\nVice-President, Supreme Court, Federal Parliament, Provincial Assembly, Provincial\nGovernment, Local Level, Constitutional Bod ies and Offices thereof, Courts, Office\nof the Attorney General , Nepal Army, Nepal Police and Armed Police Force, Nepal\nshall be audited by the Auditor -General in accordance with  law, having regard to ,\ninter alia, the regularity, economy, efficiency, effectiveness and the propriety thereof.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Auditor General shall be consulted in the matter of appointment of an\nauditor to carry out the  audit of a corporate body of which the Government of Nepal\nor Provincial Government owns more than fifty percent of  the shares or assets. The\nAuditor General may also issue necessary directives setting forth the principles for\ncarrying out the audit of such corporate body.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Auditor General shall, at all times,  have power to examine any books\nof accounts for the purpose of carrying out the functions referred to in  clause (1). It\nshall be the duty of the concerned chief of office to provide all such documents and\ninformation as may be demanded by the Auditor Gene ral or any of his or her\nemployees.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The accounts to be audited pursuant to clause (1) shall be maintained in the\nform prescribed by the Auditor General, as provided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In addition to the accounts of the offices referred to in clause (1), federal\nlaw may also require the accounts of any other office s or bodies to be audited by the\nAuditor General.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-23", "title": "Public Service Commission", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 242", "title": "Public Service Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a Public Service Commission of Nepal,\nconsisting of the Chairperson and four other Members.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall, on the recommendation of the Constitutional Council,\nappoint the Chairperson and Members.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "At least fifty percent of the total number of Members of the Public Service\nCommission shall be appointed from amongst the persons who have worked for\ntwenty years or more in any government service, and the rest of the Members shall be\nappointed from among st the persons who hold reputation after having conducted\nresearch, studies, teaching or any other significant work in the field of science,\ntechnology, art, literature, law, public a dministration, sociology or other sphere of\nnational life.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The term o f office of the Ch airperson and Members of the Public Service\nCommission shall be six years from the date of appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The Chairperson and Members appointed pursuant to clause (2) shall not\nbe eligible for reappointment.\nProvided that a Member may be appointed to the office of Chairperson, and\nwhen a Member is so appointed as the Chairperson, his or her term of office shall be\nso computed as to include his or her term as the Member.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "Notwithstanding anything contained in clause (4 ), the office of  the\nChairperson or a Member of the Public Service Commission shall fall vacant in any of\nthe following circumstances: -\n(a) In case he or she tenders resignation in writing to the President;\n(b) In case he or she attains the age of sixty-five years;\n(c) In case a motion of impeachment is adopted against him or her\npursuant to Article 101;\n(d) In case he or she is removed from the office by the President on\nrecommendation of the Constitutional Council on grounds of his or\nher inability to hold office and discharge the functions due to physical\nor mental illness;\n(e) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "A person shall be eligible to be appointed as the Chairperson or a m ember\nof the Public Service Commission in case  he or she possesses the following\nqualifications:-\n(a) One who has  acquired a Master's degree from a recognized\nuniversity;\n(b) One who is not  a member of any political party at the time of\nappointment;\n(c) One who has attained the age of forty-five years; and\n(d) One who bears high moral character.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "The remuneration and other conditions of service of the Chairperson and\nthe members of the Public Service Commission  shall be as provided for in the federal\nlaw. The remuneration and conditions of service of the Chairperson and the Members\nof the Public Service Commission shall not be altered to their disadvantage, so long as\nthey hold office.\nProvided that this provision shall not apply in case s where a state of\nemergency is declared because of extreme economic disarrays.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "A person once appointed as the Chairperson and the members of the Public\nService Commission  shall not be eligible for appointment in other government\nservice.\nProvided that nothing in this clause shall be deemed to be a bar to the\nappointment to any political position or to any position which has the responsibility of\nmaking investigations, inquiries or findings on any subject, or to any position which\nhas the responsibility of submitting advice, opinion or recommendation after carrying\nout a study or research on any subject.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 243", "title": "Functions, Duties and Powers of Public Service Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "It shall be the duty\nof the Public Service Commission to conduct examinations for the selection of\nsuitable candidates to be appointed to the positions in the Civil Service.\nExplanation: For the p urposes of this Article, \"positions in the Civil Service\" mean s\nall positions in the services of the Government of Nepal, other than the positions in\nthe services of Army personnel, Nepal Police or Armed Police Force, Nepal and such\nother positions in the services as are excluded by an Act from the Civil Service.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Public Service Commission shall conduct written examinations to be\nheld for appointment to the offices of the Nepal Army, Nepal Police, Armed Police\nForce, Nepal, other federal governmental services and of bodies corporate, other than\nthe positions in the Civil Service.\nExplanation: For the pur poses of this Article, \"body corporate\" means a corporation,\ncompany, bank or board of which more than fifty percent or more of the shares or\nassets is owned or controlled by the Government of Nepal , except a University or\nTeacher Service Commission, or a Commission, Corporation, Authority, Body,\nAcademy, Board, Centre, C ouncil and other body corporate of similar nature\nestablished under federal law or formed by the Government of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Public Service Commission shall be consulted on the general\nprinciples to be followed in the course of making appointment and promotio n to any\nposition of the Nepal A rmy, Nepal Police, Armed Poli ce Force, Nepal and other\nfederal government services.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The Public Service Commission shall be consulted on the laws relating to\nthe conditions of service of the  employees in the service of a  body corporate and on\nthe general principles to be followed in the course of making promotion to any\nposition of such service and taking departmental action against any such employee.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "No permanent appointment to any pensionable position  chargeable on the\nGovernment of Nepal  shall be made except in consultation with the Public Service\nCommission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The Public Service Commission shall be consulted on the following\nsubjects: -\n(a) Matters concerning the law relating to the conditions of service of\nthe Federal Civil Service;\n(b) Principles to be followed in making appointments to, promotions to,\nthe Federal Civil Service or positions thereof and taking\ndepartmental action;\n(c) Matters concerning the suitability of an y candidate for appointment\nto the Federal Civil Service position for a period of more than six\nmonths;\n(d) Matters concerning the suitability of any candidate  for transfer or\npromotion from a position in one type of Federal Civil Service to  a\nposition in other type of Federal Civil Service or transfer or\npromotion from other government service to the Federal Civil\nService or for a change in service or transfer from a position in a\nProvincial Civil Service to a position in the Federal Civil Service or\nfrom a position in the Fed eral Civil Service to a Provincial Civil\nService;\n(e) Matters concerning the permanent transfer or promotion of an\nemployee working in any position which does not require\nconsultation with the Public Service Commission to any position\nwhich requires consul tation with the Public Service Commission;\nand\n(f) Matters relating to departmental action against any employee of the\nFederal Civil Service.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "Notwithstanding anything contained in clause (6), matters falling within the\njurisdiction of the Judicial Service Commission referred to in Article 154 shall be as\nprovided for in that Article.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "The Public Service Commission may delegate any of its functions, duties\nand powers to its Chairperson or Member, an employee of the Government of Nepal\nas to be exercised and complied with subject to the specified conditions.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "Other functions, duties and powers and rules of procedure of the Public\nService Commission shall be as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 244", "title": "Provisions relating to Provincial Public Service Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Each Province shall\nhave a Provincial Public Service Commission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The f unctions, duties and powers of the Provincial Public Service\nCommission shall be as provided for in the provincial law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Federal Parliament shall by a law determine grounds and standards for\nthe purposes of clause (2).", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-24", "title": "Election Commission", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 245", "title": "Election Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be an Election Commission of Nepal, consisting\nof a Chief Commissioner and four other Commissioners. The Chief Commissioner\nshall act as the chairperson of the Election Commission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall, on the recommendation of the Const itutional Council,\nappoint the Chief Election Commissioner and Commissioners.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of office of the Chief Election Commissioner and Commissioners\nof the Election Commission shall be six years from the date of appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Notwithstanding anything contained in clause (3 ), the office of the Chief\nElection Commissioner or Election Commissioner shall fall vacant in any of the\nfollowing circumstances: -\n(a) In case he or she tenders resignation in writing to the President;\n(b) In case he or she attains the age of sixty-five years;\n(c) In case  a motion of impeachment is adopted against him or her\npursuant to Article 101;\n(d) In case  he or she is removed from office by the President on\nrecommendation of the Constitutional Council on grounds of his or\nher inability to hold office and discharge the functions due to physical\nor mental illness;\n(e)  In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The Chief Election Commissioner and Commissioners appointed pursuant\nto clause (2) shall not be eligible for reappointment.\nProvided that a Commissioner may be appointed to the office of Chief\nElection Commissioner , and when a Commissioner is so appointed as the Chief\nElection Commissioner, his or her term of office shall be so computed as to include\nhis or her term as the Commissioner.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "A person shall be eligible to be appointed as the Chief Election\nCommissioner or an Election Commissioner in case he or she possesses the following\nqualifications:-\n(a) One who has  attained a bachelor's degree from a recognized\nuniversity;\n(b) One who is not  a member of any political party at the time of\nappointment;\n(c)  One who has attained the age of forty-five years; and\n(d) One who bears high moral character.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The remuneration and other conditions of service of the Chief Election\nCommissioner and Election Commissioners shall be as provided for in the federal\nlaw. The remuneration and conditions of service of the Chief Election Commissioner\nand the Commissioners shall not be altered to their disadvantage  so long as they hold\noffice.\nProvided that this provision shall not apply in case s where a state of\nemergency is declared because of extreme economic disarrays.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "A person once appointed as the Chief Election Commissioner and a\nCommissioner of the Election Commission shall not be eligible for appointment in\nother government service.\nProvided that nothing in this clause shall be deemed to be a bar to the\nappointment to any political position or to any position which has the responsibility of\nmaking investigations, inquiries or findings on any subject, or to any position which\nhas the responsibility of submitting advice, opinion or recommendation after carrying\nout a study or research on any subject.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 246", "title": "Functions, Duties and Powers of Election Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Election Commission\nshall, subject to this Constitution and federal  law, conduct, supervise, direct and\ncontrol the election to the President, Vice -President, members of the Federal\nParliament, members of Provincial Assemblies and members of Local Level . The\nElection Commission shall, for these purposes, prepare electoral rolls.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Election Commission shall hold a referendum on a matter of national\nimportance in accordance with this Constitution and federal law", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In case, after nomination of candidacy for the President, Vice-President,\nmember of the Federal  Parliament, member of Provincial Assemblies or member of\nLocal Level  has been filed but before the election  results are declared , a question\narises about the qualification of a candidate, the Election Commission shall decide\nthat question.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The Election Commission may so delegate any of its functions, duties and\npowers to the Chief Election Commissioner, Election Commissioner or any\ngovernment employee as to be exercised and complied with subject to the specified\nconditions.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Other functions, duties and powers and rules of procedure of the Election\nCommission shall be as provided for in federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 247", "title": "To provide Necessary Assistance to Election Commission", "content": "The Government of Nepal,\nProvincial Government and Local Government s hall provide such employees and\nother assistance to  the Election Commission as may be required to perform its\nfunctions in accordance with this Constitution.", "children": []}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-25", "title": "National Human Rights Commission", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 248", "title": "National Human Rights  Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a  National Human Rights\nCommission of Nepal, consisting of a Chairperson and four other members.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall, on the recommendation of the Constitutional Council,\nappoint the Chairperson and members of the National Human Rights Commission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of office of the Chairperson and members of the National Human\nRights Commission shall be six years from the date of appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The Chairperson and m embers appointed pursuant to  clause (2) shall not\nbe eligible for reappointment.\nProvided that a Member may be appointed to the off ice of Chairperson, and\nwhen a member is so appointed as the Chairperson, his or her term of office shall be\nso computed as to include his or her term as the Member.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Notwithstanding anything contained in clause (3 ), the office of the\nChairperson or m ember of the National Human Rights Commission shall fall vacant\nin any of the following circumstances:-\n(a) In case he or she tenders resignation in writing to the President;\n(b) In case  a motion of impeachment is adopted against him or her\npursuant to Article 101;\n(c) In case  he or she is removed from office by the President on\nrecommendation of the Constitutional Council on grounds of his or\nher inability to hold office and discharge the functions due to physical\nor mental illness;\n(d)  In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "A person shall be eligible to be appointed as the Ch airperson or a member\nof the National Human Rights Commission  in case he or she possesses the following\nqualifications:-\n(a) In the case of the Chairperson,  one who is a retired Chief Justice or\na retired Justice of Supreme Court  and has rendered outstanding\ncontribution to the protection and promotion of human rights or\nbeing a renowned person  having been active for at least twenty\nyears in and rendered outstanding contribution to the protection and\npromotion of human rights or to various fields of national life;\n(b) In the case of a Member, one who is  involved in the field of the\nprotection and promotion of human rights or rights and interests of\nthe child or being a renowned person having been active for at least\ntwenty years in and rendered outstanding contribution to various\nfields of national life;\n(c) One who has  acquired a Bachelor's degree from a recognized\nuniversity;\n(d) One who has attained the age of forty-five years;\n(e) One who is not  a member of any political party at the time of\nappointment;\n(f) One who bears high moral character.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The remuneration and other conditions of s ervice of the Chairperson and\nmembers of the National Human Rights Commission shall be as provided for in  the\nfederal law . The remuneration and conditions of service of  the Chairperson and\nmembers of the National Human Rights Commission  shall not, so long as they hold\noffice, be altered to their disadvantage.\nProvided that this provision shall not apply in case s where a state of\nemergency is declared because of extreme economic disarrays.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "A person once appointed as the Chairperson or a member of the National\nHuman Rights Commission shall not be eligible for appointment in other government\nservice.\nProvided that nothing in this clause shall be deemed to be a bar to the\nappointment to any political position or to any position which has the responsibility of\nmaking investigations, inquiries or findings on any subject, or to any position which\nhas the responsibility of submitting advice, opinion or recommendation after carrying\nout a study or research on any subject.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 249", "title": "Functions, Duties and Powers of National Human Rights Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "It shall be\nthe duty of the National Hum an Rights Commission to respect, protect and promote\nhuman rights and ensure effective enforcement thereof.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "For the accomplishment of the duty referred to in clause (1), the National\nHuman Rights Commission shall perform the following functions:\n(a) To inquire, on its own initiative or on petition or complaint presented\nin or sent to the Commission by a victim or any person on his or her\nbehalf or on informatio n received by the Commission from any\nsource, into and investigate complaints of violations of human rights\nof an individual or group  or abetment thereof, and make\nrecommendation for action against the perpetrators;\n(b) In case  any official who has the res ponsibility or duty to prevent\nviolations of human rights fails to fulfil or perform his or her\nresponsibility or duty or shows reluctance in the fulfilment or\nperformance of his or her responsibility or duty, to make\nrecommendation to the concerned author ity to take department al\naction against such official;\n(c) In case  it is required to institute a case against any person or\norganization who has violated human rights, to make\nrecommendation to file a case in the court in accordance with law;\n(d) To coordinate and collaborate with civil society in order to en hance\nawareness on human rights;\n(e) To make recommendation, accompanied by the reasons and grounds,\nto the concerned body for taking departmental action against and\nimposing punishment on those who are violators of human rights;\n(f) To carry out periodic reviews of the relevant laws relating to human\nrights and make recommendation to the Government of Nepal for\nnecessary improvements in and amendments to such laws;\n(g)  In case  Nepal has to become a party to any international treaty or\nagreement on human rights, to make recommendation, accompanied\nby the reasons therefor, to the Government of Nepal; and monitor\nwhether any such treaty or an agreement to which Nepal is already a\nparty has been implemented, and in case it is found not to have been\nimplemented, to make recommendation to the Government of Nepal\nfor its implementation;\n(h) To publish, in accordance with law, the names of the officials,\npersons or bodies who have faile d to observe or implement any\nrecommendations or directives made or given by the National Human\nRights Commission in relation to the violations of human rights, and\nrecord them as violators of human rights.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In discharging its functions or performing i ts duties, the National Human\nRights Commission may exercise the following powers: -\n(a) To exercise all such powers as of a court in respect of the summoning\nand requiring the presence of any person before the Commission and\nseeking and recording his or h er information or statements or\ndepositions, examining evidence and producing exhibits and proofs;\n(b) On receipt of information by the Commission in any manner that a\nserious violation of human rights has already been committed or is\ngoing to be committed, to search any person or his or her residence or\noffice, enter such residence or office without notice, and, in the course\nof making such search, take possession of any document, evidence or\nproof related with the violation of human rights;\n(c) In the event of necessity to take action immediately on receipt of\ninformation that the human rights of any person are being violated, to\nenter any government office or any other place withou t notice and\nrescue such person;\n(d) To order for the provision of compensation in accordance with law to\nany person who is a victim of the violations of human rights.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The National Human Rights  Commission may so delegate any of its\nfunctions, duties and powers to the Chairperson of the Commission, any of its\nMembers or a government employee as to be exercised and complied with subject to\nthe specified conditions.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Other functions, duties and powers and rules of procedure of the National\nHuman Rights Commission shall be as provided for in the federal law.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-26", "title": "National Natural Resources and Fiscal Commission", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 250", "title": "National Natural Resources and Fiscal Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There  shall be a National\nNatural Resources and Fiscal Commission of Nepal, consisting of a maximum of five\nmembers including a Chairperson.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall, on the recommendation of the Constitutional Council,\nappoint the Chairperson and members of the  National Natural Resources and Fiscal\nCommission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of office of the Chairperson and members of the National Natural\nResources and Fiscal Commission shall be six years from the date of appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Notwithstanding anything contained in clause (3), the office of the\nChairperson or m ember of the National Natural Resources and Fiscal Commission\nshall fall vacant in any of the following circumstances: -\n(a) In case he or she tenders resignation in writing to the President;\n(b) In case he or she attains the age of sixty-five years;\n(c) In case  a motion of impeachment is adopted against him or her\npursuant to Article 101;\n(d) In case  he or she is removed from office b y the President on\nrecommendation of the Constitutional Council on grounds of his or\nher inability to hold office and discharge the functions due to physical\nor mental illness;\n(e) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The Chairperson and m embers appointed pursuant to clause (2) shall not\nbe eligible for reappointment.\nProvided that a m ember may be appointed to the off ice of Chairperson, and\nwhen a member is so appointed as the Chairperson, his or her term of office shall be\nso computed as to include his or her term as the member.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "A person shall be eligible to be appointed as the Chairperson or a m ember\nof the National Natural Resources and Fiscal Commission in case he or she possesses\nthe following qualifications:-\n(a) One who has  expertise upon being active for at least twenty years in\nthe field of natural resources or fiscal management, economic s, law,\nmanagement, after holding a bachelor's degree in the relevant subject\nfrom a recognized university;\n(b) One who is not  a member of  any political party at the time of\nappointment,\n(c) One who has attained the age of forty-five years,\n(d) One who bears high moral character.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The remuneration and other conditions of service of the Chairperson and\nmembers of the National Natural Resources and Fiscal Commission s hall be as\nprovided for in the federal law, and their remuneration and conditions of service shall\nnot, so long as they hold office, be altered to their disadvantage.\nProvided that this provision shall not apply in cases where a state of\nemergency is declared because of extreme economic disarrays.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "A person once appointed as the Chairperson or a m ember of the National\nNatural Resources and Fiscal Commission shall not be eligible for appointment in\nother government service.\nProvided that nothing in this clause shall be deemed to be a bar to the\nappointment to any political position or to any position which has the responsibility of\nmaking investigations, inquiries or findings on any subject, or to any position which\nhas the responsibility of submitting advice, opinion or recommendation after carrying\nout a study or research on any subject.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 251", "title": "Functions, Duties and Powers of National Natural Resources and Fiscal Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The functions, duties and powers of the National Natural Resources and Fiscal\nCommission shall be as follows:-\n(a) To determine detailed basis  and modality for the distribution of\nrevenues between the Federal , Provinces and Local Governments out\nof the Federal Consolidated Fund in accordance  with the Constitution\nand law;\n(b) To make a recommendation about equalization grants to be provided to\nthe Province and Local Governments out of the Federal  Consolidated\nFund;\n(c) To conduct study and research work and prepare parameters as to\nconditional grants to be provided to the Province and Local\nGovernments in accordance with national policies and programs,\nnorms and condition of infrastructures;\n(d) To determine detai led basi s and modality for the distribution of\nrevenues between the Province and Local Governments out of the\nProvincial Consolidated Fund;\n(e) To recommend measures to meet expenditures of the Federal, Province\nand Local Governments, and to reform revenue collection;\n(f) To analyse macro-economic indicators and recommend ceiling of\ninternal loans that the Federal , Province and Local Governments can\nborrow;\n(g) To review the bases for th e distribution between the Federal  and\nProvincial Governments of revenues and recommend for revision;\n(h) To set bases for the determination of shares of the Government of\nNepal, Provincial Government and Local Level  in investments and\nreturns, in the mobilization of natural resources;\n(i) To do study and research work on possible disputes that may arise\nbetween the Federation and the Provinces, between Provinces, between\na Province and a Local Level, and between Local Levels , and make\nsuggestions to act in a coordinated manner for the preven tion of such\ndisputes.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The National Natural Resources and Fiscal Commission shall carry out\nnecessary study and research work about environmental impact assessment required\nin the course of distribution of natural resources, and make recommendations  to the\nGovernment of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Other functions, duties and powers and rules of procedure of the National\nNatural Resources and Fiscal  Commission, detailed bases required to be followed in\nthe mobilization of natural resources or distribution of revenues, a nd other matters\nincluding conditions of service of the officials of the Commission shall be as provided\nfor in the federal law.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-27", "title": "Other Commissions", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 252", "title": "National Women Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a National Women Commission of\nNepal, consisting of a Chairperson and four other members.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall, on the recommendation of the Constitutional Council,\nappoint the Chairperson and members of the National Women Commission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of office of the Chairperson and members of the National Women\nCommission shall be six years from the date of appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Notwithstanding anything contained in clause (3), the office of the\nChairperson or member of the National Women Commission shall fall vacant in any\nof the following circumstances: -\n(a) In case he or she tenders resignation in writing to the President;\n(b) In case he or she attains the age of sixty-five years;\n(c) In case  a motion of impeachment is adopted against him or her\npursuant to Article 101;\n(d)  In case  he or she is removed from office by the President on\nrecommendation of the Constitutional Council on grounds of his or\nher inability to hold office and discharge the functions due to physical\nor mental illness;\n(e) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The Chairperson and members appointed pursuant to  clause (2) shall not\nbe eligible for reappointment.\nProvided that a member may be appointed to the office of Chairperson, and\nwhen a member is so appointed as th e Chairperson, his or her term of office shall be\nso computed as to include his or her term as the member.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "A person shall be eligible to be appointed as the Chairperson or a member\nof the National Women Commission in case  he or she possesses the follow ing\nqualifications:-\n(a) A woman who has rendered outstanding contribution , for at least ten\nyears, in the field of rights and interests of women or gender justice or\nwomen development or human rights and law;\n(b) In the case of the Chairperson, one who has acquired a Bachelor's\ndegree from a recognized university;\n(c) One who has attained the age of forty-five years;\n(d) One who is not  a member of any political party at the time of\nappointment, and\n(e) One who bears high moral character.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The remuneration and conditions of service of the Chairperson and\nmembers of the National Women Commission shall be as provided for in  the federal\nlaw, and their remuneration and conditions of service shall not, so long as they hold\noffice, be altered to their disadvantage.\nProvided that this provision shall not apply in case s where a state of\nemergency is declared because of extreme economic disarrays.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "A person once appointed as the Chairperson or a member of the National\nWomen Commission shall not be eligible for appointment in other government\nservice.\nProvided that nothing in this clause shall be deemed to be a bar to the\nappointment to any political position or to any position which has the responsibility of\nmaking investigations, inquiries or findi ngs on any subject, or to any position which\nhas the responsibility of submitting advice, opinion or recommendation after carrying\nout a study or research on any subject.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 253", "title": "Functions, Duties and Powers of National Women Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The functions,\nduties and powers of the National Women Commission shall be as follows:-\n(a) To formulate policies and programs concerning the rights and interests of\nthe women and submit them to the Government of Nepal for\nimplementation;\n(b) To monitor as to whether or not laws concerning the rights and interests of\nthe women and obligations under the international treaties to which Nepal\nis a party have been implemented, and make suggestions, accompanied by\nthe measures for their effective compliance and implementation  to the\nGovernment of Nepal;\n(c) In order to have the women included in the mainstream of national\ndevelopment and ensure proportional participation in all organs of the\nState, to assess, monitor and evaluate the existing policies and programs,\nand make recommendation to the Government of Nepal for their effective\nimplementation;\n(d) To carry out study and research work on the legal provisions relating to\ngender equality, empowerment of women and relating to women, make\nrecommendations to the concerned bodies on reforms to be made on such\nlaws, and monitor the same;\n(e) To make suggestions to the Government of Nepal about the preparation of\nreports to be submitted by Nepal in accordance with the provisions\ncontained in the international treaties or agreements concerning women's\nrights, to which Nepal is a party;\n(f) In case it is necessary to file cases against any persons or bodies on matters\nof violence against women or being subjected to social ill -practices or\ninfringement of or deprivation of enjoyment of women's rights, to make\nrecommendations to the concerned bodies t o file such cases in courts in\naccordance with the law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The National Women Commission may so delegate any of its functions,\nduties and powers to the Chairperson of the Commission, any of its members or any\nemployee of the Government of Nepal as to be exercised and complied with subject to\nthe specified conditions.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Other functions, duties and powers and other relevant matters of the\nNational Women Commission shall be as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 254", "title": "Powers to Establish Offices in Provinces", "content": "The National Women Rights Commission\nmay, as required, establish its offices in Provinces.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 255", "title": "National Dalit Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a National Dalit Commission of Nepal,\nconsisting of a Chairperson and four other members.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall, on the recommendation of the Constitutional Council,\nappoint the Chairperson and members of the National Dalit Commission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of office of the Chairperson and members of the National Dalit\nCommission shall be six years from the date of appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Notwithstanding anything contained in clause (3), the office of the\nChairperson or member of the National Dalit Commission shall fall vacant in any of\nthe following circumstances: -\n(a) In case he or she tenders resignation in writing to the President;\n(b) In case he or she attains the age of sixty-five years;\n(c) In case  a motion of impeachment is adopted against him or her\npursuant to Article 101;\n(d) In case  he or she is removed from office b y the President on\nrecommendation of the Constitutional Council on grounds of his or\nher inability to hold office and discharge the functions due to physical\nor mental illness;\n(e) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The Chairperson and members appointed pursuant to clause (2) shall not\nbe eligible for reappointment.\nProvided that a member may be appointed to the office of Chairperson, and\nwhen a member is so appointed as the Chairperson, his or her term of office shall be\nso computed as to include his or her term as the member.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "A person shall be eligible to be appointed as the Chairperson or a member\nof the National Dalit Commission in case  he or she possesses the following\nqualifications:\n(a) One who has rendered outstanding contribution to the field of rights\nand interests of the Dalit community or human rights and law , for at\nleast ten years;\n(b) In the case of the Chairperson, one who has acquired at least a\nbachelor's degree from a recognized university;\n(c) One who has attained the age of forty-five years;\n(d) One who is not a member of any political party at the time of\nappointment; and\n(e) One who bears high moral character.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The remuneration and conditions of service of the Chairperson and\nmembers of the National Dalit Commission shall be as provided for in  the federal\nlaw, and their remuneration and conditions of service shall not, so long as they hold\noffice, be altered to their disadvantage.\nProvided that this provision shall not apply in case s where a state of\nemergency is declared because of extreme economic disarrays.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "A person once appointed as the Chairperson or a member of the National\nDalit Commission shall not be eligible for appointment in other government service.\nProvided that nothing in this clause shall be deemed to be a bar to the\nappointment to any political position or to any position which has the responsibility of\nmaking investigations, inquiries or findings on any subject, or to any position which\nhas the responsibility of submitting advice, opinion or recommendation after carryi ng\nout a study or research on any subject.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 256", "title": "Functions, Duties and Powers of National Dalit Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The functions,\nduties and powers of the National Dalit Commission shall be as follows:-\n(a) To conduct study and research as to the overall situation of the Dalit\ncommunity, identify areas of necessary policy, legal and institutional\nreforms in that field, and make recommendations to the Government of\nNepal;\n(b) To formulate national policies and programs concerning the interests of the\nDalit for the upliftment and development of the Dalit, putting an end to\ncaste-based discrimination, oppression and discrimination, and submit\nsuch policies and programs to the Government of Nepal for their\nimplementation;\n(c) To monitor as to whether laws concerning the interests of the Dalit,\nincluding the special provisions made for the upliftment and interests of\nthe Dalit community have been effectively implemented, and in the event\nof absence of observance or implementation , to make suggestions to the\nGovernment of Nepal for the observance or implementation thereof;\n(d) To make suggestions to the Government of Nepal about the preparation of\nreports to be submitted by Nepal in accordance with the provisions\ncontained in the i nternational treaties or agreements concerning the rights\nof the Dalit community, to which Nepal is a party;\n(e) In order to have the Dalit community included in the mainstream of\nnational development and ensure proportional participation in all organs of\nthe State, to assess, monitor and evaluate the existing policies and\nprograms, and make recommendation to the Government of Nepal for their\neffective implementation;\n(f) In case it is necessary to file a case against any person or institution on\nmatters of being a victim of caste-based discrimination and untouchability\nor social ill-practices or infringement of or deprivation of enjoyment of the\nrights of the Dalit, to make recommendations to the concerned bodies to\nfile such case in courts in accordance with the law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The National Dalit Commission may so delegate any of its functions,\nduties and powers to the Chairperson of the Commission, any of its members or any\nemployee of the Government of Nepal as to be exercised and complied with subject to\nthe specified conditions.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Other functions, duties and powers and other relevant matters of the\nNational Dalit Commission shall be as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 257", "title": "Powers to Establish O ffices in Provinces", "content": "The National  Dalit Commission may, as\nrequired, establish its offices in Provinces.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 258", "title": "National Inclusion Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a National Inclusion Commission\nof Nepal, consisting of a Chairperson and four other members in the maximum.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall, on the recommendation of the Constitutional Council,\nappoint the Chairperson and members of the National Inclusion Commission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of office of the Chairperson and members of the National\nInclusion Commission shall be six years from the date of appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Notwithstanding anything contained in clause (3), the office of the\nChairperson or member of the National Inclusion Commission shall fall vacant in any\nof the following circumstances: -\n(a) In case he or she tenders resignation in writing to the President;\n(b) In case he or she attains the age of sixty-five years;\n(c) In case  a motion of impeachment is adopted against him or her\npursuant to Article 101;\n(d)  In case  he or she is removed from office by the President on\nrecommendation of the Constitutional Council on grounds of his or\nher inability to hold office and discharge the functions due to physical\nor mental illness;\n(e) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The Chairperson and members appointed pursuant to  clause (2) shall not\nbe eligible for reappointment.\nProvided that a member may be appointed to the office of Chairperson, and\nwhen a member is so appointed as the Chairperson, his or her term of office shall be\nso computed as to include his or her term as the member.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "A person shall be eligible to be appointed as the Chairperson or a member\nof the National Inclusion Commission in case  he or she possesses the following\nqualifications:-\n(a) One who has rendered outstanding contribution, for at least ten years,\nto the field of social inclusion, rights and interests or development of\npersons with disabilities, minority and marginalized communities and\nbackward areas and classes or human rights;\n(b) In the case of the Chairperson, one who has  acquired a bachelor's\ndegree from a recognized university;\n(c) One who has attained the age of forty-five years;\n(d) One who is not  a member of any political party at the time of\nappointment; and\n(e) One who bears high moral character.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The remuneration and conditions of service of the Chairperson and\nmembers of the National Inclusion Commission shall be as provided for in the federal\nlaw, and their remuneration and conditions of service shall not, so long as th ey hold\noffice, be altered to their disadvantage.\nProvided that this provision shall not apply in case s where a state of\nemergency is declared because of extreme economic disarrays.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "A person once appointed as the Chairperson or a member of the National\nInclusion Commission shall not be eligible for appointment in other government\nservice.\nProvided that nothing in this clause shall be deemed to be a bar to the\nappointment to any political position or to any position which has the responsibility of\nmaking investigations, inquiries or findings on any subject, or to any position which\nhas the responsibility of submitting advice, opinion or recommendation after carrying\nout a study or research on any subject.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 259", "title": "Functions, Duties and Powers of National Inclusion Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The functions,\nduties and powers of the National Inclusion Commission shall be as follows:-\n(a) To conduct study and research works for the protection of the rights\nand interests of the communities, including Khas Arya, Pichhada\nclass, persons with disabilities, senior citizens, labours, peasants,\nminorities and marginalize d community, backward class, people of\nKarnali and the indigent class;\n(b) To study the status of implementation of the policies and laws\nadopted by the Government of Nepal for the inclusion of the\ncommunity, class and region referred to  in sub-clause (a) and make\nsuggestions to the Government for reforms;\n(c) To study as to whether  or not there has been appropriate\nrepresentation of the community, class and region referred to in sub-\nclause (a) in the organs of the State  and make suggestions to the\nGovernment of Nepal to review the special provisions made for the\nrepresentation of such community, class and region;\n(d) To study as to whether  or not the protection, empowerment  and\ndevelopment of the community, class and region referred to  in sub-\nclause (a) has  been satisfactory and make recommendations to the\nGovernment of Nepal about policies to be pursued in the future;\n(e) To make suggestions to the Government of Nepal about policies and\nprograms to be pursued for the development and prosperity of the\nKarnali and backward regions;\n(f) To make recommendations for timely revisions of laws concerning\nminority and marginalized communities;\n(g) To monitor the status of implementation of rights and interests\nguaranteed for minority and marginalized communities and make\nrecommendations for revision upon necessary review on the basis of\nperiodic national census and human development index.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The National Inclusion Commission may so delegate any of its functions,\nduties and powers to the Chairperson of the Commission, any of its members or any\nemployee of the Government of Nepal as to be exercised and complied with subject to\nthe specified conditions.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Other func tions, duties and powers and other relevant matters of the\nNational Inclusion Commission shall be as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 260", "title": "Powers to Establish Offices in Provinces", "content": "The National Inclusion Commission may, as\nrequired, establish its offices in Provinces.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 261", "title": "Indigenous Nationalities Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be an Indigenous Nationalities\nCommission of Nepal, consisting of a Chairperson and four other members  in\nmaximum.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall, on the recommendation of  the Constitutional Council,\nappoint the Chairperson and members of the Indigenous Nationalities Commission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of office of the Chairperson and members of the Indigenous\nNationalities Commission shall be six years from the date of appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Other matters relating to t he qualification  for the Chairperson and\nmembers of the Indigenous Nationalities Commission, circumstances in which their\noffices fall vacant, their remuneration and conditions of service and the functions,\nduties and powers of this Commission shall be as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 262", "title": "Madhesi Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a Madhesi Commission of Nepal, consisting\nof a Chairperson and four other members in the maximum.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall, on the recommendation of the Constitutional Council,\nappoint the Chairperson and members of the Madhesi Commission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of office of the Chairperson and members of the Madhesi\nCommission shall be six years from the date of appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Other matters relating to the qualification for the Chairperson and\nmembers of the Madhesi Commission, circumstances in which their offices fall\nvacant, their remuneration and conditions of service and the functions, duties and\npowers of this Commission shall be as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 263", "title": "Tharu Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a Tharu Commission of Nepal, consisting of a\nChairperson and four other members in the maximum.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall, on the recommendation of the Constitutional Council,\nappoint the Chairperson and members of the Tharu Commission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of office of  the Chairperson and members of the Tharu\nCommission shall be six years from the date of appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Other matters relating to the qualification for the Chairperson and\nmembers of the Tharu Commission, circumstances in which their offices fall vacant ,\ntheir remuneration and conditions of service and the functions, duties and powers of\nthis Commission shall be as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 264", "title": "Muslim Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a Muslim Commission of Nepal, consisting of\na Chairperson and four other members in the maximum.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall, on the recommendation of the Constitutional Council,\nappoint the Chairperson and members of the Muslim Commission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of office of the Chairperson and members of the Muslim\nCommission shall be six years from the date of appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Other matters relating to the qualification for the Chairperson and\nmembers of the Muslim Commission, circumstances in which their offices fall vacant,\ntheir remuneration and conditions of service and th e functions, duties and powers of\nthis Commission shall be as provided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 265", "title": "Review of Commissions", "content": "The Federal Parliament shall, after ten years of the\ncommencement of this Constitution, review the Commissions  constituted under this\nPart.", "children": []}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-28", "title": "Provisions Relating to National Security", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 266", "title": "National Security Council", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a National Security Council for making\nrecommendation to the Government of Nepal, Council of Ministers for the\nformulation of a policy on overall national interest, security and defence of Nepal, and\nfor the mobilization or control of the Nepal Army, which shall consist of the following\nas the Chairperson and members:-\n(a) The Prime Minister       - Chairperson\n(b) Minister for Defence, Government of Nepal        - Member\n(c) Minister for Home, Government of Nepal         - Member\n(d) Minister for Foreign Affairs, Government of Nepal     -Member\n(e) Minister for Finance, Government of Nepal          - Member\n(f) Chief Secretary to Government of Nepal          - Member\n(g) Chief of the Army Staff, Nepal Army          - Member", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The secretary at the Ministry of Defence shall act as the member secretary\nto the National Security Council.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The National Security Council shall submit its annual report to the\nPresident, and the President shall cause the report  to be laid through the Prime\nMinister before the Federal Parliament.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Other matters relating to the National Security Council shall be as provided\nfor in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 267", "title": "Provisions relating to Nepal Army", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be an organization of the Nepal\nArmy, which shall  be inclusive and  committed to this Constitution , in order to\nsafeguard of independence, sovereignty, territorial integrity and freedom and national\nunity of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall be the Supreme Commander of the Nepal Army.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Entry of women, Dalit, indigenous people, indigenous nationalities\n(Aadibasi Janajati), Khas Arya, Madhesi, Tharu, Pichhada class and backward region\ncitizens into the Nepal Army shall, on the basis of principles of equality and inclusion,\nbe ensured by the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The Government of Nepal may also mobilize the Nepal Army in other\nworks including development, construction and disaster management works, as\nprovided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The President shall, on recommendation of the Council of Ministers,\nappoint the Chief of the Army Staff and remove him or her from office.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The President shall, in accordance with a decision of the Government of\nNepal, Council of Ministers on recommendation of the National Security Council ,\ndeclare the mobilization of the Nepal Army in cases where a grave emergency arises\nin regard to the sovereignty or territorial integrity of Nepal or the security of any part\nthereof, by war, external aggression, armed rebellion or extreme economic disarray s.\nA declaration of the mobilization of the Nepal Army shall be required to be approved\nby the House of Representatives within one month after the date of such declaration.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "Other matters pertaining to the Nepal Army shall be in accordance with\nlaw.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 268", "title": "Provisions Relating to Nepal Police, Armed Police Force, Nepal and  National Investigation Department", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Federation shall have Nepal Police, Armed Police\nForce, Nepal and National Investigation Department.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Each Province shall have a Provincial Police Organization.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Matters relating to the operation, supervision and coordination of functions\nto be discharged by the Nepal Police and the Provincial police shall be as provided for\nin federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Other matters relating to the Nepal Police, Armed Po lice Force, Nepal and\nNational Investigation Department shall be as provided for in the by federal law.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-29", "title": "Provisions Relating to Political Parties", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 269", "title": "Formation, Registration and Operation of Political Parties", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Persons who are\ncommitted to common political ideology, philosophy and program may, subject to\nlaws made pursuant to  sub-clause (c) of clause (2) of Article 17 , form and operate\npolitical parties, and generate, or cause to be generated, publicity in order to secure\nsupport and cooperation from  public-in-general for their ideolog y, philosophy and\nprogram or carry out other necessary activity for this purpose.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A political party formed in a ccordance with clause (1)  shall be required to\nbe registered the party with the Election Commission upon fulfilment of the\nprocedures as laid down by law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A petition to be filed for the purpose of registration of a party pursuant to\nclause (2) shall be accompanied by the constitution and manifesto of the concer ned\npolitical party and such other documents as required by federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "For a petition to be filed for the registration of a party pursuant to clause", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": ", the political party shall fulfil the following conditions:-\n(a) Its constitution and rules shall be required  be democratic;\n(b) Its constitution shall provide for election of each of the office-\nbearers of the party at the Federal and Provincial levels at least once\nin every five years;\nProvided that nothing shall bar the making of provision in the\nconstitution of a political party to hold such election within six\nmonths in the event of failure to hold election of its office -bearers\nwithin five years because of occurrence a special circumstance;\n(c) There shall be a  provision of such inclusive representation in  its\nexecutive committees at various levels as may be reflecting the\ndiversity of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In case the name, objective, insignia or flag of a political party is of such a\nnature as to jeopardize the religious and communal unity of the country or to fragment\nthe country, that party shall not be registered.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 270", "title": "Restrictions on Imposition of  Prohibition on Political Parties", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Any law,\narrangement or decision so made as to impose any restriction on the formation and\noperation of a polit ical party and on the generation of publicity in order to secure\nsupport and cooperation from  public-in-general for the ideology, philosophy and\nprogram of the party pursuant to Article 269 shall be deemed to be inconsistent with\nthis Constitution and shall, ipso facto, be void.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Any law, arrangement or decision so made as to allow for participation or\ninvolvement of only a single political party or persons having similar political\nideology, philosophy or program in the elections or in the political system of, or in the\nconduct of governance of the State shall be deemed to be inconsistent with this\nConstitution and shall, ipso facto, be void.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 271", "title": "Registration required for Securing Recognition for the Purpose of Contesting Elections as Political Party", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every political party  that is registered pursuant to\nArticle 269 and  intends to secure recognition from the Election Commission for the\npurposes of elections shall be registered with the Election Commission in fulfilment of\nthe procedures set forth in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The political party shall be required to  submit a yearly audit report in\naddition to the matters set forth in clause (3) of Article 269 a petition to be filed for the\npurpose of clause (1) and also fulfil the terms set forth in clause (4) of that Article.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 272", "title": "Other Provisions relating to Political Parties", "content": "Provisions relating to  the formation,\nregistration, operation and facilities of political parties and other matter s pertaining\nthereto shall be as provided for in the federal law.", "children": []}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-30", "title": "Emergency Powers", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 273", "title": "Emergency Provisions", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "In case a grave emergency arises in sovereignty , territorial\nintegrity or the security of any part of Nepal by the reason of war, external aggression,\narmed rebellion, extreme economic disarray s, natural disaster or epidemic ; the\nPresident may, by Proclamation, declare or order a state of emergency in respect of the\nwhole of Nepal or of any particular part thereof.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Notwithstanding anything contained in clause (1), in case  there arises a\ngrave emergency in a Province by the reason of a natural disaster or epidemic, the\nconcerned Provincial Government may request the Government of Nepal to declare a\nProclamation or order a state of emergency in respect of the whole of the Province or\nof any specified part thereof, in accordance with this Article.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Proclamation or order issued pursuant to clause (1) shall be laid before\nboth Houses of the Federal Parliament for approval within one month from the date of\nissuance of such proclamation or order.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "In case the Proclamation or order laid for approval pursuant to clause (3) is\napproved by at least a two-thirds majority of the total number of the then members of\nboth Houses of the  Federal Parliament, the Proclamation or order shall continue in\nforce for a period of three months from the date of its issuance.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In case the Proclamation or an order laid for approval pursuant to clause (3)\nis not approve d pursuant to clause (4), the Proclamation or order shall ipso facto be\ninoperative.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "Notwithstanding anything contained elsewhere in this Article, prior to\nexpiration of the period referred to in clause (4), a motion to extend the period of the\nProclamation or order of state of emergency as referred to  in clause (1)  for another\nperiod not exceeding three months may be submitted to the Federal Parliament.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "In case a motion referred to in  clause (6) is adopted by at least two -thirds\nmajority of the total number of the then members of both Houses of the Federal\nParliament, the Proclamation or order shall continue in force for the period  referred to\nin that motion.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "In the event of dissolution of the House of Representatives, the powers\nexercisable by the Federal Parliament pursuant to clauses (3), (4), (6) and (7) shall be\nexercised by the National Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "The President may, a fter the issuance of a Proclamation or order of a state\nof emergency pursuant to clause (1), issue such orders as are necessary to meet the\nexigencies. Orders so issued shall be operative with the same force and effect as  law\nso long as the state of emergency is in operation.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": "At the time of issuance of the  Proclamation or order  of a state of\nemergency pursuant to  clause (1), the fundame ntal rights as provided for in Part -3\nmay be suspended until the proclamation or order is in operation.\nProvided that Article 16, sub -clauses (c) and (d) of clause (2) of Article 17,\nArticle 18, clause (2) of Article 19 , Articles 20, 21, 22 and  24, clause (1) of Article\n26, Articles 29, 30, 31, 32, 35, clauses (1) and (2 ) of Article 36, Articles 38, 39,\nclauses (2) and (3) of Article 40, Articles 41, 42, 43, 45, and the right to constitutional\nremedy in relation to such  Articles pursuant to Article 46  and the right to  seek the\nremedy of habeas corpus shall not be suspended.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(11)", "title": null, "content": "In case any Article of this Constitution is suspended pursuant to clause", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": ", no petition may lie in any court for the enforcement of the fun damental right\nconferred by that Article nor may a question be raised in any Court in that respect.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(12)", "title": null, "content": "In case, during the continuance of a Proclamation or order pursuant to this\nArticle, any damage is caused to a  person from any ac t carried out by any official in\nbad faith, the victim may, within three months fro m the date of termination of that\nProclamation or order, file a petition for c ompensation for such damage. In case such\npetition is made, the court may order for compensation by, and punish, the perpetrator\nas provided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(13)", "title": null, "content": "The President may, at any time, withdraw a  Proclamation or order of a\nstate of emergency issuance pursuant to this Article.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-31", "title": "Amendment to Constitution", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 274", "title": "Amendment to Constitution", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No amendment shall be made to this Constitution in\nmanner to be prejudicial to sovereignty, territorial integrity, independence of Nepal\nand sovereignty vested in the people.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Subject to clause (1) and other Articles of th is Constitution, a Bill to\namend to or repeal any Article of this Constitution may be introduced in either House\nof the Federal Parliament.\nProvided that clause (1) shall not be amended.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A Bill introduced pursuant to clause ( 2) shall be publicly published for\ninformation to public-in-general within thirty days of its introduction in the concerned\nHouse.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "In case a Bill introduced pursuant to clause ( 2) is related with the alteration\nin the borders of any Province or matters set forth in Schedule -6, the Speaker or the\nChairperson of the concerned House shall send that Bill  to the Provincial Assembly\nfor its consent, within thirty days after its introduction in the Federal Parliament.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The concerned Provincial Assembly shall, by a majority of the total\nnumber of its the then members, approve or reject the Bill presented for its consent\npursuant to clause (4 ) and give information thereof to the Federal Parliament within\nthree months.\nProvided that in case any Provincial Assembly is not in existence , such  Bill\nshall be either approved or rejected within three months after the date of holding of the\nfirst meeting following the formation of that Provincial Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "In the event of failure to give information of approval or rejection of such\nBill within the period set forth in clause (5), nothing shall prevent the House of the\nFederal Parliament in which the Bill was originated from proceeding with the Bill.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "In case a majority of the Provincial Assemblies gives a notice of rejection\nof such  Bill to the concerned House of the Federal Parliament within the period\nreferred to in clause (5), the Bill shall be inoperative.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "A Bill which does not require th e consent of the Provincial Assembly or a\nBill accepted by a majority of  the Provincial Assemblies pursuant to  clause (5) shall\nbe adopted by at least two-thirds majority of the total number of the then members of\nboth Houses of the Federal Parliament.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "A Bill adopted pursuant to clause (8) shall be submitted to the President for\nauthentication.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": "The President shall authenticate the Bill submitted pursuant to clause (9)\nwithin fifteen days from the date of its receipt and the Constitution shall get amended\nfrom the date of authentication.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-32", "title": "Miscellaneous", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 275", "title": "Provisions relating to Referendum", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "In case  a decision is made by a two -thirds\nmajority of the total number of the then members of the Federal  Parliament that it is\nnecessary to hold a referendum with respect to any matter of national importance, a\ndecision on that matter may be taken by way of referendum.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Matters relating to referendum and other relevant matters shall be as\nprovided for in the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 276", "title": "Pardons", "content": "The President may, in accordance with law, grant pardons, suspend,\ncommute or re mit any sentence passed by any C ourt, judicial or quasi -judicial\ninstitution or administrative authority or institution.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 277", "title": "Titles, Honours and  Decorations", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The President shall confer titles, hono urs and\ndecorations to be conferred on behalf of the State.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No citizen of Nepal may, without the approval of the Government of\nNepal, accept any title, honour or decoration from any foreign government.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 278", "title": "Power to Conclude Treaty", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Federation shall have the power to conclude\ntreaties or agreements.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In concluding a treaty or agreement on a matter falling within the list of\npowers of Province, the Government of Nepal  shall be required to  consult the\nconcerned Province.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A Provincial Council of Ministers may, with the consent of the\nGovernment of Nepal, enter into contractual agreements on financial and industrial\nmatters.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 279", "title": "Ratification of, Accession to, Acceptance or Approval of, Treaties or Agreements", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The ratification of, accession to, acceptance or approval of, treaties or agreements to\nwhich Nepal or the Government of Nepal is to become a party shall be as provided for\nin the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Any law to be made pursuant to clause (1) shall, inter alia, require that the\nratification of, accession to, acceptance or approval of, treaties or agreements on the\nfollowing subjects shall be made by a majority of two-thirds of the total number of the\nthen members of both Houses of the Federal Parliament:-\n(a) Peace and friendship;\n(b) Defence and strategic alliance;\n(c) Boundaries of the Nepal; and\n(d) Natural resources, and the distribution of their uses.\nProvided that, out of the treaties or agreements referred to in  sub-clauses (a)\nand (d), in case any treaty or agreement is of an ordinary nature, which does not affect\nthe nation extensively, seriously or in the long term, the ratification of, accession to,\nacceptance or approval of, such treaty or agre ement may be made by a simple\nmajority of the members present in a meeting of the House of Representatives.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "After the commencement of this Constitution, unless a treaty or agreement\nis ratified, acceded to, accepted or approved pursuant to  this Article, such  treaty or\nagreement shall not be binding to the Government of Nepal or Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Notwithstanding anything contained in clauses  (1) and (2), no treaty or\nagreement that is detrimental to the territorial integrity of Nepal may be concluded.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 280", "title": "Special provision relating to Discharge of Functions of President", "content": "In case the offices\nof both  the President and the Vice-President fall vacant in accordance with this\nConstitution, the Speaker of the House of Representatives shall discharge the\nfunctions required to be performed by the President under this Constitution until\nelection to the President or Vice-President is held and he or she assumes office.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 281", "title": "Appraisal and Review of Special Rights", "content": "The Government of Nepal shall make\nappraisal and review of the implementation of special rights of the women and Dalit\ncommunity and impacts thereof, on the basis of human development index,\nconcurrently with a national census to be held in every ten years.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 282", "title": "Ambassadors and Special Emissaries", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The President may, on the basis of the\nprinciple of inclusion, appoint Nepali ambassadors, and special emissaries for any\nspecific purposes.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The President shall receive letters of credentials from for eign ambassadors\nand diplomatic representatives.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 283", "title": "Appointments to be made  in accordance with Inclusive Principle", "content": "Appointments to\noffices of Constitutional Organs and B odies shall be made in accordance with the\ninclusive principle.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 284", "title": "Provisions relating to Constitutional Council", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "There shall be a Constitutional\nCouncil for making recommendations for appointment of the Chief Justice and Chiefs\nand officials of the Constitutional Bodies in accordance with this Constitution, which\nshall consist of the following as the Chairperson and members:-\n(a) The Prime Minister - Chairperson\n(b) The Chief Justice - Member\n(c) The Speaker of the House of Representatives  - Member\n(d) The Chairperson of the National Assembly  - Member\n(e) Leader of Opposition Party in the House of Representatives  - Member\n(f) Deputy Speaker of the House of Representatives    - Member", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "While making a recommendation for appointment to the office of the Chief\nJustice, the Constitutional Council shall include th e Minister for Law and Justice of\nthe Government of Nepal, as its member.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Constitutional Council shall make a recommendation for appointment\nunder this Constitution before one month of the vacation of the of fice of the Chief\nJustice or a chief or official of a Constitutional Body.\nProvided that in case such office falls vacant because of death or resignation, it\nmay so make recommendation for appointment that the office is fulfilled within one\nmonth after the date of vacancy.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "Other functions, duties and powers of the Constitutional Council and rules\nof procedures on the appointment of the Chief Justice or chiefs or officials of\nConstitutional Bodies shall be as provided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The Chief Secretary to the Government of Nepal shall act as the secretary\nto the Constitutional Council.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 285", "title": "Constitution of Government Service", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Government of Nepal may, in order to\nrun the administration of the country, constitute the federal civil service and such other\nfederal government s ervices as may be required. The constitution, operation and\nconditions of service of such services shall be as provided for in a Federal Act.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Positions in the federal civil service as well as all federal government\nservices shall be fulfilled through competitive examinations, on the basis of open and\nproportional inclusive principle.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Provincial Council of Ministers, Rural Municipal Executive  and\nMunicipal Executive may by law constitute and operate  various government ser vices\nas required for the operation of their administration.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 286", "title": "Election Constituency Delimitation Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Government of Nepal may\nconstitute an Election Constituency Delimitation Commission, to determine election\nconstituencies for the purpose of election to the members of the Federal Parliament\nand members of the Provincial Assemblies in accordance with this Constitution, which\nshall consist of the following as the Chairperson and members:-\n(a) A retired Justice of Supreme Court                        -Chairperson\n(b) One Geographer      -Member\n(c) One Sociologist or Demographer                                      -Member\n(d) One Administration Expert or Jurist                        -Member\n(e) Gazetted spec ial class officer of the\nGovernment of Nepal.\n-Member-secretary", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The term of office of the Election Constituency Delimitation Co mmission\nshall be as prescribed at the time of its constitution.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A person shall be eligible to be appointed as the C hairperson or a member\nof the Election Constituency Delimitation Commission in case he or she possesses the\nfollowing qualifications:-\n(a) One who has acquired  at least bachelor’s degree in related subject\nfrom a recognized university;\n(b) One who has attained the age of forty-five years; and\n(c) One who bears high moral character.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The office of the C hairperson or a member of the Election Constituency\nDelimitation Commission shall fall vacant in any of the following circumstances: -\n(a) In case he or she tenders resignation in writing;\n(b) In case he or she is removed by the Government of Nepal , Council of\nMinisters;\n(c) In case he or she dies.\n(5) While determining election constituencies pursuant to this Article,\nthe Election Constituency Delimitation Commission shall, subject to sub -clause\n(a) of clause (1) of Article 84, determine the constituencies in a Province in\naccordance with the federal la w, having regard to the population as the main\nbasis and geography as the second basis for representation, and there shall be at\nleast one election constituency in each district within the Province .", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "While delimitating election constituencies pursuant t o clause (5),\nattention shall be required to be given , inter alia , the population and\ngeographical convenience , density of population, geographical specificity,\nadministrative and transportation convenience, community and cultural aspects of the\nconstituencies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "No question may be raised in any court on any matter of the determination,\nor review, of election constituencies made by the Election Constituency Delimitation\nCommission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "The Election Constituency Delimitation Commission shall subm it a report\non the works it has performed to the Government of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "The Government of Nepal, Council of Ministers, shall lay the report\nreceived pursuant to clause (8 ) before the Federal Parliament and shall also send it to\nthe Election Commission for implementation.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": "The Election Constituency Delimitation Commission shall determine its\nrules of procedures itself.\n Amended by the First Amendment.\n Inserted by the First Amendment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(11)", "title": null, "content": "The remuneration and facilities  of the C hairperson and the members of\nthe Election Constituency Delimitation Commission shall be similar to those of the\nChief Election Commissioner and the Election Commissioners  of the Election\nCommission, respectively.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(12)", "title": null, "content": "The election constituencies delimited pursuant to  clause (5) shall be\nreviewed in every twenty years.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(13)", "title": null, "content": "The Government of Nepal shall provide such employees as may be\nrequired for the Election Constituency Delimitation Commission.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 287", "title": "Language Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Government of Nepal shall, within one year of the\ncommencement of this Constitution, constitute a Language Commis sion comprising\nrepresentation of Provinces.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Language Commission shall consist of one Chairperson and a required\nnumber of members.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The term of office of the Chairperson and members of the  Language\nCommission shall be six years from the dat e of their appointment . They may not be\nreappointed.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "A person shall be eligible to be appointed as the Chairperson or a member\nof the Language Commission in case  he or she possesses the following\nqualifications:-\n(a) One who has acquired  Master’s degree in related subjec t from a\nrecognized university;\n(b) One who has gained at least twenty years of experience in the fields\nof study, teaching and research on various languages of Nepal;\n(c) One who has completed the age of forty-five years; and\n(d) One who bears high moral character.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The office of the Chairperson or a member of the Language Commission\nshall fall vacant in any of the following circumstances:-\n(a) In case he or she tenders resignation in writing;\n(b) In case he or she is removed by  the Government of Nepal , Council\nof Ministers;\n(c) In case he completes the age of sixty-five years;\n(d) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The functions, duties and powers of the Language Commission shall\nbe as follows:-\n(a) To determine the criteria to be fulfilled for the recognition as the\nofficial language and make recommendations on languages to the\nGovernment of Nepal;\n(b) To make recommendations to the Government of Nepal, on the\nmeasures to be adopted for the protection,  promotion and\ndevelopment of languages;\n(c) To measure the levels of development of mother tongues and make\nsuggestions to the Government of Nepal, on the potentiality of their\nuse in education;\n(d) To conduct study and research on languages and monitor them.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The Language Commission shall complete its task s referred to in  sub-\nclause (a) of clause (6) within five years after the date of its constitution.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "The Government of Ne pal may, in coordination with the Provincial\nGovernment, establish a branch of the Language Commission in the Province.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "The other functions, duties, powers and rules of procedures of the\nLanguage Commission shall be as provided for in federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 288", "title": "Capital", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The capital of Nepal shall be located in Kathmandu.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The capital of a Province in accordance with  this Constitution shall be as\ndecided by a two-thirds majority of the number of the then members of the concerned\nProvincial Assembly.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The business of a Province shall be conducted through the place as\nspecified by the Government of Nepal until a decision is made pursuant to clause (2).", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 289", "title": "Special Provision relating to Citizenship of Officials", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "In order for a person to be\nelected, nominated  or appointed to the office of President, Vice-President, Prime\nMinister, Chief Justice , of  the Speaker of House of Representatives, Chief of\nProvince, Chief Minister , Speaker of a Provincial Assembly and Chief of a security\nbody, a person shall have to obtain the citizenship of Nepal by descent.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A person who has obtained the citizenship of Nepal by descent, a person\nwho has obtained the naturalized citizenship of Nepal or a person who has obtained\nthe citizenship of Nepal by birth shall also be eligible for the office of a constitutional\nbody other than those referred to in clause (1).\nProvided that a person shall have resided in Nepal for at least ten years in the\ncase of a person who has obtained the naturalized citizenship of Nepal, and for at least\nfive years in the case of a person who has obtained the citizenship of Nepal by birth or\nwho has obtained the naturalized citizenship of Nepal pursuant to clause (6) of Article\n11.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 290", "title": "Provisions relating to Guthi (trusts)", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Federal Parliament shall make necessary\nlaws in relation to the rights of the trust and the farmers  enjoying possessory rights\nover trust land in a manner not to be prejudicial to the basic norms of the trusts.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Other matters relating to trusts shall be as provided by the federal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 291", "title": "Not to be Eligible for Appointment", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Notwithstanding anything contained\nelsewhere in this Constitution, a citizen of Nepal who has obtained a foreign\npermanent residence permit shall not be eligible for election, nomination or\nappointment to an office to be elected, nominated or appointed in accordance with this\nConstitution.\nProvided that nothing shall prevent electing, nominating or appointing a\nperson who has renounced such foreign permanent residence permit to such office\nafter the expiry of a period of at least three months.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Other matters relating to the citizens of Nepal who have obtained foreign\npermanent residence permits as referred to  in clause (1) shall be as provided for in\nfederal law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 292", "title": "Provisions relating to Parliamentary Hearings", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Parliamentary hearings shall be\nconducted as to appointments to the offices of the Chief Justice and Justices of the\nSupreme Court, members of the Judicial Council, chiefs and members of\nConstitutional Bodies, who are appointed on the recommendation  of the\nConstitutional Council under this Constitution, and to the offices of ambas sadors, as\nprovided for in the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "For the purposes of clause  (1), there shall be constituted a fifteen-member\njoint committee consisting of members of both Houses of the Federal Parliament, in\naccordance with the federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "No member of the joint committee referred to in  clause (2) shall practice\nlaw in the Supreme Court during that term of the Federal Parliament.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 293", "title": "Monitoring of Functioning of Constitutional Bodies", "content": "The chiefs and officials of the\nConstitutional Bodies shall be accountable and responsible to the Federal Parliament.\nThe committees of the House of Representatives may monitor an d evaluate the\nfunctioning, including reports, of the Constitutional Bodies, other than the National\nHuman Rights Commission, and give necessary direction or advice.", "children": []}, {"tier": 2, "nodeType": "article", "identifier": "Article 294", "title": "Annual Reports of Constitutional Bodies", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Every Constitut ional Body in\naccordance with this Constitution shall submit an annual report of its functioning to\nthe President, and the President shall cause that report to be laid through the Prime\nMinister before the Federal Parliament.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The matters to be set out in the annual report referred to in clause (1) shall\nbe as provided for in federal law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Notwithstanding anything contained in clause (1), a Constitutional Body\nmay prepare a separate report in relation to the functioning of each Province and\nsubmit it to the Chief of Province.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-33", "title": "Transitional Provisions", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 295", "title": "Constitution of Federal Commission", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Government of Nepal may constitute a\nFederal Commission for making suggestions on matters relating to the boundaries of\nProvinces.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The names of the Provinces referred to in clause (3) of Article 56 shall be\nset by a two thirds majority of the total number of member s of the concerned\nProvincial Assemblies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Government of Nepal shall constitute a Commission for the\ndetermination of the n umber and boundar ies of Rural Municipalities, Municipalities\nand Special, Protected or Autonomous Regions to be formed pursuant to  clauses (4)\nand (5) of Article 56. T he Commission shall determine the number and boundaries of\nthe Rural Municipalities , Municipalities and Special, Protected or Autonomous\nRegions in accordance with the criteria set by the Government of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The Commission referred to in  clause (3) shall be constituted within six\nmonths of the date of commencement of this Constitution. The term of suc h\nCommission shall be one year.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 296", "title": "Constituent Assembly to be converted into Legislature -Parliament", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The\nConstituent Assembly existing at the time of commencement of this Constitution shall\nipso facto  be converted into the Legislature -Parliament after the commencement of\nthis Constitution, and the term of that Legislature-Parliament shall  exist until 21\nJanuary 2018  (7 Magha 2074).\nProvided that in case an election is to be held to the House of Repr esentatives\nset forth in  this Constitution prior to the expiration of that term, the Legislature -\nParliament shall continue to exist until the day before the day specified for the filing\nof nominations of candidates for that election.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Bills under consideration of the Legislature -Parliament at the time of\ncommencement of this Constitution shall ipso facto be transferred to the Legislature -\nParliament set forth in clause (1).", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Legislature -Parliament set forth in clause (1) shall perform the\nbusiness required to be performed by the Federal Parliament in accordance with this\nConstitution until election to the House of Representatives is held in accordance with\nthis Constitution.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The legislative power of the Provincial Assembly with respect of matters\nset forth in Schedule -6 shall, upon the commencement of this Constitution, be vested\nin the Legislature -Parliament set forth in clause (1) until the Provincial Assembly is\nconstituted. Any law so made shall be inoperative in relati on to that Province after\none year of the date of constitution of the Provincial Assembly set forth in this\nConstitution.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The Legislature -Parliament Secretariat , its Secretary General, Secretary\nand employees  existing at the time of commencement of t his Constitution shall,\nsubject to the conditions of service in force at the time of their appointment, exist in\nthe Federal Parliament Secretariat set forth in this Constitution.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "Where the Legislature -Parliament is in recess at the time of\ncommencement of this Constitution, the President shall summon its session within\nseven days after the date of commencement of this Constitution.  The President shall,\nthereafter, summon a session of the Legislature-Parliament from time to time.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 297", "title": "Provisions relating to President and Vice -President", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The President and the Vice -\nPresident existing at the time of commencement of this Constitution shall continue to\nhold their respective offices until other President and Vice -President are elected\npursuant to this Article.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Legislature-Parliament set forth in clause (1) of Article 296 shall, on\nthe basis of political understanding, elect the President and the Vice -President, within\none month after the date of the commencement of this Constitution where t he\nLegislature-Parliament is not in recess at the time of commencement of this\nConstitution and after the date on which the session is summoned pursuant to clause", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "of Article 296 where the Legislature-Parliament is in recess.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In the event of failu re to have an understanding pursuant to clause (2), the\nPresident and the Vice -President shall be elected by a majority of all the then\nmembers of the Legislature-Parliament.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "In case the office of the President or Vice -President elected pursuant to\nclause (2) or (3) falls vacant for any reason, the President or Vice -President shall be\nelected by the Legislature -Parliament pursuant to  this Article until the Federal\nParliament is constituted.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The term of office of the President or Vice -President elected pursuant to\nthis Article shall continue to exist until another President or Vice -President elected by\nan electoral college set forth in Article 62 assumes office.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The office of the President or Vice -President elected pursuant to  this\nArticle shall fall vacant in any of the following circumstances: -\n(a) In case  the President tenders r esignation in writing to  the Vice -\nPresident and the Vice-President, to the President;\n(b) In case  a motion of impeachment against him or  her is adopted\npursuant to clause (7);\n(c) In case  another President or Vice -President elected by an electoral\ncollege set forth in Article 62 assumes office;\n(d) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "At least one fourth of the total number of the then members of the\nLegislature-Parliament referred to in clause (1) of Article 296 may move a motion of\nimpeachment against the President or Vice -President elected pursuant to this Article\non the ground of serious violation of this Constitution and law. In case the motion is\nadopted by at least two-thirds majority of the total number of the then members of the\nLegislature-Parliament, he or she shall be relieved of his or her office", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 298", "title": "Provisions relating to Constitution of Council of Ministers", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The  Council of\nMinisters existing at the time of commencement of this Constitution shall continue to\nexist until the Council of Ministers referred to clause (2) is constituted.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Prime Minister shall, on the basis of political understanding, be\nelected within seven days after the date of the commencement of this Constitution\nwhere the Legislature-Parliament is not in recess at the time of commencement of this\nConstitution, and after the date on which the session of the Legislature -Parliament\nsummoned pursuant to  clause (6) of Artic le 296 commences where the Legi slature-\nParliament is in recess, and a Council of Ministers shall be constituted under his or\nher chairpersonship.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In the event of failure to have an understanding pursuant to clause (2), the\nPrime Minister shall be elected by a majority of all the then members of the\nLegislature-Parliament.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The a composition and allocation of portfolios of the Council of Ministers\nto be constituted pursuant to this Article shall be made through mutual understanding.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The C ouncil of Ministers to be constituted pursuant to  this Article shall\nconsist of a Deputy Prime Minister and other Ministers, as required.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The Prime Minister appointed pursuant to this Article shall, in appointing\nMinisters pursuant to clause (5), appoint Ministers from amongst the members of the\nLegislature-Parliament, on the recommendation of the concerned party.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The Prime Minister and other Ministers appointed pursuant to this Article\nshall be collectively responsible to the Legislature -Parliament, and the Ministers shall\nbe individually responsible to the Prime Minister and the Legislature - Parliament for\nthe works of their respective Ministries.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "The office of the Prime Minister appointed pursuant to  this Article shall\nfall vacant in any of the following circumstances:-\n(a)  In case he or she tenders resignation in writing to the President;\n(b) In case a vote of no confidence is adopted against him or her pursuant\nto clause (14) or a vote of confidence is not adopted;\n(c) In case he or she ceases to be a member of the Legislature-Parliament;\n(d) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "The office of the Deputy Prime Minister, Minister, Minister of State and\nAssistance Minister appointed pursuant to this Article shall fall vacant in a ny of the\nfollowing circumstances:-\n(a) In case he or she tenders resignation in writing to the Prime Minister;\n(b) In case the Prime Minister is removed from office pursuant to clause", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": ";\n(c) In case he or she is removed from office by the Prime Minister on the\nrecommendation or on advice of the concerned party;\n(d) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(10)", "title": null, "content": "Even though the office of the Prime Minister falls vacant pursuant to\nclause (8), the same Council of Ministers shall continue to act until another Council of\nMinisters is constituted.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(11)", "title": null, "content": "In case  the Prime Minister appointed pursuant to  this Article dies, the\nDeputy Prime Minister or senior-most Minister shall act a s the Prime Minister until\nanother Prime Minister is appointed.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(12)", "title": null, "content": "The Prime Minister appointed pursuant to this Article may, whenever he\nor she considers necessary or appropriate to clarify that he or she has confidence from\nthe Legislature-Parliament, table a motion to that effect in the Legislature-Parliament\nfor the vote of confidence.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(13)", "title": null, "content": "At least o ne-fourth of the total number of the then members of the\nLegislature-Parliament may table in writing a motion of no confidence  against the\nPrime Minister appointed pursuant to this Article.\nProvided that a motion of no confidence shall not be tabled more than once in\nsix moths' period against the same Prime Minister appointed pursuant to this Article.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(14)", "title": null, "content": "A motion tabled pursuant to  clause (12) or (13) shall be decided  by a\nmajority of the total number of the then members of the Legislature Parliament.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(15)", "title": null, "content": "The Government of Nepal shall , after the commencement of this\nConstitution, exercise the  executive powers of a Province until the Counc il of\nMinisters of the Province set forth in this Constitution is constituted.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 299", "title": "Provisions relating to Speaker and Deputy Speaker", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Speaker and Deputy\nSpeaker existing at the time of commencement of this Constitution shall continue to\nhold their re spective offices until another Speaker and Deputy Speaker is elected in\naccordance with this Constitution.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The members of the Legislature -Parliament shall, on the basis of political\nunderstanding, elect one Speaker and Deputy Speaker from among themselves within\ntwenty days after the date of the commencement of this Constitution where the\nLegislature-Parliament is not in recess at the time of commencement of this\nConstitution, and after the date on which the session of the Legislature -Parliament is\nsummoned pursuant to clause (6) of Article 29 6 where the Legislature -Parliament is\nin recess.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In the event of failure to have an understanding pursuant to  clause (2), a\nmember of the Legislature -Parliament who commands a majority of all the then\nmembers of the Leg islature-Parliament shall be deemed to be elected as the Speaker\nor Deputy Speaker.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "In holding electing pursuant to clause (2) or (3), the Speaker and Deputy\nSpeaker shall be members representing different political parties in the Legislature -\nParliament.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In discharging his or her functions in accordance with this Constitution, the\nSpeaker and Deputy Speaker  shall so discharge functions in the capacity of a neutral\nperson without standing for or against any political party whatsoever.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The office of the  Speaker and Deputy Speaker  shall fall vacant in any of\nthe following circumstances:-\n(a) In case he or she resigns in writing;\n(b) In case he or she ceases to be a member of the Legislature-Parliament;\n(c) In case a motion is adopted by a majority of at least two-thirds of the\ntotal number of the members of the Legislature-Parliament to the\neffect that his or her conduct is not compatible with his or her office;\n(d) In case he or she dies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The Deputy Speaker  or another member shall preside over a meeting at\nwhich deliberations are to be held on a motion that the conduct of the  Speaker of the\nLegislature-Parliament is not co mpatible with his or her office, and t he Speaker may\ntake part and vote in the deliberations on such motion.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "Other procedures on the election to the Speaker and Deputy Speaker  and\nprocedures on the moving and adoption of a motion that the  Speaker or Deputy\nSpeaker has committed conduct not compatible with his or her office shall be as\nprovided by the then prevailing rules of the Legislature-Parliament.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 300", "title": "Provisions relating to Judiciary", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Supreme Court, Constituent Assembly Court,\nAppellate Courts and District Courts existing at the time of commencement of this\nConstitution shall continue to exist until the structure of Judiciary set forth in this\nConstitution is set up.  Nothing in this Constitution shall be deemed to bar the\nsettlement by respective Courts  of the cases already filed in such Courts prior to the\ncommencement of this Constitution  and of the cases to be filed after the\ncommencement of this Constitution.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Chief Justice and Justices of the Supreme Court, Chief Judges and\nJudges of the Appellate Co urts and Judges of the District  Courts at the time of\ncommencement of this Constitution  shall be deemed to have been appointed under\nthis Constitution.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The High Courts set forth in Article 139  shall be established within one\nyear after the date of commencement of this Constitution. The Appellate Courts existing\nat the time of commencement of this Constitution  shall be dissolved after the\nestablishment of such Courts.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "After the establishment of the High Courts pursuant to clause (3), the cases\nsub judice  in the Appellate Courts shall be transferred to such High Courts as\nspecified by the Government of Nepal, in consultation with the Judicial Council, by a\nnotification in the Nepal Gazette.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "After the establishment of the High Courts pursuant to clause (3), the Chief\nJustice shall, on recommendation of the Judicial Council, post the Chief Judges and\nJudges of the Appellate Courts who are holding office at the time of commencement\nof this Constitution to the offices of the Chief Judges and Judges of the High Courts.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The Additional Judges of the Appellate Courts who are holding office at\nthe time of commencement of this Constitution may continue to hold office until the\nterm specified at the time of their appointment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The cases on criminal offences punishable by imprisonment for a term of\nmore than one year and sub judice  in any body other than a Court at the time of\ncommencement of this Constitution shall, after the commencement of this\nConstitution, be transferred to the concerned District Court.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 301", "title": "Provisions r elating to Constitutional Bodies and Officials thereof", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The\nConstitutional Bodies  which are existing at the time of commenceme nt of this\nConstitution and provided in this Constitution shall be deemed to have been formed in\naccordance with this Constitution, and nothing shall be deemed to bar the settlement\nof the matters under consideration of such Bodies subject to this Constitution.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The chiefs or officials of the  Constitutional Bodies holding office at the\ntime of commencement of this Constitution shall be deemed to have been appointed in\naccordance with this Constitution and shall continue to hold their respective offices\nsubject to the conditions of services at the time of their appointments.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The officials holding office in the Commission for the Investigation of the\nAbuse of Authority and the Public Service Commission, at the time of commencement\nof this Constitution, in excess of the number specified in this Constitution,  shall\ncontinue to hold their respective office s subject to the conditions of services at the\ntime of their appointments.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 302", "title": "Formation and Operation of Government Services at Province and Local Levels", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Government of Nepal shall make necessary provisions for the delivery of services\nat the Province and Local Levels.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Government of Nepal may, in making provisions pursuant to  clause", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": ", arrange for the delivery of services by making adjustment of the employees\nserving in the government services at the time of commencement of this Co nstitution\nwith the Federal, Provincial and Local Levels in accordance with law.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 303", "title": "Provisions r elating to Local Bodies", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Local Bodies existing at the time of\ncommencement of this Constitution shall continue to exist until the determination of\nthe number and areas of the Local Level in accordance with this Constitution.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Election to the officials of the Local Bodies existing pursuant to clause (1)\nshall be held in accordance with law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The officials of the Local Bodies elected in pursuant to  clause (2) shall\ncontinue to hold office until election to the Local Level is held in accordance with this\nConstitution.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 304", "title": "Existing Laws to Remain in Force", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Nepal laws in force at the time of\ncommencement of this Constitution shall continue to be in force until such laws are\nrepealed or amended.\nProvided that any law, which is inconsistent with this Constitution,  shall ipso\nfacto be void to the extent of such inconsistency, after one year of the date on which\nthe first session of the Federal Parliament set forth in this Constitution is held.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Acts relating to peace process in accordance with the Interim Constitution\nof Nepal, 2007 shall be deemed to be carried out in accordance with this Constitution.", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 305", "title": "Power to Remove Difficulties", "content": "In case  any difficult y arises in connection with the\nimplementation of this Constitution until the commencement of the first session of the\nFederal Parliament, upon being elected  in accordance with this Constitution , the\nPresident may, on the recommend ation of the Government of Nepal, Council of\nMinisters, issue necessary orders to remove such difficult y; and such orders  shall be\nsubmitted to the Legislature-Parliament or Federal Parliament, held immediately after\nthe issue such orders, for approval.", "children": []}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-34", "title": "Definitions and Interpretations", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 306", "title": "Definitions and I nterpretations", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Unless the subject or the context otherwise\nrequires, in this Constitution,-\n(a) \"Minority\" means ethnic, linguistic and religious groups whose\npopulation is less than the pe rcentage specified by the federal law, and\nincludes groups that have their distinct ethnic, religious or linguistic\ncharacteristics, aspirations to protect such characteristics and subjected\nto discrimination and oppression.\n(b) \"Law\" means federal law, provincial law and local law.\n(c) \"Article\" means an Article of this Constitution.\n(d) \"Municipality\" means and includes a Metropolitan City  and Sub-\nMetropolitan City.\n(e) \"Citizen\" means a citizen of Nepal.\n(f) \"Province\" means the area and form  of a federal unit of Nepal divided\ninto the federal units in accordance with this Constitution.\n(g) \"Remuneration\" means and includes salary, allowance, pension and\nany other form of emolument and facility.\n(h) \"State power\" means the power relating to th e Executive, Legislative\nand Judiciary of the State, and includes residuary power as well.\n(i) \"Bill\" means a draft of amendment to the Constitution or of an Act,\nwhich has been introduced in the Federal Parliament or a Provincial\nAssembly, as the case may be.\n(j) \"Federation\" means the federal level that is the apex unit of the federal\nstructure.\n(k) \"Federal Units\" means the Federation, Province and Local Level.\n(l) \"Constitutional Bodies\" means the Commission for the Investigation of\nAbuse of Authority, Auditor General, Public Service Commission,\nElection Commission, National Human Rights Commission, National\nNatural Resources and Fiscal Commission, National Women\nCommission, National Dalit Commission, National Inclusion\nCommission, Indige nous Nationalities Commission, Madhesi\nCommission, Tharu Commission and Muslim Commission.\n(m) \"Marginalized\" means communit ies that are made politically,\neconomically and socially backward, are unable to enjoy services and\nfacilities because of discrimination and oppression and of geographical\nremoteness or deprived thereof and are in lower status than the human\ndevelopment standards under federal law , and includes highly\nmarginalized groups and groups on the verge of extinction.\n(n) \"Local Level\" means the Rural Municipality, Municipality and District\nAssembly to be established in accordance with this Constitution.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Unless the subject or the context otherwise requires, the  legal provisions\nrelating to interpretation of laws shall, subject to the provisions of this Constitution,\napply to the interpretation of this Constitu tion in the same manner as that provisions\napply to the interpretation of the Nepal laws.", "children": []}]}]}, {"tier": 1, "nodeType": "part", "identifier": "Part-35", "title": "Short Title, Commencement and Repeal", "content": null, "children": [{"tier": 2, "nodeType": "article", "identifier": "Article 307", "title": "Short Title and Commencement", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "This Constitution may be cited as the\n“Constitution of Nepal\".", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "This Constitution shall commence on  Twenty September, Two Thousand\nFifteen A.D. (corresponding to the third day of the month of Ashwin of the year Two\nThousand Seventy Two of Bikram Era).", "children": []}]}, {"tier": 2, "nodeType": "article", "identifier": "Article 308", "title": "Repeal", "content": "The Interim Constitution of Nepal, 2007 is hereby repealed.", "children": []}]}, {"tier": 1, "nodeType": "schedule", "identifier": "Schedule-1", "title": null, "content": "(Relating to clause (2) of Article 8)\nNational Flag of Nepal\nThe method of making the National Flag of Nepal\n(a) Method of making the shape inside the border\n(1) On the lower portion of a crimson cloth draw a line AB of the required length\nfrom left to right.\n(2) From A draw a line AC perpendicular to AB making AC equal to AB plus one\nthird AB. From AC mark off D making line AD equal to line AB. Join B and\nD.\n(3) From BD mark off E making BE equal to AB.\n(4) Touching E draw a line FG, starting from the point F on line AC, and parallel\nto AB to the right hand-side. Mark off FG equal to AB.\n(5) Join C and G.\n(b) Method of making the moon\n(6) From AB mark off AH making AH equal to one -fourth of line AB and starting\nfrom H draw a line HI parallel to line AC touching line CG at point I.\n(7) Bisect CF at J and draw a line JK parallel to AB touching CG at point K.\n(8) Let L be the point where lines JK and HI cut one another.\n(9) Join J and G.\n(10) Let M be the point where line JG and HI cut one another.\n(11) With centre M and with a distance shortest from M to B D mark off N on the\nlower portion of line HI.\n(12) Touching M and starting from O, a point on AC, draw a line from left to right\nparallel to AB.\n(13) With centre L and radius LN draw a semi -circle on the lower portion and let P\nand Q be the points where it touches the line OM respectively.\n(14) With centre M and radius MQ draw a semi-circle on the lower portion touching\nP and Q.\n(15) With centre N and radius NM draw an arc touching PNQ at R and S. Join RS.\nLet T be the point where RS and HI cut one another.\n(16) With centre T and radius TS draw a semi -circle on the upper portion of PNQ\ntouching it at two points.\n(17) With centre T and radius TM draw an arc on the upper portion of PNQ\ntouching at two points.\n(18) Eight equal and similar triangles of the moon are to be made in the space lying\ninside the semi -circle of No. (16) and outside the arc of No. (17) of this\nSchedule.\n(c) Method of making the sun\n(19) Bisect line AF at U, and draw a line UV parallel to AB line touching line BE at\nV.\n(20) With centre W, the point where HI and UV cut one another and radius MN\ndraw a circle.\n(21) With centre W and radius LN draw a circle.\n(22) Twelve equal and similar triangles of the sun are to be made in the space\nenclosed by the circles of No. (20) and of No. (21) with t he two apexes of two\ntriangles touching line HI.\n(d) Method of making the border\n(23) The width of the border will be equal to the width TN. This will be of deep blue\ncolour and will be provided on all the side of the flag. However, on the five\nangles of the flag the external angles will be equal to the internal angles.\n(24) The above-mentioned border will be provided in case the flag is to be used with\na rope. On the other hand, in case it is to be hoisted on a pole, the hole on the\nborder on the side AC can be extended in accordance with requirements.\nExplanation: The lines HI, RS, FE, ED, JG, OQ, JK and UV are imaginary. Similarly,\nthe external and internal circles of the sun and the other arcs except the crescent moon\nare also imaginary. These are not shown on the flag.\nNote: The size of the National Flag of Nepal shall be as  determined by the Government of\nNepal.", "children": []}, {"tier": 1, "nodeType": "schedule", "identifier": "Schedule-2", "title": null, "content": "(Relating to clause (1) of Article 9)\nNational Anthem of Nepal\nSayaun Thunga Phool Ka Hami Eutai Mala Nepali\nSarvavhaum Vai Failiyeka Mechi Mahakali\nPrakitika Koti Koti Sampada Ko Aanchala\nBir Haruka Ragata Le Swatantra Ra Atala\nGyana Bhumi Shanti Bhumi Terai Pahad Himala\nAkhanda Yo Pyaro Hamro Matri Bhumi Nepal\nBahul Jati Bhasa Dharma Sanskriti Chan Bishala\nAgragami Rastra Hamro Jaya Jaya Nepal.", "children": []}, {"tier": 1, "nodeType": "schedule", "identifier": "Schedule-3", "title": null, "content": "(Relating to clause (2) of Article 9)\nCoat of Arms of Nepal\nNote: This Coat of Arms may be made in larger or smaller size as may be necessary.\nThe colours determined by the Government of Nepal shall be used on it.\nAmended by the Second Amendment.", "children": []}, {"tier": 1, "nodeType": "schedule", "identifier": "Schedule-4", "title": null, "content": "(Relating to clause (3) of Article 56)\nProvinces, and Districts to be included in the concerned Provinces\nProvince No. 1 Province No. 2\n1. Taplejung\n2. Panchthar\n3. Ilam\n4. Sankhuwasabha\n5. Tehrathum\n6. Dhankuta\n7. Bhojpur\n8. Khotang\n9. Solukhumbu\n10. Okhaldhunga\n11. Udayapur\n12. Jhapa\n13. Morang\n14. Sunsari\n1. Saptari\n2. Siraha\n3. Dhanusa\n4. Mahottari\n5. Sarlahi\n6. Rautahat\n7. Bara\n8. Parsa\nProvince No. 3 Province No. 4\n1. Dolakha\n2. Ramechhap\n3. Sindhuli\n4. Kavrepalanchok\n5. Sindhupalchok\n6. Rasuwa\n7.Nuwakot\n8. Dhading\n9. Chitwan\n10. Makawanpur\n11. Bhaktapur\n12. Lalitpur\n13. Kathmandu\n1. Gorkha\n2. Lamjung\n3. Tanahun\n4. Kaski\n5. Manang\n6. Mustang\n7. Parbat\n8. Syangja\n9. Myagdi\n10. Baglung\n11.Nawalparasi (East of Bardaghat\nSusta)\nProvince No. 5 Province No. 6 Province No. 7\n1.Nawalparasi (West of\nBardaghat Susta)\n2. Rupandehi\n3. Kapilbastu\n4. Palpa\n5. Arghakhanchi\n6. Gulmi\n7. Rukun (Eastern Part)\n8. Rolpa\n9. Pyuthan\n10. Daang\n11. Banke\n12. Bardiya\n1.Rukum (Western Part)\n2. Salyan\n3. Dolpa\n4. Jumla\n5. Mugu\n6. Humla\n7. Kalikot\n8. Jajarkot\n9. Dailekh\n10. Surkhet\n1.Bajura\n2.Bajhang\n3. Doti\n4. Achham\n5. Darchula\n6. Baitadi\n7. Dadeldhura\n8. Kanchanpur\n9. Kailali", "children": []}, {"tier": 1, "nodeType": "schedule", "identifier": "Schedule-5", "title": null, "content": "(Relating to clause (1) of Article 57, and Article 109)\nList of Federal Powers\nS.N. Matters\n1. Relating to defence and military\n(a) Protection of national unity and territorial integrity\n(b) Relating to national security\n2. War and defence\n3. Arms and ammunitions factories and production thereof\n4. Central Police, Armed Police Force, national intelligence and investigation, law\nand order.\n5. Central planning, central bank, fina ncial policies, monetary and banking,\nmonetary policies, foreign grants, aid and loans\n6. Foreign and diplomatic affairs, international relations and United Nations related\nmatters\n7. International treaties or agreements, extradition, mutual legal assistance and\ninternational borders, international boundary rivers\n8. Telecommunications, allocation of radio frequency, radio, television and post al\nmatters\n9. Customs, excise-duty, value-added tax, corporate income tax, individual income\ntax, remuneration tax, passport fee, visa fee, tourism fee, service charge and  fee,\npenalty\n10. Federal civil service, judicial service and other government services\n11. Policies relating to conservation and multiple uses of water resources\n12. Inland and inter-Province electricity transmission lines\n13. Central statistics (national and international standards and quality)\n14. Central level large electricity, irrigation and other projects\n15. Central universities, central level academies, universities standards and\nregulation, central libraries\n16. Health policies, health services, health standards, quality and monitoring, national\nor specialised service providing hospitals , traditional treatment services and\ncommunicable disease control\n17. Federal Parliament, Federal Executive, Local Level  related affairs, special\nstructure\n18. International trade, exchange, port, quarantine\n19. Civil aviation, international airports\n20. National transportation policies, management of railways and national highways\n21. Laws relating to the Supreme Court, High Courts, District Courts and\nadministration of justice\n22. Citizenship, passport, visa, immigration\n23. Atomic energy, air space and astronomy\n24. Intellectual property (including patents, designs, trademarks and copyrights)\n25. Measurement\n26. Mines excavation\n27. National and international environment management, national parks, wildlife\nreserves and wetland, national forest policies, carbon services\n28. Insurance policies, securities, cooperatives regulation\n29. Land use policies, human settlement development policies, tourism policies,\nenvironment adaptation\n30. Enactment of Criminal and civil laws\n31. Security printing\n32. Social security and poverty alleviation\n33. Constitutional Bodies, Commissions of national importance\n34. Sites of archaeological importance and ancient monuments\n35. Any matter not enumerated in the Lists of Federal Powers, Province Powers and\nLocal Level Powers or in the Concurrent List and any matter not specified in this\nConstitution and in federal laws", "children": []}, {"tier": 1, "nodeType": "schedule", "identifier": "Schedule-6", "title": null, "content": "(Relating to clause (2) of Article 57, clause (4) of Article 162, Article 197, clause (3) of\nArticle 231, clause (7) of Article 232, clause (4) of Article 274 and clause (4) of Article\n296)\nList of Provincial Powers\nS.N. Matters\n1. Provincial police administration and law and order\n2. Operation of b anks and financial institutions  in accordance with the policies of\nNepal Rastra Bank , cooperative institutions, foreign grants and assistance with the\nconsent of the Centre\n3. Operation of Radio, F.M., television\n4. Housing and land registration fee , motor vehicle tax , entertainment  tax,\nadvertisement tax, tax on tourism, agro-income, service charge, fee, penalty\n5. Provincial civil service and other government services\n6. Provincial statistics\n7. Province level electricity, irrigation and water supply services, navigation\n8. Provincial universities, higher education, libraries, museums\n9. Health services\n10. Matters relating to the Provincial Assembly, Provincial Council of Ministers\n11. Intra-Province trade\n12. Provincial highways\n13. Provincial Bureau of Investigation\n14. Physical management and other necessary matters of Provincial governmental\noffices\n15. Provincial Public Service Commission\n16. Management of land, land records\n17. Exploration and management of mines\n18. Protection and use of languages, scripts, cultures, fine arts and religions\n19. Use of forests and waters and management of environment within the Province\n20. Agriculture and livestock development, factories, industrialization, trade, business,\ntransportation\n21. Management of trusts (Guthi)", "children": []}, {"tier": 1, "nodeType": "schedule", "identifier": "Schedule-7", "title": null, "content": "(Relating to clause (3) of Articles 57, Article 109, clause (4) of Article 162, and Article\n197)\nList of Concurrent Powers of Federation and Province\nS.N. Matters\n1. Civil and criminal procedure, evidence and oaths ( legal recognition,  public acts and\nrecords, and judicial proceedings)\n2. Supply, distribution, price control, quality and monitoring of essential goods  and\nservices\n3. Preventive detention for reasons connected with the security of the country, prison and\ndetention management, and maintenance of peace and order\n4. Transfer of accused persons, detainees and prisoners  from one Province to another\nProvince\n5. Laws relating to family affairs (marriage, transfer of property, divorce, persons on the\nverge of extinction, orphan, adoption, succession and joint family)\n6. Acquisition, requisitioning of property and creation of right in property\n7. Contracts, cooperatives, partnership and agency related matters\n8. Matters relating to bankruptcy and insolvency\n9. Drugs and pesticides\n10. Planning, family planning and population management\n11. Social security and employment, trade unions, settlement of industrial disputes, labour\nrights and disputes related matters\n12. Legal profession, auditing, engineering, medicines, Ayurvedic medicines, veterinary,\nAmchi and other professions\n13. Provincial boundary river, waterways, environment protection, biological diversity\n14. Matters related to means of communication\n15. Industries and mines and physical infrastructures\n16. Casino, lottery\n17. Preparedness for, rescue and  relief during, and recovery from, natural and non-natural\ndisasters.\n18. Tourism, water supply and sanitation\n19. Motion pictures, cinema halls and sports\n20. Insurance business operation and management\n21. Poverty alleviation and industrialization\n22. Scientific research, science and technology and human resources development\n23. Utilization of forests, Himalayan ( mountains), forest conservation areas and waters\nstretching in inter-provincial form\n24. Land policies and laws relating thereto\n25. Employment and unemployment benefit", "children": []}, {"tier": 1, "nodeType": "schedule", "identifier": "Schedule-8", "title": null, "content": "(Relating to clause (4) of Article 57, clause (2) of Article 214, clause (2) of Article 221\nand clause (1) of Article 226)\nList of Local Level Powers\nS.N. Matters\n1. Town police\n2. Cooperative institutions\n3. Operation of F.M.\n4. Local taxes ( property tax, house rent tax, land and building registration fee, motor\nvehicle tax), service charge, fee, tourism fee, advertisement tax , business tax, land\ntax (land revenue), penalty, entertainment tax, land revenue collection\n5. Management of the Local services\n6. Collection of local statistics and records\n7. Local Level development plans and projects\n8. Basic and secondary education\n9. Basic health and sanitation\n10. Local market management, environment protection and bio-diversity\n11. Local roads, rural roads, agro-roads, irrigation\n12. Rural Municipal Assembly , Municipal Assembly, District Assembly, local courts,\nmanagement of mediation and arbitration\n13. Local records management\n14. Distribution of house and land ownership certificates\n15. Agriculture and animal husbandry , agro -products management, animal health,\ncooperatives\n16. Management of senior citizens, persons with disabilities and the incapacitated\n17. Collection of statistics of the unemployed\n18. Management, operation and control of agricultural extension\n19. Water supply, small hydropower projects, alternative energy\n20. Disaster management\n21. Conservation of watersheds, wildlife, mines and minerals\n22. Protection and development of languages, cultures and fine arts", "children": []}, {"tier": 1, "nodeType": "schedule", "identifier": "Schedule-9", "title": null, "content": "(Relating to clause (5) of Article 57, Article 109, clause (4) of Article 162, Article 197,\nclause (2) of Article 214, clause (2) of Article 221, and clause (1) of Article 226)\nList of Concurrent Powers of Federation, Province and Local Level\nS.N. Matters\n1. Cooperatives\n2. Education, sports and newspapers\n3. Health\n4. Agriculture\n5. Services such as electricity, water supply, irrigation\n6. Service fee, charge, penalty and royalty from natural resources, tourism fee\n7. Forests, wildlife, birds, water uses, environment, ecology and bio-diversity\n8. Mines and minerals\n9. Disaster management\n10. Social security and poverty alleviation\n11. Personal events, births, deaths, marriages and statistics\n12. Archaeology, ancient monuments and museums\n13. Squatters management\n14. Royalty from natural resources\n15. Motor vehicle permits", "children": []}]$CODEx5eadb276c96f$::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,"originalTitle"=EXCLUDED."originalTitle","documentType"=EXCLUDED."documentType","yearBs"=EXCLUDED."yearBs","yearAd"=EXCLUDED."yearAd","totalPages"=EXCLUDED."totalPages",nodes=EXCLUDED.nodes;
